FS = 500.0                 # 標本化周波数 [Hz]
HR_SYN = 70.0              # 心拍数 [1/min]。拍長 T = 60 / HR
TP_F = 0.12                # 前進波のピークの目安 [s]
A_FWD, SIG_FWD, AL_FWD = 1.0, 0.045, 2.5     # 前進波（歪みガウス）の高さ・幅・歪度
A_REF = 0.45               # 反射波の高さ
W_REF_A, W_REF_B = 0.055, 0.16   # 反射波の幅 = W_REF_A + W_REF_B × 到達 [s]
AL_REF = 1.2               # 反射波の歪度（早く到達する拍では 0 にする）
DT_SKEW = 0.18             # 到達がこれ以下なら歪度 0（硬い血管の、幅が広く対称な反射波）
D_RES = 0.45               # 貯留槽の大きさ
RES_PEAK_LAG = 0.05        # 貯留槽が減衰に入る時刻 = 前進波のピーク + 到達 + これ [s]
RES_MAX_FRAC = 0.55        # ただし拍長のこの割合を超えない
NOISE_SD = 0.002           # 雑音の標準偏差

# 当てはめの型。(鍵, 番号, 表の見出し, 説明)
# 番号は波形の型（klass_own）と混ざらないよう括弧付きで書く。(5)(6) は形の拘束・
# 打ち切りに加えて Δμ の下限も 0.01 s に緩めてある（2 つ変わっている）。
# (5b)(6b) は同じ拘束・打ち切りで Δμ の下限を凍結版のまま 0.08 s にした版で、
# **一度に 1 つだけ変えたときの効き**を読むために 2026-09-15 に足した。
# (4b) と (0) も 2026-09-15 に足した。(4b) は「Δμ を緩める・貯留槽を畳み込みで持つ、の
# 2 つをそれぞれと同時に適用したときの結果を出すのか」に答えるための行で、(2) と (4) を
# 同時に適用したものである。(0) は `src/pda.py` の `fit_beat` をそのまま呼ぶ行で、
# 写した複製 (1) が本体と同じ振る舞いをすることの照合である。
# (1) 以降の起点の作り方と解の選び方は `fit_beat` と同じにしてある（2026-09-15 に
# そろえた。lab_log 追記143）。各行が凍結版から**狙った 1 つだけ**違うようにするため。
#
# (6c) 0.55T・(6d) 0.75T は 2026-09-15 に足した（lab_log 追記145）。**主とする打ち切りの
# 割合は 0.65T で、これは事前に決めた値である**（24番・lab_log 追記139 で、実データの
# 結果を見る前に固定した）。(6c)(6d) は**結論が割合の選び方に敏感でないことを示す記述
# （感度の確認）のためだけ**にあり、**この 3 つの数値を見てから主の割合を選び直さない。**
# 0.55T や 0.75T のほうが良く出ても「0.65T でも同じ向きの結果が出る」という記述に留め、
# 主の割合は 0.65T と書く。割合を変えるなら新しい事前登録で決める。(6b)(6c)(6d) は Δμ の
# 下限をどれも凍結版のまま 0.08 s にしてあり、**割合だけが違う 3 行**である。
#
# (4c) は 2026-09-16 に足した（lab_log 追記146）。**(4) と違うのは貯留槽の時定数 τ の
# 探索範囲の下限だけ**（0.05 s → 0.15 s）で、g の上限・τ の上限・起点・Δμ の下限・解の
# 選び方は (4) と同じである。理由は `RES_TAU_LO_OF` の注記に書いた縮退で、**(4)(4b) は
# 下限 0.05 s のまま**にしてあるから、(4) と (4c) は一度に 1 つだけ違う。
#
# (6e)(7)(8)(9) は 2026-09-16 に足した（**走らせる前に設計を固定した**。lab_log 追記149）。
# 凍結版は PPG(t) = g1(t) + g2(t)（圧に似た 2 つの波の和）を仮定するが、PWDB の指尖 PPG は
# **末梢 Windkessel の容積**（Charlton 2019 式 A1）であり、波の和を低域通過させて長い指数の
# 裾を付けた量である。模型にはその裾を受け持つ要素が無いので、第2成分が裾に引かれる
# （型3 で +98.5 ms）。(4) はその裾を**前進波だけの畳み込みを足す**形で入れたが、核が単位
# 面積なので τ → 0 で核が δ 関数に近づき、第1成分の定数倍の複製に縮退した。(7)(8)(9) は
# 同じ問題に、縮退する向きを持たない 3 通りの当て方で向かう。
#   (7) 和の全体に畳み込みを掛けて**置き換える**（足さない）。**τ → 0 は凍結版そのもの**
#       なので入れ子であり、縮退する向きが無い。倍率 g を持たない（核が単位面積なので
#       高さは a1・a2 が担う）。**ΔT・RI は畳み込む前の g1・g2 のピークから出す。**
#   (8) 当てはめの型は変えず、**当てる前に波形を戻す**。拡張期の後ろ 30% から τ を推定し、
#       y = h_τ ⊛ x の逆 x(t) = y(t) + τ·y′(t) で戻してから凍結版をそのまま当てる。
#   (9) 残差を 1 次微分の領域で取る（追記139 の候補 (3) の後半。打ち切りの側だけを試して
#       微分の側は試していなかった）。裾は微分すると小さくなるので第2成分が引かれにくい。
#   (6e) 打ち切る位置を割合ではなく**絶対時間**で決める（W1 の検査）。0.65T のような割合で
#       切ると**切る時刻そのものが心拍数の関数になる**ので、心拍数に依らない切り方でも
#       同じ向きの結果が出るかを見る。**主の切り方は 0.65T のままで動かさない。**
# **留保**: PWDB の指尖 PPG はまさに (7) の形で作られているので、in silico では (7) に
# 有利に働く。実波形での検証が済むまで「PWDB で良かった」以上のことは書かない。
