    print(f"    **主とする割合は {TRUNC_FRAC:.2f}T で、これは事前に決めた値である**"
          "（24番・lab_log 追記139。実データの結果を見る前に固定した）。")
    print("    (6c)(6d) は結論が割合の選び方に敏感でないことを示す記述（感度の確認）の"
          "ためだけにあり、")
