def _colv(d: pd.DataFrame, c: str) -> np.ndarray:
    if c not in d.columns:
        return np.full(len(d), np.nan)
    return pd.to_numeric(d[c], errors="coerce").to_numpy(dtype=float)


def stage_a(d: pd.DataFrame) -> pd.DataFrame:
    """26番の A 段（ok_v1 == 1）。列が無ければそのまま返す（C 段と同じになる）。"""
    if COL_OK not in d.columns:
        return d
    return d[pd.to_numeric(d[COL_OK], errors="coerce") == 1]


def subset(d: pd.DataFrame, k: int) -> pd.DataFrame:
    return d[_colv(d, KLASS_COL) == float(k)]


def missing_cols(d: pd.DataFrame) -> list:
    return [c for c in NEED_B if c not in d.columns]


def dist_of(d: pd.DataFrame, col: str) -> dict:
    """1 列の分布（人数・最小・パーセンタイル・最大）。"""
    v = _colv(d, col)
    v = v[np.isfinite(v)]
    out = {"n": int(v.size), "min": float("nan"), "max": float("nan"),
           "p": dict((q, float("nan")) for q in PCTS)}
    if v.size:
        out["min"], out["max"] = float(np.min(v)), float(np.max(v))
        out["p"] = dict((q, float(np.percentile(v, q))) for q in PCTS)
    return out


def floor_bins(d: pd.DataFrame) -> dict:
    """特徴点法 ΔT を BIN_MS 刻みの区間に分け、区間ごとの凍結版 ΔT を要約する。

    対応のある行（両方が有限）だけを使う。返り値の `bins` は区間の下端をキーにした
    辞書で、下端の小さい順に並べれば「特徴点法が短い区間で凍結版が下がるか」が読める。
    """
    x, y = _colv(d, COL_LM), _colv(d, COL_V1)
    g = np.isfinite(x) & np.isfinite(y)
    x, y = x[g], y[g]
    out = {"n": int(x.size), "bins": [], "v1_min": float("nan"),
           "v1_p5": float("nan"), "lm_min": float("nan")}
    if x.size == 0:
        return out
    out["v1_min"] = float(np.min(y))
    out["v1_p5"] = float(np.percentile(y, 5))
    out["lm_min"] = float(np.min(x))
    idx = np.floor(x / BIN_MS).astype(int)
    for b in np.unique(idx):
        sel = idx == b
        v = y[sel]
        q1, q3 = (float(q) for q in np.percentile(v, [25, 75]))
        out["bins"].append({"lo": float(b) * BIN_MS, "hi": float(b + 1) * BIN_MS,
                            "n": int(sel.sum()), "med": float(np.median(v)),
                            "q1": q1, "q3": q3,
                            "lm_med": float(np.median(x[sel]))})
    return out


def rho_rows(d: pd.DataFrame, half=None, xcol: str = COL_V1, ycol: str = COL_LM) -> list:
    """年齢層ごとの (年齢, ρ(xcol, ycol), n)。既定は ΔT（dt_v1_ms・dt_lm_ms）。

    `half` が "short"／"long" のときは、**その年齢層の** `ycol` の中央値で二分した
    片側だけを使う（層をまたいだ中央値で切ると年齢と混ざる）。ρ は 20番の `_spearman`
    （対応のある行だけ・1 層 MIN_PER_AGE 名以上）。B4 は xcol・ycol に RI の列を渡す。
    """
    out = []
    if "age" not in d.columns or len(d) == 0:
        return out
    for age, g in d.groupby("age", sort=True):
        x, y = _colv(g, xcol), _colv(g, ycol)
        keep = np.isfinite(x) & np.isfinite(y)
        if half is not None and int(keep.sum()) >= 2:
            thr = float(np.median(y[keep]))
            keep = keep & ((y <= thr) if half == "short" else (y > thr))
        r, n = M._spearman(x[keep], y[keep], min_n=MIN_PER_AGE)
        out.append((float(age), r, int(n)))
    return out


def strat(rows: list, sign: int = 1) -> dict:
    """年齢層をまたいだまとめ。中央値・向きの層数は 20番の `_judge` に任せる。"""
    fin = [(a, r, n) for a, r, n in rows if np.isfinite(r)]
    j = M._judge(rows, sign) if rows else None
    return {"rows": rows,
            "med": float(np.median([r for _a, r, _n in fin])) if fin else float("nan"),
            "med_abs": j["med_abs"] if j else float("nan"),
            "n_ok": j["n_ok"] if j else 0,
            "n_ages": j["n_ages"] if j else 0,
            "min_n": min(n for _a, _r, n in fin) if fin else 0,
            "n_tot": int(sum(n for _a, _r, n in fin))}


def print_b1(d: pd.DataFrame, klasses) -> dict:
    """B1 型ごとの ΔT の分布。"""
    print("\n" + "-" * 100)
    print("B1. 型ごとの ΔT の分布（凍結版と特徴点法。単位 ms）")
    print("-" * 100)
    print("  段 A は 26番の A 段（ok_v1 == 1。凍結版が自分で採用した例）、段 C は採否を"
          "無視した全例。")
    out = {}
    for k in klasses:
        g = subset(d, k)
        ga = stage_a(g)
        print(f"\n  {KLASS_LABEL.get(k, f'型{k}')}  n = {len(g)} 名（A 段 {len(ga)} 名）")
        if len(g) == 0:
            print("    該当なし")
            continue
        print("    " + _pad("列", 12) + _pad("段", 4) + _pad("n", 7, right=True)
              + _pad("最小", 8, right=True)
              + "".join(_pad(f"p{q}", 8, right=True) for q in PCTS)
              + _pad("最大", 8, right=True))
        for col in (COL_V1, COL_LM):
            for stg, gg in (("A", ga), ("C", g)):
                s = dist_of(gg, col)
                out[(k, col, stg)] = s
                print("    " + _pad(col, 12) + _pad(stg, 4) + _pad(s["n"], 7, right=True)
                      + _f(s["min"], 8, prec=1)
                      + "".join(_f(s["p"][q], 8, prec=1) for q in PCTS)
                      + _f(s["max"], 8, prec=1))
    print("\n  出典: この台本（50番）の節B が CSV の既存列から計算した値。"
          "**新しい当てはめはしていない。**")
    return out


def print_b2(d: pd.DataFrame, klasses) -> dict:
    """B2 下限の検査（特徴点法 ΔT の区間ごとに凍結版 ΔT を並べる）。"""
    print("\n" + "-" * 100)
    print(f"B2. 下限の検査: 特徴点法 ΔT を {BIN_MS:.0f} ms 刻みの区間に分け、区間ごとの"
          " 凍結版 ΔT（A 段）")
    print("-" * 100)
    print("  特徴点法 ΔT が短い区間でも凍結版 ΔT の中央値が下がらなければ、凍結版は下限で"
          "詰まっている。")
    print("  対応のある行（両方が有限）だけを使う。")
    out = {}
    for k in klasses:
        g = stage_a(subset(d, k))
        res = floor_bins(g)
        out[k] = res
        print(f"\n  {KLASS_LABEL.get(k, f'型{k}')}  対応のある行 {res['n']} 名（A 段）")
        if res["n"] == 0:
            print("    対応のある行が無い")
            continue
        print("    " + _pad("特徴点法 ΔT の区間", 22) + _pad("人数", 7, right=True)
              + _pad("凍結版 ΔT 中央値", 18, right=True)
              + _pad("四分位範囲", 22, right=True)
              + _pad("特徴点法 ΔT 中央値", 20, right=True))
        for b in res["bins"]:
            iqr = f"[{b['q1']:.1f}〜{b['q3']:.1f}]"
            print("    " + _pad(f"[{b['lo']:.0f}, {b['hi']:.0f})", 22)
                  + _pad(b["n"], 7, right=True) + _f(b["med"], 18, prec=1)
                  + _pad(iqr, 22, right=True) + _f(b["lm_med"], 20, prec=1))
        print(f"    凍結版 ΔT の最小 {_n(res['v1_min'], 1)} ms・下位 5% "
              f"{_n(res['v1_p5'], 1)} ms（特徴点法 ΔT の最小は "
              f"{_n(res['lm_min'], 1)} ms）。")
        print(f"    探索範囲の下限 Δμ {DMU_LO_FROZEN} s（＝ {DMU_LO_MS:.0f} ms）との差は "
              f"{_n(res['v1_min'] - DMU_LO_MS, 1, sign=True)} ms・"
              f"{_n(res['v1_p5'] - DMU_LO_MS, 1, sign=True)} ms。")
    print("\n  Δμ は母数（μ2 − μ1）の下限で、ΔT は成分のピーク間隔である。歪みがあると")
    print("  ピークは μ からずれるので、ΔT が 80 ms を下回ることはありうる。80 ms は")
    print("  それでも目安になる（下限より下には母数を動かせない）。")
    print("  出典: この台本（50番）の節B が CSV の既存列から計算した値。")
    return out


def print_b3(d: pd.DataFrame, klasses) -> dict:
    """B3 型ごとの ρ(dt_v1_ms, dt_lm_ms) と、特徴点法 ΔT の短い側・長い側。"""
    print("\n" + "-" * 100)
    print("B3. 型ごとの ρ(dt_v1_ms, dt_lm_ms)（年齢層内 Spearman の中央値。符号つき）")
    print("-" * 100)
    print(f"  層は `age` の相異なる値、1 層 {MIN_PER_AGE} 名以上（20番の `_spearman`）。")
    print("  短い側・長い側は**年齢層ごとに**その層の dt_lm_ms の中央値で二分した半数で、")
    print("  半数それぞれにも 1 層 8 名以上を要求する（足りない層は数えない）。")
    print("  下限で詰まっているなら、短い側で ρ が落ちる。")
    print("    " + _pad("型", 20) + _pad("段", 4) + _pad("ρ 全体", 13, right=True)
          + _pad("ρ 短い側", 13, right=True) + _pad("ρ 長い側", 13, right=True)
          + _pad("差 長−短", 11, right=True) + _pad("層", 5, right=True)
          + _pad("最小n", 8, right=True))
    out = {}
    for k in klasses:
        g = subset(d, k)
        for stg, gg in (("A", stage_a(g)), ("C", g)):
            s_all = strat(rho_rows(gg))
            s_sh = strat(rho_rows(gg, half="short"))
            s_lg = strat(rho_rows(gg, half="long"))
            gap = s_lg["med"] - s_sh["med"]
            out[(k, stg)] = {"all": s_all, "short": s_sh, "long": s_lg, "gap": gap}
            lab = KLASS_SHORT.get(k, f"型{k}")
            print("    " + _pad(lab, 20) + _pad(stg, 4)
                  + _f(s_all["med"], 13, prec=3, sign=True)
                  + _f(s_sh["med"], 13, prec=3, sign=True)
                  + _f(s_lg["med"], 13, prec=3, sign=True)
                  + _f(gap, 11, prec=3, sign=True)
                  + _pad(s_all["n_ages"], 5, right=True)
                  + _pad(s_all["min_n"] or "—", 8, right=True))
    print("  「層」「最小n」は ρ 全体のもの。短い側・長い側は人数が半分になるので、"
          "層が減ることがある。")
    print("  出典: この台本（50番）の節B が CSV の既存列から計算した値。")
    return out


def print_b4_ri(d: pd.DataFrame, klasses) -> dict:
    """B4 型ごとの ρ(ri_v1, digital_ri) を年齢層ごとに 1 行ずつ。

    規約は 48番・B3 と同じ（20番の `_spearman`・1 層 MIN_PER_AGE 名以上・層は `age` の
    相異なる値）。凍結版の RI は A 段（ok_v1 == 1）を主とし、C 段（採否を無視した全例）を
    同じ行に並べる。**新しい当てはめはしない**（既存列を読むだけ）。
    """
    print("\n" + "-" * 100)
    print("B4. 型ごとの ρ(ri_v1, digital_ri)（年齢層ごとに 1 行。符号つき）")
    print("-" * 100)
    miss = [c for c in NEED_B4 if c not in d.columns]
    if miss:
        print(f"  ★ 列が無い: {miss}。B4 と予測 P4・P5 は計算できない。")
        return {}
    print(f"  層は `age` の相異なる値、1 層 {MIN_PER_AGE} 名以上。A 段は ok_v1 == 1、")
    print("  C 段は採否を無視した全例。対応のある行（両方が有限）だけを使う。")
    out = {}
    for k in klasses:
        g = subset(d, k)
        rows_a = rho_rows(stage_a(g), xcol=COL_RI_V1, ycol=COL_RI_LM)
        rows_c = rho_rows(g, xcol=COL_RI_V1, ycol=COL_RI_LM)
        s_a, s_c = strat(rows_a), strat(rows_c)
        out[k] = {"A": s_a, "C": s_c}
        print(f"\n  {KLASS_LABEL.get(k, f'型{k}')}  n = {len(g)} 名（A 段 {len(stage_a(g))} 名）")
        if not rows_c:
            print("    該当なし")
            continue
        print("    " + _pad("年齢層", 10, right=True) + _pad("A段 n", 10, right=True)
              + _pad("A段 ρ", 12, right=True) + _pad("C段 n", 10, right=True)
              + _pad("C段 ρ", 12, right=True))
        d_a = dict((a, (r, n)) for a, r, n in rows_a)
        for age, r_c, n_c in rows_c:
            r_a, n_a = d_a.get(age, (float("nan"), 0))
            print("    " + _pad(f"{age:.0f}", 10, right=True)
                  + _pad(n_a or "—", 10, right=True) + _f(r_a, 12, prec=3, sign=True)
                  + _pad(n_c or "—", 10, right=True) + _f(r_c, 12, prec=3, sign=True))
        print("    " + _pad("中央値", 10, right=True) + _pad("", 10)
              + _f(s_a["med"], 12, prec=3, sign=True) + _pad("", 10)
              + _f(s_c["med"], 12, prec=3, sign=True)
              + f"  （評価できた層 A {s_a['n_ages']}・C {s_c['n_ages']}）")
    print("\n  出典: この台本（50番）の節B が CSV の既存列から計算した値。"
          "**新しい当てはめはしていない。**")
    return out


def _iqr_of(v: np.ndarray) -> dict:
    """1 群ぶんの 人数・中央値・四分位（25・75）・四分位範囲の幅。有限な値だけを使う。"""
    v = np.asarray(v, float)
    v = v[np.isfinite(v)]
    out = {"n": int(v.size), "med": float("nan"), "q1": float("nan"),
           "q3": float("nan"), "iqr": float("nan")}
    if v.size:
        out["med"] = float(np.median(v))
        out["q1"], out["q3"] = (float(q) for q in np.percentile(v, [25, 75]))
        out["iqr"] = out["q3"] - out["q1"]
    return out


def print_b6(d: pd.DataFrame, klasses) -> dict:
    """B6 型 × 年齢層で、真値（PWV_a・pvr）そのもののばらつきを並べる。

    **2026-09-15 に、型1 の関連がどの手法でも低いのを見たあとで足した記述の表である。
    予測は立てていない**（lab_log 追記145）。判定にも使わない。

    C 段（採否を無視した全例）で出す。真値の散らばりはその層にどういう被験者がいるかの
    性質であって、当てはめの性質ではないからである。`PWV_a`・`pvr` の列が無い CSV では
    1 行だけ印字して飛ばす。
    """
    print("\n" + "-" * 100)
    print(f"B6. 真値そのもののばらつき: 型 × 年齢層の {COL_PWV}・{COL_PVR}"
          "（中央値・四分位範囲とその幅。C 段）")
    print("-" * 100)
    print("  **2026-09-15 に、型1 の弱さを見たあとで足した記述の表である。予測は立てて"
          "いない。**")
    print("  段は C 段（採否を無視した全例）だけである。真値の散らばりはその層にどういう")
    print("  被験者がいるかの性質であって、当てはめの性質ではない（A 段に絞る意味がない）。")
    miss = [c for c in NEED_B6 if c not in d.columns]
    if miss:
        print(f"  ★ 列が無い: {miss}。B6 は計算できない（真値の列が要る）。")
        return {}
    print(f"  層は `age` の相異なる値で、その型に {MIN_PER_AGE} 名以上いる層だけを出す。")
    print("  中央値・四分位範囲は有限な値だけで計算する。")
    ks = [k for k in klasses if k in B6_KLASSES]
    out = {}
    for k in ks:
        g = subset(d, k)
        print(f"\n  {KLASS_LABEL.get(k, f'型{k}')}  n = {len(g)} 名（C 段）")
        if len(g) == 0 or "age" not in g.columns:
            print("    該当なし")
            out[k] = {"rows": [], "n": len(g), "n_ages": 0, "min_n": 0,
                      "iqr_med": dict((c, float("nan")) for c in NEED_B6)}
            continue
        rows, short, lines = [], [], []
        for age, gg in g.groupby("age", sort=True):
            if len(gg) < MIN_PER_AGE:
                short.append((float(age), len(gg)))
                continue
            rec = {"age": float(age), "n": int(len(gg))}
            line = ("    " + _pad(f"{float(age):.0f}", 8, right=True)
                    + _pad(len(gg), 7, right=True))
            for c in NEED_B6:
                s = _iqr_of(_colv(gg, c))
                rec[c] = s
                iqr = ("—" if not np.isfinite(s["q1"])
                       else f"[{s['q1']:.3f}〜{s['q3']:.3f}]")
                line += (_f(s["med"], 15, prec=3) + _pad(iqr, 24, right=True)
                         + _f(s["iqr"], 12, prec=3))
            rows.append(rec)
            lines.append(line)
        if rows:
            print("    " + _pad("年齢層", 8, right=True) + _pad("n", 7, right=True)
                  + "".join(_pad(f"{c} 中央値", 15, right=True)
                            + _pad(f"{c} 四分位範囲", 24, right=True)
                            + _pad(f"{c} 幅", 12, right=True) for c in NEED_B6))
            for line in lines:
                print(line)
        else:
            print(f"    {MIN_PER_AGE} 名以上の年齢層が無い")
        med = dict((c, float(np.median([r[c]["iqr"] for r in rows
                                        if np.isfinite(r[c]["iqr"])]))
                    if any(np.isfinite(r[c]["iqr"]) for r in rows) else float("nan"))
                   for c in NEED_B6)
        n_ages = len(rows)
        min_n = min((r["n"] for r in rows), default=0)
        out[k] = {"rows": rows, "n": len(g), "n_ages": n_ages, "min_n": min_n,
                  "iqr_med": med, "short": short}
        print("    " + _pad("幅の中央値", 15) + "・".join(
            f"{c} {_n(med[c], 3)}" for c in NEED_B6)
            + f"（層をまたいだ中央値。{n_ages} 層）")
        print(f"    {MIN_PER_AGE} 名以上の年齢層 {n_ages} / {N_AGES_FULL}"
              f"・最小の層 n = {min_n if n_ages else '—'}"
              + (f"（{MIN_PER_AGE} 名に満たない層: "
                 + "・".join(f"{a:.0f}歳 {n} 名" for a, n in short) + "）" if short else ""))
        n_part = [(r["age"], c, r[c]["n"], r["n"]) for r in rows for c in NEED_B6
                  if r[c]["n"] < r["n"]]
        if n_part:
            print("    ★ 真値が欠測の行がある層: "
                  + "・".join(f"{a:.0f}歳 {c} {nf}/{nt}" for a, c, nf, nt in n_part))

    # まとめ（層をまたいだ 幅 の中央値と、型1 ÷ 型3 の比）
    print("\n  まとめ（層をまたいだ 四分位範囲の幅 の中央値。C 段）")
    print("    " + _pad("型", 20) + _pad("層", 5, right=True)
          + _pad("最小の層 n", 12, right=True)
          + "".join(_pad(f"{c} 幅の中央値", 20, right=True) for c in NEED_B6))
    for k in ks:
        s = out.get(k, {})
        print("    " + _pad(KLASS_SHORT.get(k, f"型{k}"), 20)
              + _pad(s.get("n_ages", 0), 5, right=True)
              + _pad(s.get("min_n", 0) or "—", 12, right=True)
              + "".join(_f(s.get("iqr_med", {}).get(c, float("nan")), 20, prec=3)
                        for c in NEED_B6))
    k1, k3 = B6_RATIO
    ratio = {}
    for c in NEED_B6:
        a = out.get(k1, {}).get("iqr_med", {}).get(c, float("nan"))
        b = out.get(k3, {}).get("iqr_med", {}).get(c, float("nan"))
        ratio[c] = a / b if (np.isfinite(a) and np.isfinite(b) and b != 0) else float("nan")
    print(f"    型{k1} ÷ 型{k3}: "
          + "・".join(f"{c} {_n(ratio[c], 3)}" for c in NEED_B6)
          + "（1 より小さいほど、型1 のほうが真値の動く範囲が狭い）")
    print("  幅が狭いほど、その層の中で真値が動いていないので順位相関は小さく出る"
          "（範囲の制限）。これは記述であって検定ではない。")
    print("  「最小の層 n」が小さい型は、その層の ρ が少ない人数で決まる（人数の問題も"
          "同じ表から読める）。")
    print("  出典: この台本（50番）の節B が CSV の既存列から計算した値。"
          "**新しい当てはめはしていない。**")
    return {"types": out, "ratio": ratio}


def print_b5(b2: dict, b3: dict, b4: dict) -> dict:
    """B5 予測との照合（P1〜P5）。**判定は付けない**（事後・記述）。"""
    print("\n" + "-" * 100)
    print("B5. 予測との照合（予測は 2026-09-15 に、実データを見る前に固定した。docstring と同文）")
    print("-" * 100)
    print("  (P1) 型3 で、特徴点法 ΔT が最も短い区間（下から 2 区間）でも凍結版 ΔT の")
    print(f"       中央値は {PRED_P1_FLOOR_MS:.0f} ms を下回らない。")
    print(f"  (P2) 型3 では、特徴点法 ΔT が短い側の半数の ρ が長い側の半数より "
          f"{PRED_RHO_GAP:.2f} 以上小さい。")
    print(f"  (P3) 型1 では (P2) の差が {PRED_RHO_GAP:.2f} 未満。")
    print(f"  (P4) 型3 では、年齢層内の ρ(ri_v1, digital_ri) の中央値が "
          f"{PRED_P4_MED:.2f} 未満で、かつ高齢の層ほど")
    print(f"       小さい（{AGE_OLD:.0f} 歳層で {PRED_P4_OLD:.2f} 未満）。")
    print(f"  (P5) 型1 ではその ρ の中央値が {PRED_P5_MED:.2f} 以上で、年齢層による傾きが")
    print(f"       ない（最も若い層と最も高齢の層の差が {PRED_P5_SLOPE:.2f} 未満）。")

    res3 = b2.get(3, {"bins": [], "n": 0})
    low = res3["bins"][:PRED_P1_N_BINS]
    ev1 = len(low) == PRED_P1_N_BINS
    p1 = ev1 and all(np.isfinite(b["med"]) and b["med"] >= PRED_P1_FLOOR_MS for b in low)
    print(f"\n  P1 型3・特徴点法 ΔT が下から {PRED_P1_N_BINS} 区間の凍結版 ΔT 中央値:")
    for b in low:
        print(f"     [{b['lo']:.0f}, {b['hi']:.0f}) ms  n = {b['n']}  "
              f"凍結版 ΔT の中央値 {_n(b['med'], 1)} ms"
              + ("  ★ この区間は 8 名未満で、中央値は不安定である"
                 if b["n"] < MIN_PER_AGE else ""))
    if ev1:
        print(f"     → {PRED_P1_FLOOR_MS:.0f} ms を下回らない: {_yn(p1)}")
    else:
        print(f"     → 照合できない（対応のある行の区間が {len(low)} しかない）")

    g3 = b3.get((3, "A"), {})
    g1 = b3.get((1, "A"), {})
    gap3 = g3.get("gap", float("nan"))
    gap1 = g1.get("gap", float("nan"))
    p2 = bool(np.isfinite(gap3) and gap3 >= PRED_RHO_GAP)
    p3 = bool(np.isfinite(gap1) and gap1 < PRED_RHO_GAP)
    print(f"\n  P2 型3（A 段）  ρ 短い側 {_n(g3.get('short', {}).get('med', float('nan')), 3, sign=True)}"
          f"・長い側 {_n(g3.get('long', {}).get('med', float('nan')), 3, sign=True)}"
          f"・差 {_n(gap3, 3, sign=True)}")
    print(f"     → 差が {PRED_RHO_GAP:.2f} 以上: "
          + (_yn(p2) if np.isfinite(gap3) else "照合できない（層の人数が足りない）"))
    print(f"\n  P3 型1（A 段）  ρ 短い側 {_n(g1.get('short', {}).get('med', float('nan')), 3, sign=True)}"
          f"・長い側 {_n(g1.get('long', {}).get('med', float('nan')), 3, sign=True)}"
          f"・差 {_n(gap1, 3, sign=True)}")
    print(f"     → 差が {PRED_RHO_GAP:.2f} 未満: "
          + (_yn(p3) if np.isfinite(gap1) else "照合できない（層の人数が足りない）"))

    r4 = _ri_stats(b4, 3)
    r5 = _ri_stats(b4, 1)
    p4 = bool(np.isfinite(r4["med"]) and np.isfinite(r4["old"])
              and r4["med"] < PRED_P4_MED and r4["old"] < PRED_P4_OLD)
    p5 = bool(np.isfinite(r5["med"]) and np.isfinite(r5["span"])
              and r5["med"] >= PRED_P5_MED and r5["span"] < PRED_P5_SLOPE)
    print(f"\n  P4 型3（A 段）  ρ(ri_v1, digital_ri) の中央値 {_n(r4['med'], 3, sign=True)}"
          f"・{AGE_OLD:.0f} 歳層 {_n(r4['old'], 3, sign=True)}"
          f"（評価できた層 {r4['n_ages']}）")
    print(f"     層ごと: {r4['line']}")
    print(f"     → 中央値が {PRED_P4_MED:.2f} 未満、かつ {AGE_OLD:.0f} 歳層が "
          f"{PRED_P4_OLD:.2f} 未満: "
          + (_yn(p4) if np.isfinite(r4["med"]) and np.isfinite(r4["old"])
             else "照合できない（層の人数が足りない）"))
    print(f"     参考: 年齢と層ごとの ρ の順位相関 {_n(r4['trend'], 2, sign=True)}"
          "（負なら高齢の層ほど小さい。記述のみで、規準には使わない）")
    print(f"\n  P5 型1（A 段）  ρ(ri_v1, digital_ri) の中央値 {_n(r5['med'], 3, sign=True)}"
          f"・最も若い層 {_n(r5['young'], 3, sign=True)}"
          f"・最も高齢の層 {_n(r5['old'], 3, sign=True)}"
          f"・差 {_n(r5['span'], 3)}")
    print(f"     層ごと: {r5['line']}")
    print(f"     → 中央値が {PRED_P5_MED:.2f} 以上、かつ層による差が "
          f"{PRED_P5_SLOPE:.2f} 未満: "
          + (_yn(p5) if np.isfinite(r5["med"]) and np.isfinite(r5["span"])
             else "照合できない（層の人数が足りない）"))

    ev4 = bool(np.isfinite(r4["med"]) and np.isfinite(r4["old"]))
    ev5 = bool(np.isfinite(r5["med"]) and np.isfinite(r5["span"]))
    hit = sum(1 for v in (p1, p2, p3, p4, p5) if v)
    ev = sum(1 for v in (ev1, np.isfinite(gap3), np.isfinite(gap1), ev4, ev5) if v)
    print(f"\n  まとめ: 予測 5 条のうち照合できたのは {ev} 条、そのうち「はい」は {hit} 条。")
    if ev < 5:
        print("  照合できなかった条は、人数が足りないか対応のある行・列が無いためである。")
        print("  この CSV が抜粋なら、確認的解析の機械（4,374 行）で走らせ直す。")
    print("  **この節は事後の記述であり、判定（成立・不成立）は付けない。**"
          "26番の事前規準による判定は動かない。")
    return {"P1": p1, "P2": p2, "P3": p3, "P4": p4, "P5": p5, "hit": hit, "n_eval": ev,
            "p1_bins": low, "gap3": gap3, "gap1": gap1, "ri3": r4, "ri1": r5}


def _ri_stats(b4: dict, klass: int) -> dict:
    """B4 の A 段から、P4・P5 に要る値を取り出す（中央値・最若層・最高齢層・傾き）。

    「年齢層による傾き」は記述として年齢と ρ の順位相関も出すが、**規準に使うのは
    最も若い層と最も高齢の層の差**（P5）と、最も高齢の層の値（P4）である。
    """
    s = b4.get(klass, {}).get("A", {})
    rows = [(a, r) for a, r, _n in s.get("rows", []) if np.isfinite(r)]
    out = {"med": s.get("med", float("nan")), "n_ages": s.get("n_ages", 0),
           "young": float("nan"), "old": float("nan"), "span": float("nan"),
           "trend": float("nan"), "line": "—"}
    if not rows:
        return out
    rows.sort()
    out["young"], out["old"] = rows[0][1], rows[-1][1]
    out["span"] = abs(out["old"] - out["young"])
    if len(rows) >= MIN_BEATS_A:
        out["trend"] = M._spearman(np.array([a for a, _r in rows], float),
                                   np.array([r for _a, r in rows], float),
                                   min_n=MIN_BEATS_A)[0]
    out["line"] = "・".join(f"{a:.0f}歳 {r:+.3f}" for a, r in rows)
    # P4 は「75 歳層」を見る。その層が評価できていなければ最も高齢の層で代える
    for a, r in rows:
        if abs(a - AGE_OLD) < 1e-9:
            out["old"] = r
    return out


def section_b(d: pd.DataFrame, src: str) -> dict:
    """節B: 凍結版 ΔT が下限で詰まる性質は実データにも出るか（既存列だけを読む）。"""
    print("\n" + "=" * 100)
    print("節B 実データ（PWDB）: 凍結版 ΔT は下限で詰まっているか")
    print("=" * 100)
    miss = missing_cols(d)
    if miss:
        print(f"  入力 {src}")
        print(f"  ★ 列が無い: {miss}。節B は計算できない（26番 `26_pwdb_compare.py` の"
              "出力が要る）。")
        return {"state": 2, "missing": miss}
    ages = sorted(pd.to_numeric(d["age"], errors="coerce").dropna().unique().tolist())
    kl = _colv(d, KLASS_COL)
    seen = sorted(set(int(v) for v in kl[np.isfinite(kl)]))
    n_ok = int(np.sum(pd.to_numeric(d[COL_OK], errors="coerce") == 1)) \
        if COL_OK in d.columns else -1
    print(f"  入力 {src}")
    print("  （26番の出力。**既存列だけを読み、新しい当てはめはしない**）")
    print(f"  行数 {len(d)} 名（確認的解析を回した機械では 4,374 名）"
          f"・年齢層 {[int(a) for a in ages]}・型の値 {seen}")
    print(f"  A 段（{COL_OK} == 1）{n_ok} 名"
          if n_ok >= 0 else f"  {COL_OK} の列が無いので A 段と C 段は同じになる")
    short = [int(a) for a in ages
             if int((pd.to_numeric(d["age"], errors="coerce") == a).sum()) < MIN_PER_AGE]
    if len(d) < 100:
        print(f"  ★ この CSV は {len(d)} 行の抜粋である（1 層 "
              f"{len(d) // max(len(ages), 1)} 名）。**ここから出る数値は読んではいけない。**")
    elif short:
        print(f"  ★ {MIN_PER_AGE} 名に満たない年齢層がある: {short}")
    klasses = list(KLASSES) + sorted(set(seen) - set(KLASSES))
    out = {"state": 0}
    out["b1"] = print_b1(d, klasses)
    out["b2"] = print_b2(d, klasses)
    out["b3"] = print_b3(d, klasses)
    out["b4"] = print_b4_ri(d, klasses)
    out["b6"] = print_b6(d, klasses)
    out["b5"] = print_b5(out["b2"], out["b3"], out["b4"])
    return out


# ============================================================ 節C（実データ・再当てはめ）
# 節A・節A-2 で候補になった当てはめの型を、**26番と同じ拍**（PWDB の指尖 PPG）に当て直し、
# 26番の枠組み（波形の型・A 段と C 段・年齢層内 Spearman）でそのまま並べる。
# **探索・事後であり、26番の事前規準による判定は動かさない。**
# 既定の型は 10 型。(6b) と (3) は 2026-09-15 の実データの結果を見て足した（lab_log 追記144）。
# (6b) は**打ち切りと Δμ の緩和を分けて読む**ために要る。合成脈波では 2 つが同時に効いて
# いたが（(6) は両方を変えてある）、実データでは Δμ の下限に 1 拍も張り付かないので、
# 打ち切り単独の (6b) が (6) と同じ結果になるかどうかで、効き目の出どころが分かる。
# (3) 自由な減衰項は合成では効かなかったが、実データで効いているのは拡張期の下降の扱い
# なので、合成とは違う順位になりうる。**この 2 つを足したのは結果を見た後だが、どちらも
# 「どの変更が効いたか」を分けて読むための行で、判定の規準は動かさない（事後の探索）。**
# (6c) 0.55T・(6d) 0.75T は 2026-09-15 に足した（lab_log 追記145）。**主とする割合は
# 0.65T のまま動かさない**（24番・追記139 で実データを見る前に決めた値である）。この 2 行は
# **結論が割合の選び方に敏感でないことを示す記述（感度の確認）のためだけ**にあり、
# **この 3 つの数値を見てから主の割合を選び直さない。**(6b)(6c)(6d) は Δμ の下限が
# どれも凍結版のまま 0.08 s で、割合だけが違う。
# (4c) 畳み込み・τ の下限 0.15 s は 2026-09-16 に足した（lab_log 追記146）。4,374 名の
# 再当てはめで (4) は g:hi（型1 の 0.42・型3 の 0.61）と tau:lo（0.07・0.21）に張り付いて
# おり、これは核が単位面積の畳み込みが τ → 0 で第1成分の複製に縮退するためである
# （**候補の作りの問題であってデータの性質ではない**）。(4) と τ の下限だけが違う 1 行に
# してあり、**(4)(4b) は 0.05 s のまま**なので一度に 1 つだけ変えた比較になる。記録があれば
# 再開するので、既存の 7 型は当てはめ直さず、新しい 3 型 (4c)(6c)(6d) だけを当てる。
# (6e)(7)(8)(9) は 2026-09-16 に足した（**走らせる前に設計を固定した**。lab_log 追記149）。
# 凍結版が劣る理由をいまの時点で最も正確に言うと、**PPG という量（末梢 Windkessel の
# 容積）に対して圧に似た波の和の模型を当てている**ことである。(7) は和の全体に単位面積の
# 指数核を掛けて置き換え（τ → 0 が凍結版そのものなので入れ子）、(8) は当てる前に波形を
# 戻し、(9) は残差を微分の領域で取る。(6e) は打ち切る位置を絶対時間にした版で、割合で
# 切ると切る時刻が心拍数の関数になることの確認である（W1）。
# **同じ 2026-09-16 に診断の列 `taulo_{型}` を足したので、それより前に書いた記録は
# どの型も当てはめ直される**（列の欠けた記録を使い回さない規約。`_has_variant`）。
# **2026-09-17 に第1成分のピーク時刻 `t1_{型}_ms` を足したので、指定した型は当て直される**
# （同じ規約。C7 がこの列を読む）。14 型全部を指定すると Mac 1 で約 15 時間かかるので
# （lab_log 追記152 の実測 53,632 秒）、**次の実行は `--variants fb,trunc08,deriv` にする。**
# 指定しなかった型の列は記録の中に残る（`_absorb` が古い行に上書きし、`_order_cols` が
# 残りの列を末尾に置く）ので、14 型の記録を消してしまうことはない。
VARIANTS_DEFAULT = ("fb", "relax", "conv", "conv01", "conv15", "trunc", "trunc08",
                    "trunc055", "trunc075", "truncabs", "decay", "convout", "deconv2",
                    "deriv")
# B 段（分母をそろえる段）に使う型。**14 型すべてを要求すると (8) deconv2 の通過率が
# 8% なので積集合が空になり、前回の実行では B 段が 0 名だった**（lab_log 追記152 の 1(f)）。
# B 段は「比べたい少数の型で分母をそろえる」ためのものなので、既定を 3 型にする
# （凍結版・打ち切り 0.65T・微分領域。追記152 で ΔT・RI が成立した候補）。
B_STAGE_DEFAULT = ("fb", "trunc08", "deriv")
REFIT_NAME = "50_refit.csv"     # 再当てはめの記録（--refit-csv で変えられる）
# W6（雑音）の乱数の種の足し前。被験者ごとに `SEED_NOISE + subj_no` を使うので、
# 同じ被験者は何度走らせても同じ雑音になる（再現できる）。
SEED_NOISE = 20260917
# 記録に残す診断の列の頭 → `fit_kind` が返す `checks` の鍵。
# **`taulo` は 2026-09-16 に足した**（(7) の τ が下限＝凍結版そのものに張り付いた拍を
# 数えるため。lab_log 追記149）。列が 1 つ増えるので、**それより前に書いた記録は
# 「その型が入っている」と見なされず、再開のときに当てはめ直される**（`_has_variant`）。
# `pin_{型}` を足した 2026-09-15 と同じ扱いで、列の欠けた記録を黙って使うと表が空の
# ままになるからである。
CHK_COLS = (("dmulo", "dmu_lo"), ("bnd", "boundary"), ("amp", "amp_zero"),
            ("amb", "ambiguous"), ("tauhi", "tau_hi"), ("taulo", "tau_lo"))
CHK_HEAD = {"dmulo": "Δμ下限率", "bnd": "境界率", "amp": "高さ率", "amb": "別解率",
            "tauhi": "τ上限率", "taulo": "τ下限率"}
# 真値の列 COL_PWV（PWV_a）・COL_PVR（pvr）は節B の側で定めてある（B6 も読むため）。
SIGN_DT = -1               # ΔT × 大動脈PWV の予測の向き（26番・48番と同じ）
SIGN_RI = +1               # RI × 末梢血管抵抗 の予測の向き（同上）
MIN_N_POOL = 20            # C4 の順位相関に要る人数（26番の MIN_N と同じ）
C_KLASSES = (1, 3, 4)      # C1〜C4 で分ける波形の型（これに「全」を足す）
PROGRESS_EVERY = 200       # 節C の進み具合を印字する間隔 [名]
CKPT_EVERY = 400           # 節C が途中の記録を書く間隔 [名]（止めても再開できる）

# 予測の規準（docstring の P6〜P10）。2026-09-15 実装前に固定（lab_log 追記143）
PRED_P7_GAP = 0.10         # P7 型3・C 段: (2) の Δμ 下限の割合が (4) より これ以上大きい
PRED_P8_MED = 0.30         # P8 型3・A 段: (4) の RI × pvr の |中央値| がこれ以上
PRED_C0_DT_MS = 1e-6       # C0・P10: (0) と 26番の ΔT の差の許容 [ms]
PRED_C0_RI = 1e-9          # C0・P10: (0) と 26番の RI の差の許容
PRED_P10_LM = {1: 0.343, 3: 0.430}   # P10: 同梱の特徴点の型別 |ρ|（48番・lab_log 追記137）
PRED_P10_PREC = 3          # P10: 小数 3 桁で一致
# P6・P9 の規準は 20番の `_judge` そのもの（|中央値| ≥ M.CRIT_RHO かつ全層で符号が合う）で、
# この台本では新しい閾値を作らない。

_L = None                  # 23番（真値と同梱の特徴点の読み込み）。節C でだけ読み込む


def _landmarks_module():
    """23番を必要になったときだけ読み込む（節A・節B だけのときは読み込まない）。"""
    global _L
    if _L is None:
        _L = _load("23_pwdb_landmarks.py", "m23")
    return _L


def c_stride(ppg, limit: int):
    """先頭 N 名ではなく等間隔に N 名（26番 `_stride` と同じ式を写したもの）。

    PWDB は被験者が年齢順に並んでいる可能性があり、先頭だけ取ると 1 つの年齢層に偏る。
    年齢層内の順位相関で読むので全層が要る。26番のものと同じ結果になることは自己検査で
    確かめる（26番を読み込んで突き合わせる）。
    """
    if limit >= len(ppg):
        return ppg
    idx = np.unique(np.linspace(0, len(ppg) - 1, limit).round().astype(int))
    return ppg.iloc[idx]


def refit_subject(args_tuple):
    """1 被験者の 1 拍に、頼まれた当てはめの型を当てる（26番 `indices_for_subject` と同じ形）。

    例外は握りつぶさず `why` に残し、値は NaN にする（1 名で落ちても走り続ける）。
    拍の作り方・型の付け方は 26番と同一である（`M.beat_of`・`pda2.preprocess` →
    `find_landmarks`）。採否 `ok_{型}` は `fit_kind` の `checks["ok"]`、すなわち凍結版
    `fit_beat` と同じ収束検算の規則である。

    `noise_sd`（既定 0.0）は W6 の検査で拍に足す白色ガウス雑音の標準偏差で、拍の峰から
    谷までの振幅 `np.ptp(y)` に対する比で与える。乱数は `SEED_NOISE + subj_no` で被験者
    ごとに固定するので、同じ被験者は何度走らせても同じ雑音になる。**波形の型 `klass_own`・
    `sys_own_ms`・`dia_own_ms` は雑音を足す前の拍から付ける**（層別を雑音なしの実行と
    同じにするため）。当てはめ（`fit_kind`）だけが雑音を足した拍に当たる。
    """
    subj, row, hr, variants, noise_sd = args_tuple
    noise_sd = float(noise_sd)
    out = {"subj_no": int(subj), "noise_sd": noise_sd}
    for k in variants:                    # 先に空で埋める（当てはめが成らなければこのまま）
        out[f"dt_{k}_ms"] = float("nan")
        out[f"t1_{k}_ms"] = float("nan")
        out[f"ri_{k}"] = float("nan")
        out[f"ok_{k}"] = 0
        for tag, _q in CHK_COLS:
            out[f"{tag}_{k}"] = float("nan")
        out[f"cost_{k}"] = float("nan")
        out[f"pin_{k}"] = ""              # 境界の内訳（空＝当てはめが成らなかった拍）
        if k in KIND_TRUNC:
            # 打ち切る型が実際に切った時刻 [s]。(6e) で拍長の 0.90 倍の頭打ちが効いた
            # 拍を後から数えられるようにしてある（**再開の可否には使わない**。切らない
            # 型では欠測になるので、`_has_variant` の必須の列に入れると毎回当てはめ
            # 直すことになる）。
            out[f"cut_{k}_s"] = float("nan")
    why = []
    try:
        y, fs = M.beat_of(row, hr)
        if y is None:
            out["why"] = "no_beat"        # 心拍が無い・標本 40 未満で拍を復元できない
            return out
        t = np.arange(y.size) / fs
        out["fs"] = float(fs)
        out["n_samp"] = int(y.size)
        try:                              # --- 波形の型（26番と同じ手順で自分で付ける）
            ys, _amp = pda2.preprocess(t, y, fs)
            if ys is None:
                why.append("preprocess_none")
            else:
                lm = pda2.find_landmarks(t, ys)
                out["klass_own"] = int(lm["klass"])
                out["sys_own_ms"] = float(lm["sys_t"]) * 1000.0
                out["dia_own_ms"] = float(lm["dia_t"]) * 1000.0
        except Exception as e:            # noqa: BLE001
            why.append(("EXC:" + str(e))[:40])
        # --- W6 の雑音（--noise）。**型を付けたあとで足す**ので、層別は雑音なしの実行と
        # 同じままである。振幅は拍の峰から谷まで（`np.ptp`）に対する比で与える。
        y_fit = y
        if noise_sd > 0.0:
            rng_n = np.random.default_rng(SEED_NOISE + int(subj))
            y_fit = y + (noise_sd * float(np.ptp(y))) * rng_n.standard_normal(y.size)
        for k in variants:                # --- 候補の当てはめ（節A と同じ `fit_kind`）
            try:
                r = fit_kind(t, y_fit, k)
                ck = r["checks"]
                out[f"dt_{k}_ms"] = (1000.0 * float(r["dt_s"])
                                     if np.isfinite(r["dt_s"]) else float("nan"))
                out[f"t1_{k}_ms"] = (1000.0 * float(r["t1_s"])
                                     if np.isfinite(r["t1_s"]) else float("nan"))
                out[f"ri_{k}"] = float(r["ri"])
                out[f"ok_{k}"] = int(bool(ck["ok"]))
                for tag, q in CHK_COLS:
                    out[f"{tag}_{k}"] = int(bool(ck[q]))
                out[f"cost_{k}"] = float(r["cost"])
                if k in KIND_TRUNC:
                    out[f"cut_{k}_s"] = float(r.get("cut_s", float("nan")))
                # 境界の内訳。どの母数も端に付かなかった拍は PIN_NONE を書く
                # （空欄のままだと CSV から読み直したときに欠測と区別できない）。
                out[f"pin_{k}"] = (";".join(ck.get("pins", [])) or PIN_NONE)[:PIN_MAX]
            except Exception as e:        # noqa: BLE001
                why.append((f"EXC:{k}:" + str(e))[:40])
    except Exception as e:                # noqa: BLE001
        why.append(("EXC:" + str(e))[:60])
    if why:
        out["why"] = ";".join(why)[:120]
    return out


def _refit_path(refit_csv, limit: int, noise_sd: float = 0.0) -> Path:
    """再当てはめの記録の置き場。--limit・--noise のときは別名にする（26番の CSV と同じ規約）。

    雑音を足した実行（`--noise`）は**別のファイル**に書く。雑音なしの記録と混ざると、
    どの行がどの条件のものか分からなくなるからである（記録の中にも `noise_sd` の列を
    書き、再開のときに引数と照合する）。2026-09-17 に足した。
    """
    if refit_csv:
        return Path(refit_csv).expanduser()
    sd = float(noise_sd)
    tag = f"_noise{sd:g}" if sd > 0 else ""
    lim = f"_limit{limit}" if limit else ""
    if not tag and not lim:
        return DATA / "pwdb" / REFIT_NAME
    return DATA / "pwdb" / f"50_refit{tag}{lim}.csv"


def _cached_rows(path: Path) -> dict:
    """記録（CSV）を被験者番号をキーにした辞書で読む。読めなければ空で返す。"""
    if not path.exists():
        return {}
    try:
        # `float_precision="round_trip"` を付ける。既定の速い読み方は最後の 1 ビットが
        # ずれることがあり、再開して書き直すだけで記録の数字が変わってしまう。
        old = pd.read_csv(path, float_precision="round_trip")
    except Exception as e:                # noqa: BLE001
        print(f"  記録 {path} を読めない（{e}）。最初から当てはめる。", flush=True)
        return {}
    if "subj_no" not in old.columns:
        print(f"  記録 {path} に subj_no の列が無い。最初から当てはめる。", flush=True)
        return {}
    out = {}
    for rec in old.to_dict("records"):
        try:
            out[int(rec["subj_no"])] = rec
        except (TypeError, ValueError):
            continue
    return out


def _has_variant(rec: dict, k: str) -> bool:
    """記録にその型の結果が入っているか。

    その型が書く列（`dt_`・`t1_`・`ri_`・`ok_`・診断の印・`cost_`・`pin_`）が**すべて**
    埋まっているときだけ「入っている」と見なし、1 つでも欠けていれば当てはめ直す。
    2026-09-15 までは `ok_{型}` だけを見ていたが、それでは `pin_`（境界の内訳）を
    足す前に書いた記録をそのまま使ってしまい、C1b が空のままになる（lab_log 追記144）。
    **2026-09-16 に診断の列 `taulo_{型}` を足したので、それより前の記録はこの規則で
    すべて当てはめ直される**（lab_log 追記149）。**2026-09-17 に第1成分のピーク時刻
    `t1_{型}_ms` を足したので、同じ規約でまた当てはめ直される**（C7 が読む列である）。
    打ち切った時刻 `cut_{型}_s` は切る型にしか無い列なので、ここでは見ない
    （見ると切らない型が毎回やり直しになる）。
    当てはめが成らなかった拍（`dt_` が欠測）も、この規則では毎回やり直すことになる。
    拍を作れない被験者は `beat_of` の段で即座に戻るので、費用は小さい。
    """
    if not rec:
        return False
    num = ([f"dt_{k}_ms", f"t1_{k}_ms", f"ri_{k}", f"ok_{k}"]
           + [f"{tag}_{k}" for tag, _q in CHK_COLS] + [f"cost_{k}"])
    for c in num:
        v = rec.get(c)
        if v is None:
            return False
        try:
            if not np.isfinite(float(v)):
                return False
        except (TypeError, ValueError):
            return False
    pin = rec.get(f"pin_{k}")              # 文字の列なので float では見られない
    if pin is None or (isinstance(pin, float) and not np.isfinite(pin)):
        return False
    return str(pin).strip() != ""


def _order_cols(df: pd.DataFrame, variants) -> pd.DataFrame:
    """記録の列を決まった順に並べる（再開して書き直しても同じ CSV になる）。"""
    head = ["subj_no", "fs", "n_samp", "klass_own", "sys_own_ms", "dia_own_ms", "noise_sd"]
    per = []
    for k in variants:
        per += ([f"dt_{k}_ms", f"t1_{k}_ms", f"ri_{k}", f"ok_{k}"]
                + [f"{tag}_{k}" for tag, _q in CHK_COLS]
                + [f"cost_{k}", f"pin_{k}"]
                + ([f"cut_{k}_s"] if k in KIND_TRUNC else []))
    tail = ["why", "python_version", "numpy_version", "scipy_version"]
    order = [c for c in head + per + tail if c in df.columns]
    rest = [c for c in df.columns if c not in order]
    return df[order + rest]


def _check_noise_col(have: dict, noise_sd: float, path: Path) -> None:
    """記録の `noise_sd` が引数と違えば止める（別の雑音の記録を混ぜない）。

    記録にこの列が無い行は雑音なし（0.0）と見なす（2026-09-17 より前の記録）。
    `--refit-csv` で場所を指定すると雑音ありと無しが同じ名前になりうるので、名前だけに
    頼らずに中身でも照合する。
    """
    got = set()
    for rec in have.values():
        v = rec.get("noise_sd", 0.0)
        try:
            v = float(v)
        except (TypeError, ValueError):
            v = 0.0
        got.add(0.0 if not np.isfinite(v) else round(v, 12))
    bad = sorted(v for v in got if abs(v - float(noise_sd)) > 1e-12)
    if bad:
        raise ValueError(
            f"記録 {path} の noise_sd が {bad} で、この実行の --noise {noise_sd:g} と違う。"
            "雑音の違う記録を混ぜると、どの行がどの条件のものか分からなくなる。"
            "別の記録（--refit-csv）を指すか、その記録を消してから走らせること。")


def _backup_refit(path: Path) -> None:
    """`--no-resume` で上書きする前に、既存の記録を退避する（消してしまわないため）。

    14 型 × 4,374 名の記録は 15 時間かかっている（lab_log 追記152）。`--no-resume` は
    その記録を丸ごと捨てて書き直すので、**捨てる前に日時付きの名前で残す**。
    2026-09-17 に足した。
    """
    if not path.exists():
        return
    import shutil
    import time
    dst = path.with_name(path.name + "." + f"bak-{time.strftime('%Y%m%d-%H%M%S')}")
    shutil.copy2(path, dst)
    print(f"  --no-resume: 既存の記録を退避した（{dst}）。この実行は最初から当てはめる。",
          flush=True)


def build_refit(root: Path, limit: int = 0, jobs: int = 1, variants=VARIANTS_DEFAULT,
                refit_csv=None, resume: bool = True, noise_sd: float = 0.0):
    """PWDB の拍に候補の当てはめを当て、記録（CSV）を書き直して表を返す。

    返り値は (この実行で使う表, 記録の場所, 内訳)。表は今回の被験者だけに絞るが、記録には
    前の実行で当てた被験者も残す（再開できるようにするため）。
    """
    root = Path(root).expanduser()
    variants = tuple(variants)
    noise_sd = float(noise_sd)
    path = _refit_path(refit_csv, limit, noise_sd)
    hae, _cfg, ppg, _extras = M.load_pwdb(root)
    if limit and limit < len(ppg):
        ppg = c_stride(ppg, limit)
        print(f"  --limit: 等間隔に {len(ppg)} 名を取る（26番と同じ。全年齢層を含めるため）",
              flush=True)
    hr_by = dict(zip(hae["subj_no"].astype(int), hae["HR"].astype(float)))
    have = _cached_rows(path) if resume else {}
    if have:
        print(f"  記録を読んだ: {path}（{len(have)} 名）", flush=True)
        _check_noise_col(have, noise_sd, path)
    if not resume:
        _backup_refit(path)

    subjects, work, n_cache = [], [], 0
    for i in range(len(ppg)):
        subj = int(ppg.iloc[i, 0])
        subjects.append(subj)
        need = tuple(k for k in variants if not _has_variant(have.get(subj), k))
        if not need:
            n_cache += 1
            continue
        work.append((subj, ppg.iloc[i].to_numpy(float), hr_by.get(subj, np.nan), need,
                     noise_sd))
    print(f"\n  {len(subjects)} 名中 {len(work)} 名に当てはめる"
          f"（記録から {n_cache} 名を再利用）・型 {list(variants)} / jobs={jobs}", flush=True)

    # 版も記録する（26番と同じ。scipy の版が違うと最適化の最終桁が変わりうる）
    import platform
    import time
    import scipy
    meta = {"python_version": platform.python_version(),
            "numpy_version": np.__version__, "scipy_version": scipy.__version__,
            "noise_sd": noise_sd}
    path.parent.mkdir(parents=True, exist_ok=True)

    def _absorb(r: dict) -> None:
        r.update(meta)
        s_ = int(r["subj_no"])
        base = dict(have.get(s_, {}))
        base.update(r)
        have[s_] = base

    def _write() -> pd.DataFrame:
        df_ = _order_cols(pd.DataFrame([have[s_] for s_ in sorted(have)]), variants)
        df_.to_csv(path, index=False)
        return df_

    # 進み具合を PROGRESS_EVERY 名ごとに印字し、CKPT_EVERY 名ごとに記録を書く。
    # 並列でも黙って走らせない（Mac 1 で 4,374 名を --jobs 8 で回すと、印字が無いと
    # 止まっているように見えた。2026-09-15）。途中で止めても記録から再開できる。
    t_start = time.time()
    n_done = 0

    def _tick(r: dict) -> None:
        nonlocal n_done
        _absorb(r)
        n_done += 1
        if n_done % PROGRESS_EVERY == 0 or n_done == len(work):
            el = time.time() - t_start
            eta = el / n_done * (len(work) - n_done)
            print(f"  [{n_done}/{len(work)}] {el:.0f} 秒経過・残り約 {eta:.0f} 秒", flush=True)
        if n_done % CKPT_EVERY == 0 and n_done < len(work):
            _write()
            print(f"  途中の記録を書いた: {path}（{len(have)} 名）", flush=True)

    if work and jobs > 1:
        from concurrent.futures import ProcessPoolExecutor, as_completed
        with ProcessPoolExecutor(max_workers=jobs) as ex:
            futs = [ex.submit(refit_subject, w) for w in work]
            for fut in as_completed(futs):
                _tick(fut.result())
    elif work:
        for w in work:
            _tick(refit_subject(w))

    df = _write()
    print(f"  再当てはめの記録: {path}（{len(df)} 名・{len(df.columns)} 列）", flush=True)
    keep = df[df["subj_no"].isin(subjects)].reset_index(drop=True)
    return keep, path, {"n_fit": len(work), "n_cache": n_cache, "n_sub": len(subjects)}


# ---------------------------------------------------------------- 節C の計算の部品
STAGE_B_COL = "_stage_b"   # B 段（--b-stage の型が全部採用した共通例）の印。表の中だけで使う


def b_stage_mask(d: pd.DataFrame, b_variants) -> np.ndarray:
    """B 段の印。**`--b-stage` に挙げた型が全部そろって採用した被験者**だけ真にする。

    A 段は型ごとに分母が違うので、A 段どうしを比べると「どの拍を捨てたか」の差が値に
    混ざる。B 段は分母を完全にそろえるので、A 段の良さが**当てはめの良さ**なのか
    **採用の仕方**なのかを分けられる（2026-09-16 に足した。lab_log 追記149 の問1。
    打ち切りの RI は型3・A 段で 0.530、C 段で 0.107 と食い違っていて、いまのままでは
    どちらか決められない）。

    **2026-09-17 に、そろえる型を `--b-stage` で選べるようにした。**それまでは「その実行で
    並べる型すべて」だったが、14 型で回した実行では (8) deconv2 の通過率が 8% なので
    積集合が空になり、**B 段が 0 名になった**（lab_log 追記152 の 1(f)）。B 段の目的は
    比べたい手法の分母をそろえることなので、そろえる相手を指定する形に変える。
    表の行はいままでどおり全型に A・B・C を出す（B 段の**被験者の選び方**だけが変わる）。

    `ok_{型}` の列が 1 つでも無ければ、黙って C 段にせず**全部を偽**にする
    （48番の `_stage` と同じ扱い。段を取り違えた表を出さないため）。
    """
    m = np.ones(len(d), dtype=bool)
    for k in b_variants:
        col = f"ok_{k}"
        if col not in d.columns:
            return np.zeros(len(d), dtype=bool)
        m &= (pd.to_numeric(d[col], errors="coerce") == 1).to_numpy(dtype=bool)
    return m


def b_stage_missing(d: pd.DataFrame, variants, b_variants) -> list:
    """B 段に使えない型を返す（`--variants` に無い・`ok_{型}` の列が無い）。

    1 つでもあれば `section_c` は B 段を全部偽にして ★ で印字する。黙って C 段にしない
    （段を取り違えた表を出さないため。48番の `_stage`・`b_stage_mask` と同じ流儀）。
    """
    return [k for k in b_variants
            if k not in tuple(variants) or f"ok_{k}" not in d.columns]


def stage_of(d: pd.DataFrame, ok_col, stage: str = "A") -> pd.DataFrame:
    """段で絞る。A 段はその型が自分で採用した例だけ、B 段は `--b-stage` に挙げた型が
    全部そろって採用した共通例、C 段は採否を無視した全例である。

    B 段の印は `section_c` が表を出す前に 1 回だけ数えて `STAGE_B_COL` の列に入れて
    おく（表ごとに数え直さない）。列が無ければ空にする。A 段は `ok_col` で絞り、
    `ok_col` が None で B 段でもなければ C 段（そのまま返す）。48番の `_stage` と同じ
    扱いにする（列が無ければ空にする。黙って C 段にしない）。
    """
    if stage == "B":
        if STAGE_B_COL not in d.columns:
            return d.iloc[0:0]
        return d[d[STAGE_B_COL].astype(bool)]
    if ok_col is None:
        return d
    if ok_col not in d.columns:
        return d.iloc[0:0]
    return d[pd.to_numeric(d[ok_col], errors="coerce") == 1]


def print_stage_head(d: pd.DataFrame, b_variants) -> None:
    """A・B・C 段の 1 行の定義と、B 段の人数を**表の直前に毎回**出す。

    段の定義は読み手が忘れるものなので、段を使う表の直前に必ず置く（この作業場の
    決まり。2026-09-15）。B 段は挙げた型の数だけ採用の条件を重ねるので小さくなりうる。
    """
    b_list = list(b_variants)
    print("  段 A = その手法が自分で採用した例だけ（ok_{型} == 1）、"
          "段 B = `--b-stage` の "
          + "・".join(_kind_lab(k) for k in b_list) + " が")
    print(f"  すべて採用した共通例（{len(b_list)} 型）、段 C = 採否を無視した全例。"
          "**B 段はこの 3 段のうち分母が完全にそろう唯一の段である。**")
    if STAGE_B_COL not in d.columns:
        print("  ★ B 段の印が無い（ok_{型} の列が足りない）ので、B 段の行は空になる。")
        return
    txt = []
    for kt, nm in _ktypes():
        g = _sub_k(d, kt)
        txt.append(f"{nm} {int(g[STAGE_B_COL].astype(bool).sum())}/{len(g)} 名")
    print("  B 段の人数（波形の型ごと・分母はその型の全例）: " + "・".join(txt))
    print("  ★ **B 段は小さくなりうる。**1 層 "
          f"{MIN_PER_AGE} 名に満たない年齢層は ρ を計算しないので、人数が減ると")
    print("  B 段の行が「—」になる。その「—」は関連が無いことではなく、"
          "**評価できなかった**ことである。")


def judge_c(d: pd.DataFrame, x: str, y: str, sign: int):
    """年齢層内 Spearman の一式。20番の `_by_age`・`_judge` をそのまま使う（48番と同じ）。"""
    if len(d) == 0 or x not in d.columns or y not in d.columns or "age" not in d.columns:
        return None, []
    rows = M._by_age(d, x, y, min_n=MIN_PER_AGE)
    return M._judge(rows, sign), rows


def _cell(j) -> str:
    """表のます目「|ρ| の中央値（向きの合った層／評価できた層）成立・不成立」。"""
    if not j:
        return "—"
    return (f"{j['med_abs']:.3f}（{j['n_ok']}/{j['n_ages']}）"
            + ("成立" if j["pass"] else "不成立"))


def _age_line_c(rows: list) -> str:
    """年齢層ごとの ρ を 1 行に並べる（48番の `_age_line` と同じ書き方）。"""
    if not rows:
        return "年齢層が取れない"
    return "・".join(f"{int(a)}歳 {_n(r, sign=True)}({n})" for a, r, n in rows)


def _rho_at(rows: list, age: float) -> float:
    """その年齢層の ρ（無ければ NaN）。"""
    for a, r, _n in rows:
        if abs(float(a) - age) < 1e-9:
            return float(r)
    return float("nan")


def _kind_lab(k: str) -> str:
    return f"{_kind_no(k)} {KIND_HEAD[k]}"


def _ktypes():
    """C1〜C4 で分ける型の一覧（型1・型3・型4 と「全」）。"""
    return [(k, f"型{k}") for k in C_KLASSES] + [(None, "全")]


def _sub_k(d: pd.DataFrame, k):
    return d if k is None else subset(d, k)


# ---------------------------------------------------------------- C0
def print_c0(d: pd.DataFrame, variants, noise_sd: float = 0.0) -> dict:
    """C0 (0) 凍結版本体の再当てはめが 26番の列と同じ値かを照合する。

    `--noise` を付けた実行では**一致しなくて当然である**（26番は雑音を足していない拍に
    当てた値だから）。そのときは「雑音あり」と明記したうえで差を出すだけにし、照合の
    判定（`match`・`match_p10`）は立てない。P10 もその旨を印字して照合しない。
    """
    noise_sd = float(noise_sd)
    print("\n" + "-" * 100)
    print("C0. 照合: (0) 凍結版本体の再当てはめは 26番の列（dt_v1_ms・ri_v1・ok_v1・"
          "klass_own）と同じか")
    print("-" * 100)
    out = {"state": "照合できない", "n": 0, "dt": float("nan"), "ri": float("nan"),
           "n_ok_diff": -1, "n_klass_diff": -1, "n_klass": 0,
           "match": False, "match_p10": False, "noise_sd": noise_sd}
    if noise_sd > 0:
        print(f"  ★ **この実行は拍に雑音を足している（--noise {noise_sd:g}"
              "・峰から谷までの振幅に対する標準偏差）。**")
        print("  26番の列は雑音を足していない拍の値なので、**一致しなくて当然である。**")
        print("  ここでは差を出すだけにし、一致・不一致の判定はしない"
              "（型 klass_own は雑音を足す前の拍から付けるので、そちらは一致するはずである）。")
    if "fb" not in variants:
        print("  (0) 凍結版本体を当てていないので照合できない（--variants に fb を入れる）。")
        return out
    if COL_V1 not in d.columns:
        print("  26番の列が無いので照合できない（--csv で 26番の出力を渡す）。")
        return out

    def _pair(a_col: str, b_col: str):
        """対応のある行と、その行での差（値の列は |差| の最大、印の列は食い違いの数）。"""
        a, b = _colv(d, a_col), _colv(d, b_col)
        g = np.isfinite(a) & np.isfinite(b)
        if not g.any():
            return 0, float("nan")
        if a_col in ("dt_fb_ms", "ri_fb"):
            return int(g.sum()), float(np.max(np.abs(a[g] - b[g])))
        return int(g.sum()), float(np.sum(a[g] != b[g]))

    n_dt, out["dt"] = _pair("dt_fb_ms", COL_V1)
    n_ri, out["ri"] = _pair("ri_fb", COL_RI_V1)
    n_ok, v_ok = _pair("ok_fb", COL_OK)
    n_kl, v_kl = _pair(KLASS_COL, KLASS_COL + "_26")
    out["n"] = n_dt
    out["n_klass"] = n_kl
    out["n_ok_diff"] = int(v_ok) if np.isfinite(v_ok) else -1
    out["n_klass_diff"] = int(v_kl) if np.isfinite(v_kl) else -1
    print(f"  対応のある行 ΔT {n_dt} 名・RI {n_ri} 名・採否 {n_ok} 名・型 {n_kl} 名")
    print(f"  |dt_fb_ms − dt_v1_ms| の最大   {_n(out['dt'], 9)} ms（許容 {PRED_C0_DT_MS:g}）")
    print(f"  |ri_fb − ri_v1| の最大         {_n(out['ri'], 12)}（許容 {PRED_C0_RI:g}）")
    print("  ok_fb ≠ ok_v1 の人数           "
          + (str(out["n_ok_diff"]) if out["n_ok_diff"] >= 0 else "—（照合できない）"))
    print("  klass_own ≠ klass_own_26 の人数 "
          + (str(out["n_klass_diff"]) if out["n_klass_diff"] >= 0 else "—（照合できない）"))
    ev = bool(n_dt and n_ri and n_ok)
    if not ev:
        out["state"] = "照合できない"
        print("  → 照合できない（対応のある行が無い。26番の CSV がこの被験者を含まない）")
        return out
    if noise_sd > 0:
        out["state"] = "雑音あり（照合しない）"
        print(f"  → {out['state']}。上の差は「雑音 SD {noise_sd:g} で ΔT・RI がどれだけ"
              "動いたか」を表す量であって、検算ではない。")
        return out
    out["match_p10"] = bool(out["dt"] <= PRED_C0_DT_MS and out["ri"] <= PRED_C0_RI
                            and out["n_ok_diff"] == 0)
    out["match"] = bool(out["match_p10"] and out["n_klass_diff"] == 0)
    # 型の列が 26番の CSV に無いときは、型の一致は問わない（印字は「—」のまま）
    if out["n_klass_diff"] < 0:
        out["match"] = out["match_p10"]
    out["state"] = "一致" if out["match"] else "食い違いあり"
    print(f"  → {out['state']}")
    if not out["match"]:
        print("  ★ (0) は `src/pda.py` の `fit_beat` をそのまま呼ぶので、26番の列と一致する")
        print("  はずである。食い違うなら入力の拍か版が 26番と違う（この先の表はその前提で読む）。")
    return out


# ---------------------------------------------------------------- C1
def print_c1(d: pd.DataFrame, variants) -> dict:
    """C1 型ごとの採否と縮退の割合（C 段。採否を無視した全例を分母にする）。"""
    print("\n" + "-" * 100)
    print("C1. 採否と縮退: 型ごとに、凍結版の収束検算の規則を当てたときの割合（C 段）")
    print("-" * 100)
    print("  「通過率」は凍結版と同じ規則（境界張り付き・高さ 0.02・競合解の RI 差 0.08）を")
    print("  当てて採用になった割合、すなわち A 段に残る割合である。")
    print("  「Δμ下限率」は Δμ が探索範囲の下限に張り付いた割合で、2 成分の縮退の目安である。")
    print("  n は当てはめを試した拍の数（拍を作れなかった被験者は数えない）。縮退の 4 列は、")
    print("  解が出た拍だけを分母にする。")
    print("  「境界率」がどの母数のものかは、次の C1b に内訳を出す。")
    out = {}
    for kt, kname in _ktypes():
        g = _sub_k(d, kt)
        lab = KLASS_LABEL.get(kt, "全例（型を分けない）")
        print(f"\n  {lab}  n = {len(g)} 名")
        print("    " + _pad("当てはめの型", 18) + _pad("n", 8, right=True)
              + _pad("通過率", 10, right=True)
              + "".join(_pad(CHK_HEAD[t], 12, right=True) for t, _q in CHK_COLS))
        for k in variants:
            ok = _colv(g, f"ok_{k}")
            n = int(np.isfinite(ok).sum())
            rec = {"n": n,
                   "ok": float(np.nanmean(ok)) if n else float("nan")}
            for tag, _q in CHK_COLS:
                v = _colv(g, f"{tag}_{k}")
                rec[tag] = float(np.nanmean(v)) if np.isfinite(v).any() else float("nan")
            out[(kt, k)] = rec
            print("    " + _pad(_kind_lab(k), 18) + _pad(n, 8, right=True)
                  + _f(rec["ok"], 10)
                  + "".join(_f(rec[t], 12) for t, _q in CHK_COLS))
    print("\n  出典: この台本（50番）の節C が PWDB の拍に当てはめ直して数えた値。")
    return out


# ---------------------------------------------------------------- C1b
def _pin_counts(g: pd.DataFrame, k: str) -> tuple:
    """その型の境界の内訳を数える。返り値は (解が出た拍の数, [(母数, 拍数), ...] 多い順)。

    記録の `pin_{型}` は「s2:hi;al2:hi」のように並べた文字である。欠測（当てはめが
    成らなかった拍）は分母に入れない。PIN_NONE は「解は出たが、どの母数も端に
    付かなかった拍」なので分母には入れ、内訳には数えない。記録は PIN_MAX 文字で
    切ってあるので、末尾が途中で切れた語（`:lo`・`:hi` で終わらない）は数えない。
    """
    col = f"pin_{k}"
    if col not in g.columns:
        return 0, []
    n, cnt = 0, {}
    for v in g[col]:
        if v is None or (isinstance(v, float) and not np.isfinite(v)):
            continue
        txt = str(v).strip()
        if txt == "" or txt.lower() == "nan":
            continue
        n += 1
        if txt == PIN_NONE:
            continue
        for nm in txt.split(";"):
            nm = nm.strip()
            if nm.endswith((":lo", ":hi")):
                cnt[nm] = cnt.get(nm, 0) + 1
    return n, sorted(cnt.items(), key=lambda kv: (-kv[1], kv[0]))


def print_c1b(d: pd.DataFrame, variants) -> dict:
    """C1b 境界の内訳（C1 の「境界率」がどの母数のものかを型ごとに並べる）。"""
    print("\n" + "-" * 100)
    print("C1b. 境界の内訳: C1 の「境界率」はどの母数が探索範囲の端に付いたものか（C 段）")
    print("-" * 100)
    print("  1 つの拍が複数の母数で端に付くことがあるので、**割合の合計は 1 にならない。**")
    print("  母数の名前は a1・mu1・s1・al1（第1成分の 高さ・位置・幅・歪度）、"
          "a2・dmu・s2・al2（第2成分）、")
    print("  g・tau（貯留槽）、c（形を縛る型の σ の比）で、:lo は下限・:hi は上限に付いた"
          "ことを表す。")
    print("  数え方は C1 の「境界率」と同じ（歪度 α の下限・g の下限・τ の上限は数えない。"
          "τ の上限は")
    print(f"  「τ上限率」で見る）。分母は解が出た拍で、多い順に上位 {PIN_TOP} 個まで出す。")
    out = {}
    for kt, _kname in _ktypes():
        g = _sub_k(d, kt)
        lab = KLASS_LABEL.get(kt, "全例（型を分けない）")
        print(f"\n  {lab}  n = {len(g)} 名")
        print("    " + _pad("当てはめの型", 18) + _pad("n", 8, right=True)
              + "  " + "張り付いた母数（多い順・数字は解が出た拍に対する割合）")
        for k in variants:
            n, rows = _pin_counts(g, k)
            out[(kt, k)] = {"n": n, "rows": rows}
            txt = ("—" if not rows or not n
                   else "・".join(f"{nm} {c / n:.2f}" for nm, c in rows[:PIN_TOP]))
            print("    " + _pad(_kind_lab(k), 18) + _pad(n, 8, right=True) + "  " + txt)
    print("\n  出典: この台本（50番）の節C が PWDB の拍に当てはめ直して数えた値。")
    return out


# ---------------------------------------------------------------- C2・C3
def _rows_for(d: pd.DataFrame, variants, pre: str, suf: str, ref_col: str, ref_lab: str,
              lm_col: str, lm_lab: str) -> list:
    """C2・C3 の行（表示名, 列, 採否の列, 段）。参考の 2 行は末尾に置く。"""
    rows = []
    for k in variants:
        col = f"{pre}{k}{suf}"
        rows.append((_kind_lab(k), col, f"ok_{k}", "A"))
        rows.append((_kind_lab(k), col, None, "B"))
        rows.append((_kind_lab(k), col, None, "C"))
    if ref_col in d.columns:
        rows.append((ref_lab, ref_col, COL_OK, "A"))
        rows.append((ref_lab, ref_col, None, "B"))
        rows.append((ref_lab, ref_col, None, "C"))
    if lm_col in d.columns:
        # 同梱の特徴点は採否を持たないので A 段が無い。B 段（共通例）は**同じ被験者の
        # 上で比べるため**に出す（段は被験者の絞り方であって、手法の性質ではない）。
        rows.append((lm_lab, lm_col, None, "B"))
        rows.append((lm_lab, lm_col, None, "C"))
    return rows


def print_c_matrix(d: pd.DataFrame, rows: list, tgt: str, sign: int) -> dict:
    """型 × 当てはめの表。ます目は |ρ| の中央値（向きの層／評価層）と規準の成立・不成立。"""
    types = _ktypes()
    print("  " + _pad("当てはめ（段）", 22)
          + "".join(_pad(nm, 19, right=True) for _k, nm in types))
    out = {}
    for lab, col, ok_col, stg in rows:
        line = "  " + _pad(f"{lab} {stg}", 22)
        for kt, _nm in types:
            g = stage_of(_sub_k(d, kt), ok_col, stg)
            j, ages = judge_c(g, col, tgt, sign)
            out[(col, stg, kt)] = {"j": j, "rows": ages, "n": len(g)}
            line += _pad(_cell(j), 19, right=True)
        print(line)
    return out


def print_c2(d: pd.DataFrame, variants, b_variants) -> dict:
    """C2 ΔT × 大動脈脈波伝播速度（予測の向き 負）。"""
    print("\n" + "-" * 100)
    print(f"C2. ΔT × 大動脈脈波伝播速度 {COL_PWV}（予測の向き 負。年齢層内 Spearman）")
    print("-" * 100)
    print(f"  層は `age` の相異なる値、1 層 {MIN_PER_AGE} 名以上（20番の `_by_age`・`_judge`）。")
    print_stage_head(d, b_variants)
    print("  行は当てはめごとに A・B・C の 3 段を並べる。**A 段だけが良くて C 段が悪い"
          "とき、それが**")
    print("  **当てはめの良さなのか採用の仕方なのかは A と C からは分けられない。"
          "分けるのが B 段である。**")
    print("  ます目は **|ρ| の中央値（予測の向きに合った層数／評価できた層数）** と、")
    print(f"  20番 `_judge` の規準（|中央値| ≥ {M.CRIT_RHO:.2f} かつ全層で向きが合う）に対する")
    print("  **規準 成立／不成立**。**この印は事後の記述であり、26番の判定は動かない。**")
    rows = _rows_for(d, variants, "dt_", "_ms", COL_V1, "（参考）凍結版 26番",
                     COL_LM, "（参考）同梱の特徴点")
    out = print_c_matrix(d, rows, COL_PWV, SIGN_DT)
    print("  出典: この台本（50番）の節C が PWDB の拍に当てはめ直して計算した値"
          "（参考の 2 行は既存列）。")
    return out


def print_c3(d: pd.DataFrame, variants, b_variants) -> dict:
    """C3 RI × 末梢血管抵抗（予測の向き 正）。型3・A 段は年齢層別の ρ も並べる。"""
    print("\n" + "-" * 100)
    print(f"C3. RI × 末梢血管抵抗 {COL_PVR}（予測の向き 正。年齢層内 Spearman）")
    print("-" * 100)
    print("  読み方は C2 と同じ。節A-2 で凍結版の RI は型3 相当の条件で符号が反転したので、")
    print("  型3 の列と、その 75 歳層の ρ を見る。")
    print_stage_head(d, b_variants)
    print("  **この表の B 段が、打ち切りの RI をいちばん強く問う。**型3 の A 段（0.530）と"
          " C 段（0.107）の食い違いが")
    print("  当てはめの良さなら B 段でも保たれ、採用の仕方なら B 段で落ちる"
          "（lab_log 追記149 の問1）。")
    rows = _rows_for(d, variants, "ri_", "", COL_RI_V1, "（参考）凍結版 26番",
                     COL_RI_LM, "（参考）同梱の特徴点")
    out = print_c_matrix(d, rows, COL_PVR, SIGN_RI)
    print(f"\n  型3・A 段の年齢層別 ρ（{AGE_OLD:.0f} 歳層を見るため。括弧内は人数）:")
    for lab, col, ok_col, stg in rows:
        if stg != "A":
            continue
        rec = out.get((col, stg, 3), {})
        print("    " + _pad(lab, 22) + _age_line_c(rec.get("rows", [])))
    print("  出典: この台本（50番）の節C が PWDB の拍に当てはめ直して計算した値"
          "（参考の 2 行は既存列）。")
    return out


# ---------------------------------------------------------------- C4
def print_c4(d: pd.DataFrame, variants) -> dict:
    """C4 同梱の特徴点 ΔT との一致（差の中央値と、まとめた順位相関）。"""
    print("\n" + "-" * 100)
    print(f"C4. 一致: 当てはめの ΔT は同梱の特徴点 {COL_LM} と同じ値か（48番 節4 と同じ見方）")
    print("-" * 100)
    print("  差の中央値は（当てはめの ΔT − 同梱の特徴点 ΔT）[ms]、ρ は年齢層で分けずに")
    print(f"  まとめた Spearman（20番の `_spearman`・{MIN_N_POOL} 名以上）。対応のある行だけ。")
    print("  段 A = その手法が自分で採用した例だけ（ok_{型} == 1）、"
          "段 C = 採否を無視した全例。")
    print("  **C4 は A 段と C 段だけである**（当てはめごとに同梱の特徴点とどれだけ"
          "一致するかを見る指標で、")
    print("  手法どうしを同じ被験者の上で比べる表ではないので、B 段に絞る意味がない）。")
    out = {}
    rows = [(_kind_lab(k), f"dt_{k}_ms", f"ok_{k}", "A") for k in variants]
    rows += [(_kind_lab(k), f"dt_{k}_ms", None, "C") for k in variants]
    if COL_V1 in d.columns:
        rows += [("（参考）凍結版 26番", COL_V1, COL_OK, "A"),
                 ("（参考）凍結版 26番", COL_V1, None, "C")]
    for kt, _nm in _ktypes():
        g0 = _sub_k(d, kt)
        lab = KLASS_LABEL.get(kt, "全例（型を分けない）")
        print(f"\n  {lab}  n = {len(g0)} 名")
        print("    " + _pad("当てはめの型", 22) + _pad("段", 4, right=True)
              + _pad("n", 8, right=True) + _pad("差の中央値[ms]", 16, right=True)
              + _pad("|差|の中央値[ms]", 18, right=True) + _pad("ρ", 10, right=True))
        for name, col, ok_col, stg in rows:
            g = stage_of(g0, ok_col, stg)
            a, b = _colv(g, col), _colv(g, COL_LM)
            ok = np.isfinite(a) & np.isfinite(b)
            n = int(ok.sum())
            v = a[ok] - b[ok]
            med = float(np.median(v)) if n else float("nan")
            mad = float(np.median(np.abs(v))) if n else float("nan")
            rho, _nn = M._spearman(a, b, min_n=MIN_N_POOL)
            out[(kt, col, stg)] = {"n": n, "med": med, "med_abs": mad, "rho": rho}
            print("    " + _pad(name, 22) + _pad(stg, 4, right=True)
                  + _pad(n, 8, right=True) + _f(med, 16, prec=1, sign=True)
                  + _f(mad, 18, prec=1) + _f(rho, 10, prec=3, sign=True))
    print("\n  出典: この台本（50番）の節C が PWDB の拍に当てはめ直して計算した値。")
    return out


# ---------------------------------------------------------------- C5
def _pass_of(cells: dict, col: str, stg: str, kt) -> tuple:
    """表のます目から (照合できるか, 規準を満たすか, ます目の文字, 年齢層ごとの ρ) を取る。"""
    rec = cells.get((col, stg, kt), {})
    j = rec.get("j")
    return (j is not None), bool(j and j["pass"]), _cell(j), rec.get("rows", [])


def print_c5(c0: dict, c1: dict, c2: dict, c3: dict, variants,
             noise_sd: float = 0.0) -> dict:
    """C5 予測との照合（P6〜P10）。**判定は付けない**（事後・記述）。

    `--noise` を付けた実行では P10（26番の列との検算）を**照合しない**。26番は雑音を
    足していない拍の値なので、食い違って当然だからである（C0 と同じ扱い）。
    """
    print("\n" + "-" * 100)
    print("C5. 予測との照合（予測は 2026-09-15 に、実データを見る前に固定した。docstring と同文）")
    print("-" * 100)
    print(f"  (P6) 型3・A 段: (4) conv の ΔT × PWV_a が `_judge` の規準を満たす"
          f"（|中央値| ≥ {M.CRIT_RHO:.2f} かつ全層で符号が合う）。")
    print(f"  (P7) 型3・C 段: (2) relax の Δμ 下限張り付きの割合が (4) conv より "
          f"{PRED_P7_GAP:.2f} 以上大きい。")
    print(f"  (P8) 型3・A 段: (4) conv の RI × pvr で {AGE_OLD:.0f} 歳層の ρ > 0 かつ "
          f"|中央値| ≥ {PRED_P8_MED:.2f}。")
    print("  (P9) 型1・A 段: (4) conv の ΔT × PWV_a が `_judge` の規準を満たす。")
    print("  (P10) 検算: (0) fb の ΔT・RI・採否が 26番の列と全例一致、かつ同梱の特徴点の型別")
    print(f"        ρ(dt_lm_ms, PWV_a) が 型1 {PRED_P10_LM[1]:.3f}・型3 {PRED_P10_LM[3]:.3f}"
          f"（小数 {PRED_P10_PREC} 桁で一致）を再現")
    print("        （26番の列が無ければ「照合できない」）。")
    have_conv = "conv" in variants
    have_relax = "relax" in variants
    res = {}

    def _judge_pred(tag: str, kt: int, name: str) -> None:
        """P6・P9（(4) 畳み込みの ΔT × 大動脈PWV。A 段）を同じ書き方で印字する。"""
        if not have_conv:
            print(f"\n  {tag} {name}・A 段  → 照合できない（--variants に conv が無い）")
            res[tag] = {"ev": False, "hit": False}
            return
        ev, hit, cell, _rows = _pass_of(c2, "dt_conv_ms", "A", kt)
        print(f"\n  {tag} {name}・A 段  (4) 畳み込み ΔT × {COL_PWV}: {cell}")
        print("     → `_judge` の規準を満たす: "
              + (f"{_yn(hit)}（規準 {'成立' if hit else '不成立'}）" if ev
                 else "照合できない（8 名以上の年齢層が無い）"))
        res[tag] = {"ev": ev, "hit": hit}

    _judge_pred("P6", 3, "型3")

    # --- P7（Δμ 下限張り付きの割合。型3・C 段）
    r_rx = c1.get((3, "relax"), {}).get("dmulo", float("nan")) if have_relax else float("nan")
    r_cv = c1.get((3, "conv"), {}).get("dmulo", float("nan")) if have_conv else float("nan")
    gap = r_rx - r_cv
    ev7 = bool(np.isfinite(gap))
    hit7 = bool(ev7 and gap >= PRED_P7_GAP)
    print(f"\n  P7 型3・C 段  (2) Δμ0.01 の Δμ 下限 {_n(r_rx)}・(4) 畳み込み {_n(r_cv)}"
          f"・差 {_n(gap, sign=True)}")
    print(f"     → 差が {PRED_P7_GAP:.2f} 以上: "
          + (_yn(hit7) if ev7 else "照合できない（どちらかの割合が出ていない）"))
    res["P7"] = {"ev": ev7, "hit": hit7, "gap": gap}

    # --- P8（RI × 末梢血管抵抗。型3・A 段の 75 歳層）
    if have_conv:
        ev, _hit, cell, rows = _pass_of(c3, "ri_conv", "A", 3)
        rho_old = _rho_at(rows, AGE_OLD)
        med = c3.get(("ri_conv", "A", 3), {}).get("j")
        med_abs = med["med_abs"] if med else float("nan")
        ev8 = bool(np.isfinite(rho_old) and np.isfinite(med_abs))
        hit8 = bool(ev8 and rho_old > 0 and med_abs >= PRED_P8_MED)
        print(f"\n  P8 型3・A 段  (4) 畳み込み RI × {COL_PVR}: {cell}"
              f"・{AGE_OLD:.0f} 歳層 {_n(rho_old, sign=True)}")
        print(f"     層ごと: {_age_line_c(rows)}")
        print(f"     → {AGE_OLD:.0f} 歳層の ρ > 0 かつ |中央値| ≥ {PRED_P8_MED:.2f}: "
              + (_yn(hit8) if ev8 else f"照合できない（{AGE_OLD:.0f} 歳層の ρ が出ていない）"))
    else:
        ev8, hit8 = False, False
        print("\n  P8 型3・A 段  → 照合できない（--variants に conv が無い）")
    res["P8"] = {"ev": ev8, "hit": hit8}

    _judge_pred("P9", 1, "型1")

    # --- P10（検算。(0) と 26番の列、同梱の特徴点の型別 |ρ|）
    lm = {}
    for kt in (1, 3):
        j = c2.get((COL_LM, "C", kt), {}).get("j")
        lm[kt] = j["med_abs"] if j else float("nan")
    ev10 = bool(c0.get("state") not in ("照合できない", "雑音あり（照合しない）")
                and all(np.isfinite(lm[kt]) for kt in (1, 3)))
    hit10 = bool(ev10 and c0.get("match_p10")
                 and all(round(lm[kt], PRED_P10_PREC) == PRED_P10_LM[kt] for kt in (1, 3)))
    if float(noise_sd) > 0:
        print(f"\n  P10 検算  **雑音ありなので照合しない**（--noise {float(noise_sd):g}）。"
              "26番の列は雑音を足していない拍の値で、")
        print("      (0) の ΔT・RI が食い違うのは当然である。C0 に差だけを出してある。")
    elif c0.get("state") == "照合できない":
        print("\n  P10 検算  (0) と 26番の列: 照合できない（26番の CSV が無いか、"
              "対応のある行が無い）")
    else:
        print(f"\n  P10 検算  (0) と 26番の列: {c0.get('state')}"
              f"（{c0.get('n')} 名・ΔT の差の最大 {_n(c0.get('dt', float('nan')), 9)} ms・"
              f"RI {_n(c0.get('ri', float('nan')), 12)}・"
              f"採否の食い違い {c0.get('n_ok_diff')} 名）")
    print(f"      同梱の特徴点の型別 |ρ|（C 段）: 型1 {_n(lm[1])}（予測 {PRED_P10_LM[1]:.3f}）"
          f"・型3 {_n(lm[3])}（予測 {PRED_P10_LM[3]:.3f}）")
    print("     → 全例一致かつ型別 |ρ| を再現: "
          + (_yn(hit10) if ev10 else "照合できない（26番の列が無い・層の人数が足りない）"))
    res["P10"] = {"ev": ev10, "hit": hit10, "lm": lm}

    ev = sum(1 for k in ("P6", "P7", "P8", "P9", "P10") if res[k]["ev"])
    hit = sum(1 for k in ("P6", "P7", "P8", "P9", "P10") if res[k]["hit"])
    print(f"\n  まとめ: 予測 5 条のうち照合できたのは {ev} 条、そのうち「はい」は {hit} 条。")
    if ev < 5:
        print("  照合できなかった条は、人数が足りないか列・型が無いためである。")
        print("  この実行が抜粋（--limit）なら、確認的解析の機械で全例を回して読み直す。")
    print("  **この節は事後の記述であり、判定（成立・不成立）は付けない。**"
          "26番の事前規準による判定は動かない。")
    res["n_eval"] = ev
    res["hit"] = hit
    return res


# ---------------------------------------------------------------- C6・C7・C8 の部品
# 2026-09-17 に足した 3 つの表（lab_log 追記152 の弱点の第2陣。W4・W5・W1b）。
# **事前に登録した予測は無い。すべて探索・事後であり、26番の判定は動かさない。**
WAVE_SEP_NAME = "51_wave_sep.csv"   # 51番の記録（C7 が前進波のピークを読む）
COL_PF = "pf_peak_ms"               # 51番の前進波 P_f のピーク時刻 [ms]
COL_T1_SYS = "sys_own_ms"           # この台本が付けた収縮期ピークの時刻 [ms]
C6_TERT = ("低", "中", "高")         # C6 の三分位の名前（年齢層ごとに分ける）


def _by_age_med(d: pd.DataFrame, x: str, y: str):
    """年齢層内 Spearman の**符号つき**中央値と、評価できた層の数。

    向きを決めた予測が無い表（C6・C7）で使うので、`_judge` は当てない（|ρ| に直すと
    符号が読めなくなる）。層の規約は C2・C3 と同じ（20番の `_by_age`・1 層
    `MIN_PER_AGE` 名以上）。層の中で x が全部同じ値なら `_spearman` は NaN を返すので、
    その層は数に入らない。
    """
    if len(d) == 0 or x not in d.columns or y not in d.columns or "age" not in d.columns:
        return float("nan"), 0
    rows = M._by_age(d, x, y, min_n=MIN_PER_AGE)
    rs = [float(r) for _a, r, _n in rows if np.isfinite(r)]
    return (float(np.median(rs)) if rs else float("nan")), len(rs)


def _tertile_in_age(d: pd.DataFrame, col: str) -> np.ndarray:
    """年齢層ごとに `col` を三分位に分ける（0 低・1 中・2 高。分けられない行は −1）。

    **層をまたいだ三分位で切ると年齢と混ざる**ので、層ごとに切る（節B の B3 で短い側・
    長い側を層ごとに分けているのと同じ理由）。
    """
    lab = np.full(len(d), -1, dtype=int)
    if col not in d.columns or "age" not in d.columns:
        return lab
    v, age = _colv(d, col), _colv(d, "age")
    for a in np.unique(age[np.isfinite(age)]):
        sel = np.where((age == a) & np.isfinite(v))[0]
        if sel.size < len(C6_TERT):
            continue
        q1, q2 = np.percentile(v[sel], [100.0 / 3.0, 200.0 / 3.0])
        lab[sel] = np.where(v[sel] <= q1, 0, np.where(v[sel] <= q2, 1, 2))
    return lab


# ---------------------------------------------------------------- C6
def print_c6(d: pd.DataFrame, variants) -> dict:
    """C6 採否の偏り（W4）。**C 段だけ**で出す（採否そのものを見る表だから）。"""
    print("\n" + "-" * 100)
    print("C6. 採否の偏り（W4）: 不採用になる被験者は硬い側・抵抗の高い側に偏っていないか")
    print("-" * 100)
    print("  **この表は C 段だけである。**採否そのものを見る表なので、採否で被験者を"
          "絞ると問いが消える。")
    print(f"  ρ は年齢層内 Spearman の**符号つき**中央値（20番の `_by_age`・1 層 "
          f"{MIN_PER_AGE} 名以上）。層の中で")
    print("  採否が全員同じ層は ρ を計算できないので数に入らない（「層」の欄がその数）。")
    print("  三分位の通過率は、**年齢層ごとに** PWV_a を低・中・高の 3 つに分けたときの"
          "通過率である")
    print("  （層をまたいで切ると年齢と混ざる）。三分位は**全例の中で**切り、型ごとの行は"
          "その印をそのまま使う")
    print("  （型ごとに切り直さない。切り方が行ごとに変わると行どうしを比べられない）。")
    print("  読み方: **ρ が負なら硬い（PWV が高い）被験者ほど不採用で、A 段は柔らかい側に"
          "偏っている。**")
    print("  A 段の ρ（C2・C3）はその偏りの上で読むこと。")
    print("  同梱の特徴点は採否を持たないので行に入れない。凍結版 26番（ok_v1）は参考行"
          "として入れる。")
    tert = _tertile_in_age(d, COL_PWV)
    rows = [(_kind_lab(k), f"ok_{k}") for k in variants]
    if COL_OK in d.columns:
        rows.append(("（参考）凍結版 26番", COL_OK))
    out = {}
    for kt, _nm in _ktypes():
        idx = np.where(_colv(d, KLASS_COL) == float(kt))[0] if kt is not None \
            else np.arange(len(d))
        g = d.iloc[idx]
        tg = tert[idx]
        lab = KLASS_LABEL.get(kt, "全例（型を分けない）")
        print(f"\n  {lab}  n = {len(g)} 名")
        print("    " + _pad("当てはめの型", 22) + _pad("n", 7, right=True)
              + _pad("通過率", 9, right=True)
              + _pad(f"ρ(採否,{COL_PWV})", 17, right=True) + _pad("層", 5, right=True)
              + _pad(f"ρ(採否,{COL_PVR})", 17, right=True) + _pad("層", 5, right=True)
              + "".join(_pad(f"通過率 {q}", 12, right=True) for q in C6_TERT))
        for name, col in rows:
            ok = _colv(g, col)
            n = int(np.isfinite(ok).sum())
            rate = float(np.nanmean(ok)) if n else float("nan")
            r_pwv, n_pwv = _by_age_med(g, col, COL_PWV)
            r_pvr, n_pvr = _by_age_med(g, col, COL_PVR)
            ter = []
            for q in range(len(C6_TERT)):
                v = ok[tg == q]
                v = v[np.isfinite(v)]
                ter.append(float(np.mean(v)) if v.size else float("nan"))
            out[(kt, col)] = {"n": n, "ok": rate, "rho_pwv": r_pwv, "n_pwv": n_pwv,
                              "rho_pvr": r_pvr, "n_pvr": n_pvr, "tertile": ter}
            print("    " + _pad(name, 22) + _pad(n, 7, right=True) + _f(rate, 9)
                  + _f(r_pwv, 17, sign=True) + _pad(n_pwv, 5, right=True)
                  + _f(r_pvr, 17, sign=True) + _pad(n_pvr, 5, right=True)
                  + "".join(_f(x, 12) for x in ter))
    print("\n  出典: この台本（50番）の節C が PWDB の拍に当てはめ直して数えた値"
          "（参考の行は 26番の既存列）。")
    return out


# ---------------------------------------------------------------- C7
def _wave_sep_path(limit: int = 0, wave_csv=None) -> Path:
    """51番の記録の場所（`--limit` の記録があればそちらを先に見る）。無ければ None。

    `wave_csv` を渡すとその場所だけを見る（自己検査が模擬の被験者に実データの記録を
    結合してしまわないようにするため。既定の探し方は変えない）。
    """
    if wave_csv is not None:
        q = Path(wave_csv).expanduser()
        return q if q.exists() else None
    base = DATA / "pwdb"
    cand = ([base / f"51_wave_sep_limit{limit}.csv"] if limit else []) \
        + [base / WAVE_SEP_NAME]
    for p in cand:
        if p.exists():
            return p
    return None


def merge_wave_sep(d: pd.DataFrame, limit: int = 0, wave_csv=None):
    """51番の記録から前進波のピーク `pf_peak_ms` を `subj_no` で結合する（あれば）。

    **時間の原点は 50番と同じである。**51番も 20番の `M.beat_of` で拍を作り、
    `t = np.arange(n) / fs` を当ててから `pf_peak_ms = t[argmax(P_f)] × 1000` を書いて
    いるので、どちらも**その被験者の拍の先頭が 0** である（51番 `wave_sep_subject` の
    `tp = np.arange(m) / fs_p`）。したがって揃え直しは要らない。ただし 51番の P_f は
    **指尖の圧波形**から作った量で、50番の t1 は**指尖 PPG** に当てた第1成分なので、
    量そのものは別である（原点だけが共通）。
    """
    p = _wave_sep_path(limit, wave_csv)
    if p is None:
        print(f"  51番の記録（{DATA / 'pwdb' / WAVE_SEP_NAME}）が無いので、C7 の前進波の列は"
              "「—」になる。")
        print("  出すには先に 51番を走らせる: "
              "python3 scripts/51_pwdb_wave_separation.py --pwdb ~/pwdb --jobs 8")
        return d, None
    try:
        w = pd.read_csv(p, float_precision="round_trip")
    except Exception as e:                # noqa: BLE001
        print(f"  51番の記録 {p} を読めない（{e}）。C7 の前進波の列は「—」になる。")
        return d, None
    if "subj_no" not in w.columns or COL_PF not in w.columns:
        print(f"  51番の記録 {p} に subj_no か {COL_PF} の列が無い。C7 の前進波の列は"
              "「—」になる。")
        return d, None
    d = d.merge(w[["subj_no", COL_PF]], on="subj_no", how="left")
    n = int(np.isfinite(_colv(d, COL_PF)).sum())
    print(f"  51番の記録を結合した（{p}・{COL_PF} が入った {n} 名）。C7 が読む。"
          "時間の原点は 50番と同じ（どちらも `beat_of` の拍の先頭が 0）。")
    return d, p


def print_c7(d: pd.DataFrame, variants) -> dict:
    """C7 第1成分の位置（W5）。ΔT の誤差が t1 の側から来ていないかを見る。"""
    print("\n" + "-" * 100)
    print("C7. 第1成分のピーク時刻 t1（W5）: ΔT の誤差は第2成分の側だけの話か")
    print("-" * 100)
    print("  段 A = その手法が自分で採用した例だけ（ok_{型} == 1）、"
          "段 C = 採否を無視した全例。")
    print("  **C7 は A 段と C 段だけである**（1 つの当てはめの中の量を見る表で、"
          "手法どうしを同じ")
    print("  被験者の上で比べる表ではないので、B 段に絞る意味がない）。")
    print("  t1 は当てはめの第1成分のピーク時刻 [ms]（**拍の先頭を 0 とする**）で、"
          "ΔT = t2 − t1 である。")
    print(f"  `{COL_T1_SYS}` はこの台本が `find_landmarks` で付けた PPG の収縮期ピークの"
          "時刻、")
    print(f"  `{COL_PF}` は 51番が指尖の圧波形を線形分離して得た前進波 P_f のピークの時刻"
          "である。")
    print(f"  ρ は年齢層内 Spearman の**符号つき**中央値（1 層 {MIN_PER_AGE} 名以上）、"
          f"ρ(t1,{COL_PF}) は")
    print(f"  年齢層で分けずにまとめた Spearman（20番の `_spearman`・{MIN_N_POOL} 名以上）"
          "である。")
    print("  **向きの予測は設けない**（`_judge` は当てない）。ΔT の誤差が t1 の側から"
          "来ていないかを見るだけの表である。")
    has_pf = COL_PF in d.columns
    out = {}
    for kt, _nm in _ktypes():
        g0 = _sub_k(d, kt)
        lab = KLASS_LABEL.get(kt, "全例（型を分けない）")
        print(f"\n  {lab}  n = {len(g0)} 名")
        print("    " + _pad("当てはめの型", 22) + _pad("段", 4, right=True)
              + _pad("n", 7, right=True) + _pad("t1 中央値[ms]", 15, right=True)
              + _pad("t1−収縮期[ms]", 15, right=True)
              + _pad(f"ρ(t1,{COL_PWV})", 16, right=True) + _pad("層", 5, right=True)
              + _pad("t1−前進波[ms]", 15, right=True)
              + _pad("ρ(t1,前進波)", 15, right=True))
        for k in variants:
            col = f"t1_{k}_ms"
            for stg, ok_col in (("A", f"ok_{k}"), ("C", None)):
                g = stage_of(g0, ok_col, stg)
                v = _colv(g, col)
                n = int(np.isfinite(v).sum())
                med = float(np.median(v[np.isfinite(v)])) if n else float("nan")
                sy = _colv(g, COL_T1_SYS)
                ok_sy = np.isfinite(v) & np.isfinite(sy)
                d_sy = (float(np.median(v[ok_sy] - sy[ok_sy]))
                        if ok_sy.any() else float("nan"))
                rho, n_age = _by_age_med(g, col, COL_PWV)
                d_pf, rho_pf = float("nan"), float("nan")
                if has_pf:
                    pf = _colv(g, COL_PF)
                    ok_pf = np.isfinite(v) & np.isfinite(pf)
                    if ok_pf.any():
                        d_pf = float(np.median(v[ok_pf] - pf[ok_pf]))
                    rho_pf = M._spearman(v, pf, min_n=MIN_N_POOL)[0]
                out[(kt, k, stg)] = {"n": n, "t1": med, "d_sys": d_sy, "rho": rho,
                                     "n_ages": n_age, "d_pf": d_pf, "rho_pf": rho_pf}
                print("    " + _pad(_kind_lab(k), 22) + _pad(stg, 4, right=True)
                      + _pad(n, 7, right=True) + _f(med, 15, prec=1)
                      + _f(d_sy, 15, prec=1, sign=True) + _f(rho, 16, sign=True)
                      + _pad(n_age, 5, right=True)
                      + (_f(d_pf, 15, prec=1, sign=True) if has_pf
                         else _pad("—", 15, right=True))
                      + (_f(rho_pf, 15, sign=True) if has_pf
                         else _pad("—", 15, right=True)))
    print("\n  出典: この台本（50番）の節C が PWDB の拍に当てはめ直して計算した値"
          + ("（前進波の 2 列は 51番の記録）。" if has_pf else "。"))
    return out


# ---------------------------------------------------------------- C8
def _factor_call(d: pd.DataFrame, col: str):
    """20番の `_factor_effects` をそのまま呼ぶ（この台本では計算し直さない）。

    採用が少ない部分集合では列が全層で欠測になり `np.nanmean` が警告を出す（値は NaN の
    ままで、表示だけの問題）ので、20番の中と同じように警告だけを止める。
    """
    import warnings
    if len(d) == 0 or col not in d.columns:
        return (np.full(len(M.FACTORS), np.nan), np.full(len(M.FACTORS), np.nan))
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", category=RuntimeWarning)
        return M._factor_effects(d, col)


def has_factors(d: pd.DataFrame) -> bool:
    """C8 に要る `var_{因子}` の列がそろっているか。"""
    return all(f"var_{f}" in d.columns for f in M.FACTORS)


C8_KLASSES = (None, 3)     # C8 で出す型（全例と型3）


def print_c8(d: pd.DataFrame, variants) -> dict:
    """C8 因子ごとの主効果（W1b。原稿の表2 と同じ形）。20番の `_factor_effects` を使う。"""
    print("\n" + "-" * 100)
    print("C8. 振った因子ごとの主効果（W1b）: 候補の当てはめは何で動いているか"
          "（原稿の表2 と同じ形）")
    print("-" * 100)
    if not has_factors(d):
        print("  PWDB の `pwdb_model_variations.csv`（どの因子を振ったか）が読めないので"
              "C8 は計算できない。")
        print("  要る列は " + "・".join(f"var_{f}" for f in M.FACTORS)
              + " で、配布物にこの表があれば 23番の `load` が結合する。")
        print("  この表を飛ばして先へ進む。")
        return {}
    print("  主効果 [%] は 20番の `_factor_effects` そのもの（年齢層内で +1 の平均 − −1 の"
          "平均を層平均で割る。")
    print("  年齢層の中央値）。ρ はその層内の Spearman の中央値である。"
          "**20番の関数をそのまま呼んでいて、この台本では計算し直さない。**")
    print("  段 A = その手法が自分で採用した例だけ（ok_{型} == 1）、"
          "段 C = 採否を無視した全例。")
    print("  **C8 は A 段と C 段だけである**（1 つの当てはめが何で動くかを見る表で、"
          "手法どうしを同じ")
    print("  被験者の上で比べる表ではないので、B 段に絞る意味がない）。ます目は"
          " **主効果 [%]（ρ）** である。")
    print("  読み方: ΔT が主に脈波伝播速度で動き、RI が主に平均血圧で動けば概念どおり"
          "（20番の表3 と同じ読み）。")
    print("  **この表に事前の予測は無い。探索・事後の記述である。**")
    out = {}
    for kt in C8_KLASSES:
        g0 = _sub_k(d, kt)
        lab = KLASS_LABEL.get(kt, "全例（型を分けない）")
        for idx_lab, pre, suf, ref_col, ref_lab, lm_col, lm_lab in (
                ("ΔT", "dt_", "_ms", COL_V1, "（参考）凍結版 26番",
                 COL_LM, "（参考）同梱の特徴点"),
                ("RI", "ri_", "", COL_RI_V1, "（参考）凍結版 26番",
                 COL_RI_LM, "（参考）同梱の特徴点")):
            print(f"\n  {lab}  n = {len(g0)} 名 ／ 指標 {idx_lab}")
            print("    " + _pad("当てはめの型（段）", 26)
                  + "".join(_pad(M.FACTOR_LABEL[f], 15, right=True) for f in M.FACTORS))
            rows = []
            for k in variants:
                rows.append((_kind_lab(k), f"{pre}{k}{suf}", f"ok_{k}", "A"))
                rows.append((_kind_lab(k), f"{pre}{k}{suf}", None, "C"))
            if ref_col in d.columns:
                rows.append((ref_lab, ref_col, COL_OK, "A"))
                rows.append((ref_lab, ref_col, None, "C"))
            if lm_col in d.columns:
                # 同梱の特徴点は採否を持たないので C 段だけ
                rows.append((lm_lab, lm_col, None, "C"))
            for name, col, ok_col, stg in rows:
                g = stage_of(g0, ok_col, stg)
                eff, rho = _factor_call(g, col)
                out[(kt, col, stg)] = {"n": len(g), "eff": eff, "rho": rho}
                line = "    " + _pad(f"{name} {stg}", 26)
                for j in range(len(M.FACTORS)):
                    e_, r_ = float(eff[j]), float(rho[j])
                    line += _pad("—" if not np.isfinite(e_)
                                 else f"{e_:+.1f}（{_n(r_, 2, sign=True)}）",
                                 15, right=True)
                print(line)
    print("\n  出典: この台本（50番）の節C が PWDB の拍に当てはめ直した値に、"
          "20番 `20_pwdb_validity.py` の")
    print("  `_factor_effects` をそのまま当てた（参考の行は 26番の既存列と Charlton 同梱"
          "の特徴点）。")
    return out


# ---------------------------------------------------------------- 節C の入口
def section_c(root, limit: int = 0, jobs: int = 1, variants=VARIANTS_DEFAULT,
              refit_csv=None, resume: bool = True, d26=None, src26: str = "",
              b_variants=B_STAGE_DEFAULT, noise_sd: float = 0.0, wave_csv=None) -> dict:
    """節C: 候補の当てはめを PWDB の同じ拍に当て、26番の枠組みで並べる（探索・事後）。"""
    print("\n" + "=" * 100)
    print("節C 実データ（PWDB）: 候補の当てはめを同じ拍に当てる"
          "（探索・事後。26番の判定は動かない）")
    print("=" * 100)
    variants = tuple(variants)
    b_variants = tuple(b_variants)
    noise_sd = float(noise_sd)
    bad = [k for k in tuple(variants) + b_variants if k not in KIND_KEYS]
    if bad:
        raise ValueError(f"知らない当てはめの型: {bad}（使えるのは {list(KIND_KEYS)}）")
    root = Path(root).expanduser()
    print(f"  入力 {root}（PWDB の配布物）")
    print("  拍の作り方は 26番と同じ（20番の `load_pwdb`・`beat_of`）。型 klass_own も")
    print("  26番と同じ手順（`pda2.preprocess` → `find_landmarks`）で自分で付ける。")
    print("  当てはめ: " + "・".join(_kind_lab(k) for k in variants))
    if noise_sd > 0:
        print(f"  ★ **雑音あり（--noise {noise_sd:g}）。**拍の峰から谷までの振幅の"
              f"{noise_sd:g} 倍を標準偏差とする")
        print("  白色ガウス雑音を足した拍に当てはめる（乱数は被験者ごとに固定）。"
              "**波形の型・収縮期ピーク・拡張期の点は**")
        print("  **雑音を足す前の拍から付ける**ので、層別は雑音なしの実行と同じである。"
              "26番の列とは一致しない（C0 を見ること）。")

    ref, path, info = build_refit(root, limit=limit, jobs=jobs, variants=variants,
                                  refit_csv=refit_csv, resume=resume, noise_sd=noise_sd)
    L = _landmarks_module()
    d = L.load(root, pda_dir=root / "__no_pda__")
    d = d.drop(columns=[c for c in ("dt_pda_ms", "ri_pda", "ok2") if c in d.columns])
    n_truth, n_ref = len(d), len(ref)
    d = d.merge(ref, on="subj_no", how="inner")
    print(f"\n  真値・同梱の特徴点 {n_truth} 名・再当てはめ {n_ref} 名 → "
          f"突き合わせ {len(d)} 名（内部結合。26番と同じ扱い）")
    if d26 is not None and "subj_no" in getattr(d26, "columns", []):
        cols = [c for c in ("subj_no", COL_V1, COL_RI_V1, COL_OK, KLASS_COL)
                if c in d26.columns]
        d = d.merge(d26[cols], on="subj_no", how="left", suffixes=("", "_26"))
        n26 = int(np.isfinite(_colv(d, COL_V1)).sum())
        print(f"  26番の列を結合した（{src26}・{n26} 名ぶん）。C0 と C2・C3 の参考行に使う。")
    else:
        print("  26番の CSV が無いので C0 の照合と参考行は飛ばす（--csv で渡せる）。")
    if not has_factors(d):
        # C8 に要る `var_{因子}`。23番の `load` は配布物に変動表があれば結合するが、
        # 無い・列が欠けているときはここで結合し直す（20番 `report` と同じやり方で、
        # `load_pwdb` が中で呼ぶ `load_extras` と同じ表である。指尖 PPG の大きな CSV を
        # もう一度読まないよう `load_extras` を直接呼ぶ）。
        try:
            ex = M.load_extras(root)
        except Exception as e:            # noqa: BLE001
            ex, _ = {}, print(f"  変動表（variations）を読めない（{e}）。C8 は飛ばす。")
        if "variations" in ex:
            d = d.drop(columns=[c for c in d.columns if c.startswith("var_")])
            add = ex["variations"].drop(columns=["var_age"], errors="ignore")
            d = d.merge(add, on="subj_no", how="left")
            print(f"  変動表 var_{{因子}} を結合した（{len(add)} 名ぶん）。C8 が読む。")
    for c in (COL_PWV, COL_PVR, COL_LM, COL_RI_LM, "age", KLASS_COL, KLASS_COL + "_26"):
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors="coerce")
    ages = sorted(pd.to_numeric(d["age"], errors="coerce").dropna().unique().tolist()) \
        if "age" in d.columns else []
    kl = _colv(d, KLASS_COL)
    seen = sorted(set(int(v) for v in kl[np.isfinite(kl)]))
    print(f"  年齢層 {[int(a) for a in ages]}・型の値 {seen}"
          + (f"・型の欠測 {int(np.sum(~np.isfinite(kl)))} 名"
             if np.any(~np.isfinite(kl)) else "・型の欠測なし"))
    why = d["why"].dropna().astype(str) if "why" in d.columns else pd.Series(dtype=str)
    why = why[why != ""]
    if len(why):
        top = why.value_counts().head(5).to_dict()
        print(f"  当てはめの失敗 {len(why)} 名: {top}")
    if len(d) < 100:
        print(f"  ★ この実行は {len(d)} 名の抜粋である（1 層 "
              f"{len(d) // max(len(ages), 1)} 名）。**ここから出る数値は読んではいけない。**")

    d, wave_p = merge_wave_sep(d, limit=limit, wave_csv=wave_csv)

    # B 段（--b-stage の型が全部そろって採用した共通例）の印を**表を出す前に 1 回だけ**
    # 数え、列にして持ち回る（表ごとに数え直さない）。A 段は型ごとに分母が違うので、
    # A 段どうしの比較には「どの拍を捨てたか」の差が混ざる。B 段は分母をそろえる。
    miss_b = b_stage_missing(d, variants, b_variants)
    if miss_b:
        d[STAGE_B_COL] = np.zeros(len(d), dtype=bool)
        print(f"  ★ **B 段に使えない型がある: {miss_b}**（--variants に無いか "
              "ok_{型} の列が無い）。")
        print("  ★ B 段は全部偽にする（黙って C 段にはしない）。C2・C3 の B 段の行は"
              "すべて「—」になる。")
    else:
        d[STAGE_B_COL] = b_stage_mask(d, b_variants)
    n_b = int(np.sum(d[STAGE_B_COL].to_numpy(dtype=bool)))
    print(f"  B 段（`--b-stage` の {len(b_variants)} 型 "
          + "・".join(_kind_lab(k) for k in b_variants)
          + f" がすべて採用した共通例）{n_b} 名 / {len(d)} 名")
    if n_b == 0:
        print("  ★ B 段が 0 名である。C2・C3 の B 段の行はすべて「—」になる。")
    out = {"state": 0, "n": len(d), "n_b": n_b, "path": str(path), "info": info,
           "variants": variants, "b_variants": b_variants, "noise_sd": noise_sd,
           "wave_sep": (str(wave_p) if wave_p else "")}
    out["c0"] = print_c0(d, variants, noise_sd=noise_sd)
    out["c1"] = print_c1(d, variants)
    out["c1b"] = print_c1b(d, variants)
    out["c2"] = print_c2(d, variants, b_variants)
    out["c3"] = print_c3(d, variants, b_variants)
    out["c4"] = print_c4(d, variants)
    out["c5"] = print_c5(out["c0"], out["c1"], out["c2"], out["c3"], variants,
                         noise_sd=noise_sd)
    out["c6"] = print_c6(d, variants)
    out["c7"] = print_c7(d, variants)
    out["c8"] = print_c8(d, variants)
    return out


# ---------------------------------------------------------------- まとめ
def print_no_pwdb() -> None:
    """節C を頼まれたのに --pwdb が無いときの案内（CSV が無いときと同じ扱いで落とす）。"""
    print("\n  節C は PWDB の配布物が要る（--pwdb で渡す）。")
    print("  例: python3 scripts/50_reservoir_bench.py --section C --pwdb ~/pwdb --jobs 8")
    print("  配布物は Charlton らの PWDB（pwdb_haemod_params.csv・pwdb_model_configs.csv・")
    print("  pwdb_pw_indices.csv・PWs/csv/PWs_Digital_PPG.csv）を置いたフォルダである。")


def report(section: str, d=None, src: str = "", taus=TAUS_FULL, dts=DTS_FULL,
           ris=RIS_FULL, seed: int = SEED_A, pwdb=None, limit: int = 0, jobs: int = 1,
           variants=VARIANTS_DEFAULT, refit_csv=None, resume: bool = True,
           b_variants=B_STAGE_DEFAULT, noise_sd: float = 0.0) -> dict:
    """節A（ΔT）・節A-2（RI）・節B・節C を印字する。返り値は計算した値と終了コード。"""
    print("\n" + "=" * 100)
    print("50番 探索的（事後）: 当てはめの型と、凍結版 ΔT が下限で詰まること")
    print("=" * 100)
    print("  論文2・探索的（事後）。**判定（成立・不成立）は付けない。**事前規準による")
    print("  判定は 26番のものが有効で、この台本の出力は事後の記述である。")
    out = {"code": 0}
    if "A" in section:
        out["A"] = section_a(taus, dts, seed=seed)
        out["A2"] = section_a2(RI_CONDS, ris, seed=seed)
    if "B" in section:
        if d is None:
            print("\n  節B は CSV が無いので走らせない（--csv で 26番の出力を渡す）。")
            out["code"] = 2
        else:
            out["B"] = section_b(d, src)
            if out["B"]["state"] != 0:
                out["code"] = 2
    if "C" in section:
        if pwdb is None:
            print_no_pwdb()
            out["code"] = 2
        else:
            try:
                out["C"] = section_c(Path(pwdb), limit=limit, jobs=jobs,
                                     variants=variants, refit_csv=refit_csv,
                                     resume=resume, d26=d, src26=src,
                                     b_variants=b_variants, noise_sd=noise_sd)
            except (FileNotFoundError, OSError) as e:
                print(f"\n  ★ PWDB を読めない: {e}")
                print_no_pwdb()
                out["code"] = 2
    print("\n" + "-" * 100)
    a_txt = (f"節A 合成脈波（時定数 {len(list(taus))} 通り × 到達 {len(list(dts))} 通り）"
             f"＋ 節A-2（条件 {len(RI_CONDS)} 通り × 大きさ {len(list(ris))} 通り）"
             if "A" in section else "節A・節A-2 なし")
    a_txt2 = (f"当てはめ {len(KIND_KEYS)} 型・雑音 SD {NOISE_SD}・乱数種 {seed}"
              if "A" in section else "")
    b_txt = (f"節B {src}（{len(d)} 名・型の列 {KLASS_COL}・A 段 {COL_OK} == 1）"
             if ("B" in section and d is not None) else "節B なし")
    c = out.get("C")
    c_txt = (f"節C {pwdb}（{c['n']} 名・当てはめ {list(c['variants'])}・"
             f"B 段 {list(c['b_variants'])}・雑音 SD {c['noise_sd']:g}・"
             f"記録 {c['path']}）" if c else "節C なし")
    print("  出典: analysis/scripts/50_reservoir_bench.py")
    print(f"        / {a_txt}")
    if a_txt2:
        print(f"          （{a_txt2}）")
    print(f"        / {b_txt}")
    print(f"        / {c_txt}")
    print("  年齢層内 Spearman の規約は 20番 `20_pwdb_validity.py` の `_spearman`・`_judge`")
    print(f"  をそのまま使う（1 層 {MIN_PER_AGE} 名以上・層は `age` の相異なる値）。")
    return out


# ---------------------------------------------------------------- 自己検査
# 節B の部品を試す合成データ。型3 だけ凍結版 ΔT を FLOOR_SYN_MS で止め、型1 は特徴点法に
# 載せる。これで P1・P2 が「はい」、P3 も「はい」になるはずである。
AGES_SYN = (25, 35, 45, 55, 65, 75)
N_PER_AGE_SYN = 300
LM_LO_SYN, LM_HI_SYN = 60.0, 260.0     # 特徴点法 ΔT の範囲 [ms]
FLOOR_SYN_MS = 150.0                   # 型3 に仕込む下限 [ms]
JIT_SYN_MS = 4.0                       # 当てはめの雑音 [ms]
P_KLASS1_SYN = 0.35
# RI の仕込み（B4・P4・P5 の部品を試すため）。型1 は特徴点法に載せ、型3 は年齢層ごとに
# 関係の強さを変えて、高齢の層ほど逆向きにする。
RI_LO_SYN, RI_HI_SYN = 0.20, 0.70      # 特徴点法 RI の範囲
RI_JIT_SYN = 0.05                      # 当てはめの雑音
RI_SLOPE_SYN = (0.6, 0.4, 0.2, 0.0, -0.3, -0.6)     # 型3 の傾き（25〜75 歳層）
RI_SLOPE_FLAT = 1.0                    # 型1 の傾き（年齢層によらない）
# 真値の仕込み（B6 を試すため。2026-09-15 に足した）。型1 は「同じ年齢層の中で血管が
# 柔らかい側の部分集団」に見立て、PWV_a の散らばりを型3 より**わざと狭く**する。B6 の表が
# その差を出せるかを見るための仕込みであって、PWDB の値を写したものではない。
PWV_MID_SYN = (6.0, 6.8, 7.6, 8.6, 9.8, 11.2)   # 年齢層ごとの PWV_a の中心 [m/s]
PWV_SD_K1, PWV_SD_K3 = 0.25, 1.20      # 型ごとの標準偏差（型1 を狭くする）
PWV_SHIFT_K1 = 0.6                     # 型1 は中心も低い側に置く [m/s]
PVR_MID_SYN = 1.00                     # pvr の中心
PVR_SD_K1, PVR_SD_K3 = 0.10, 0.16      # 型ごとの標準偏差（型1 を狭くする）
SEED_TRUTH_SYN = 101                   # 真値の乱数種の足し前（既存の列の乱数の並びを変えない）


def synth_b(seed: int = 0) -> pd.DataFrame:
    """節B の部品を試す合成データ。

    ΔT: 型3 は下限（FLOOR_SYN_MS）で詰まり、型1 は詰まらない。
    RI: 型1 は特徴点法に載る（ρ ≈ +1・年齢層による差なし）。型3 は年齢層ごとに傾きを
        変え、高齢の層ほど逆向きにする（P4 の仕込み）。
    真値: `PWV_a`・`pvr` を足す（B6 の仕込み）。型1 は型3 より散らばりを**狭く**して
        ある。真値の列は別の乱数の流れ（種 seed + SEED_TRUTH_SYN）で作るので、足しても
        ΔT・RI の列の値は変わらない（既存の検査の数値を動かさないため）。
    """
    rng = np.random.default_rng(seed)
    rng_t = np.random.default_rng(seed + SEED_TRUTH_SYN)
    frames = []
    for k_age, age in enumerate(AGES_SYN):
        n = N_PER_AGE_SYN
        lm = rng.uniform(LM_LO_SYN, LM_HI_SYN, n)
        klass = np.where(rng.random(n) < P_KLASS1_SYN, 1.0, 3.0)
        jit = rng.normal(0.0, JIT_SYN_MS, n)
        v1 = np.where(klass == 1.0, lm + jit, np.maximum(lm, FLOOR_SYN_MS) + jit)
        ri_lm = rng.uniform(RI_LO_SYN, RI_HI_SYN, n)
        ri_jit = rng.normal(0.0, RI_JIT_SYN, n)
        slope = np.where(klass == 1.0, RI_SLOPE_FLAT, RI_SLOPE_SYN[k_age])
        ri_v1 = 0.30 + slope * (ri_lm - 0.45) + ri_jit
        is1 = klass == 1.0
        pwv = (PWV_MID_SYN[k_age] - np.where(is1, PWV_SHIFT_K1, 0.0)
               + np.where(is1, PWV_SD_K1, PWV_SD_K3) * rng_t.standard_normal(n))
        pvr = PVR_MID_SYN + np.where(is1, PVR_SD_K1, PVR_SD_K3) * rng_t.standard_normal(n)
        frames.append(pd.DataFrame({"age": age, KLASS_COL: klass, COL_LM: lm,
                                    COL_V1: v1, COL_RI_LM: ri_lm, COL_RI_V1: ri_v1,
                                    COL_PWV: pwv, COL_PVR: pvr,
                                    COL_OK: 1}))
    return pd.concat(frames, ignore_index=True)


# (4)(4b) が**この変更の前と同じ値を返す**ことを照合するための記録（2026-09-16）。
# 合成の 1 拍 `synth_beat(0.20, 0.45)` に `fit_kind` を当てて、τ の下限を型ごとに引く
# 対応表 `RES_TAU_LO_OF` を入れる**前**の版で測った (ΔT [ms], RI) である
# （測った環境は Python 3.11.15・NumPy 2.4.6・SciPy 1.17.1）。
CONV_REF = {"conv": (230.9637409352338, 0.48128433281878286),
            "conv01": (230.9637409352338, 0.48128294052285514)}
# 照合の許容。**版の違う機械では最後の桁が動きうるので桁を詰めすぎない。**下限 0.15 s が
# 誤って (4)(4b) にも効けば ΔT は ms の単位で動くので、この許容でも取り違えは捕まる。
CONV_REF_TOL_MS = 1e-3
# RI の許容は 2026-09-22 に 1e-6 → 1e-5 に広げた。Mac 1（Python 3.9.6・SciPy 1.13.1）では
# 同じ合成の拍で RI が 1.373e-6 だけ違い（ΔT の差は 0.000e+00、HEAD との動的な照合も
# 0.000e+00）、機械の違いによる最後の桁の差で落ちた（lab_log 追記158）。下限の取り違えは
# RI を 1e-3 の単位で動かすので、1e-5 でも捕まる。
CONV_REF_TOL_RI = 1e-5


def selftest() -> int:
    n_fail = 0

    def rep(name, cond, detail=""):
        nonlocal n_fail
        cond = bool(cond)
        if not cond:
            n_fail += 1
        print(f"  [{'PASS' if cond else 'FAIL'}] {name}" + (f"  {detail}" if detail else ""))

    print("50番 自己検査（合成だけで走る。CSV もネットワークも要らない）")
    print(f"  節A の掃引は {len(TAUS_FAST)} 層 × {len(DTS_FAST)} 拍に減らす"
          f"（本番は {len(TAUS_FULL)} 層 × {len(DTS_FULL)} 拍）。")
    print(f"  節A-2 は {len(RI_CONDS)} 条件 × {len(RIS_FAST)} 拍に減らす"
          f"（本番は {len(RI_CONDS)} 条件 × {len(RIS_FULL)} 拍）。")

    import inspect
    rep("順位相関の規約を 20番と共有している（_spearman・_judge・層の人数）",
        M.CRIT_RHO == 0.30
        and inspect.signature(M._by_age).parameters["min_n"].default == MIN_PER_AGE,
        f"CRIT_RHO {M.CRIT_RHO} / 層の人数 {MIN_PER_AGE}")

    # --- 合成脈波そのもの
    t, y, tr = synth_beat(0.20, 0.45)
    rep("合成脈波を作れる（真値は成分のピークの差で、母数の差とは違う）",
        t.size == int(round(FS * 60.0 / HR_SYN)) and np.isfinite(tr["dt_s"])
        and abs(tr["dt_s"] - 0.20) > 0.005,
        f"{t.size} 標本・真値 {1000 * tr['dt_s']:.0f} ms（設定 200 ms）")

    # --- (a-1) 下限の詰まりの検出器そのもの（いま使う規準と、差し替える前の規準）
    truth5 = np.array([250.0, 200.0, 150.0, 100.0, 50.0])
    stuck = np.array([250.0, 200.0, 190.0, 187.0, 185.0])   # 下限 185 ms で止めた列
    prop = np.array([255.0, 205.0, 155.0, 105.0, 55.0])     # 真値に比例する列
    f_stuck, f_prop = floor_check(truth5, stuck), floor_check(truth5, prop)
    rep("(a) 検出器: 人工的に下限で止めた列で「あり」（新しい規準・差し替える前の規準とも）",
        f_stuck["flag_gap"] and f_stuck["flag_range"],
        f"返り値の最小 − 真値の最大 {f_stuck['gap']:+.0f} ms"
        f"（要 {FLOOR_GAP_MS:.0f} 以上）・下位 {FLOOR_N} 拍の範囲 {f_stuck['rng']:.0f} ms")
    rep("(a) 検出器: 真値に比例する列では「なし」（同上）",
        (not f_prop["flag_gap"]) and (not f_prop["flag_range"]),
        f"返り値の最小 − 真値の最大 {f_prop['gap']:+.0f} ms・"
        f"下位 {FLOOR_N} 拍の範囲 {f_prop['rng']:.0f} ms")

    # --- 節A を減らした掃引で 1 回走らせる（(a-2)・(b)・(e) で使い回す）
    buf = io.StringIO()
    with redirect_stdout(buf):
        a0 = section_a(TAUS_FAST, DTS_FAST, seed=SEED_A)
    txt_a0 = buf.getvalue()
    summ, res = a0["summ"], a0["res"]
    rep("節A が減らした掃引で最後まで印字される",
        "A2. 時定数の層ごとの表" in txt_a0 and len(txt_a0) > 1000,
        f"{len(txt_a0)} 文字・{len(TAUS_FAST)} 層 × {len(DTS_FAST)} 拍")

    # --- (a-2) 凍結版が短い側で下限に詰まる（本文の所見そのもの）
    det = []
    for tau in TAUS_FAST:
        rec = res[float(tau)]
        truth = np.asarray(rec["truth"], float)
        got = np.asarray(rec["got"]["frozen"], float)
        order = np.argsort(truth)
        d2 = abs(got[order[0]] - got[order[1]])          # 真値が 20 ms 違う 2 拍
        td = abs(truth[order[0]] - truth[order[1]])      # その 2 拍の真値の差
        fl = summ[("frozen", float(tau))]["floor"]
        det.append((tau, d2, fl["got_min"] - float(np.min(truth)), fl, td))
    # 規準は「返り値の差が真値の差の 1/4 未満」（順位の尺度が 4 倍以上に縮んでいる）。
    # 2026-09-15 までは「差 1 ms 未満」だったが、それは汎用の起点 4 点の複製が 2 拍で
    # 同じ値を返していたことに合わせた文言で、凍結版本体は 173・175 ms（差 1.7 ms）を
    # 返す。起点を凍結版と同じにしたときに実態に合わせて直した（lab_log 追記143）。
    rep("(a) 凍結版は短い側で下限に詰まる（真値が 20 ms 違う 2 拍で返り値の差が真値の差の"
        " 1/4 未満）",
        all(dd < 0.25 * td for _t, dd, _g, _fl, td in det),
        "・".join(f"時定数 {t_:.2f}s 返り値の差 {dd:.1f} ms（真値の差 {td:.0f} ms）"
                  for t_, dd, _g, _fl, td in det))
    rep("(a) 凍結版の返り値の最小は真値の最小より 60 ms 以上大きい（短い側を追えない）",
        all(g >= 60.0 for _t, _d, g, _fl, _td in det),
        "・".join(f"時定数 {t_:.2f}s +{g:.0f} ms" for t_, _d, g, _fl, _td in det))

    # 新しい規準（2026-09-15 差し替え）の検算。時定数 0.45 s の層で、凍結版だけが「あり」
    tau0 = float(TAUS_FAST[0])
    fl_fz = summ[("frozen", tau0)]["floor"]
    rep(f"(a) 新しい規準で凍結版が「あり」（時定数 {tau0:.2f} s の層）",
        fl_fz["flag_gap"],
        f"下位 {FLOOR_N} 拍の返り値の最小 {fl_fz['lo']:.0f} ms − 真値の最大 "
        f"{fl_fz['truth_max']:.0f} ms = {fl_fz['gap']:+.0f} ms（要 {FLOOR_GAP_MS:.0f} 以上）")
    none_keys = ("relax", "conv", "conv01", "trunc")
    rep("(a) 新しい規準で Δμ0.01・畳み込み・(4b) 畳み込み＋Δμ0.01・0.65T は「なし」"
        f"（時定数 {tau0:.2f} s の層）",
        all(not summ[(k, tau0)]["floor"]["flag_gap"] for k in none_keys),
        "・".join(f"{_kind_no(k)}{KIND_HEAD[k]} {summ[(k, tau0)]['floor']['gap']:+.0f} ms"
                  for k in none_keys))

    # (0) 凍結版本体も、複製 (1) と同じように短い側で下限に詰まるか。閾値 60 ms は上の
    # (1) の検査と同じものを使う。ここが落ちたら、複製が本体と同じ振る舞いをしていない。
    det_fb = []
    for tau in TAUS_FAST:
        tmin = float(np.min(np.asarray(res[float(tau)]["truth"], float)))
        det_fb.append((float(tau),
                       summ[("fb", float(tau))]["floor"]["got_min"] - tmin,
                       summ[("frozen", float(tau))]["floor"]["got_min"] - tmin))
    rep("(0) 凍結版本体も短い側で下限に詰まる（複製 (1) と同じ印）",
        summ[("fb", tau0)]["floor"]["flag_gap"]
        and all(np.isfinite(g0) and g0 >= 60.0 for _t, g0, _g1 in det_fb),
        "返り値の最小 − 真値の最小: "
        + "・".join(f"時定数 {t_:.2f}s (0) {g0:+.0f} ms / (1) {g1:+.0f} ms"
                    for t_, g0, g1 in det_fb))
    print("    参考: 差し替える前の規準（下位 3 拍の返り値の範囲 < "
          f"{FLOOR_RANGE_MS:.0f} ms）での凍結版の印字は "
          + "・".join(f"時定数 {t_:.2f}s {_ari(fl['flag_range'])}"
                      f"（範囲 {fl['rng']:.0f} ms）" for t_, _d, _g, fl, _td in det)
          + "。これが取り逃がしである。")

    # (0)(4b)(4c)(5b)(6b): 凍結版本体が先頭にあり、一度に 1 つだけ変える版が並んでいるか
    rep("当てはめの型が 17 行あり、先頭が (0) 凍結版本体・(4b) は (2) と (4) の同時適用・"
        "(4c) は (4) と τ の下限だけが違い・"
        "(5b)(6b) は Δμ の下限だけが (5)(6) と違い・(6c)(6d) は (6b) と割合だけが違い・"
        "(6e) は切る位置の決め方だけが違い・(7)(8)(9) は末尾にあって Δμ は緩めていない",
        len(KIND_KEYS) == 17 and KIND_KEYS[0] == "fb"
        and KIND_NO["fb"] == "(0)" and KIND_NO["conv01"] == "(4b)"
        and KIND_SHAPE["conv01"] == "conv"
        and KIND_NO["conv15"] == "(4c)" and KIND_SHAPE["conv15"] == "conv"
        and ("conv15" in KIND_DMU_FROZEN)
        and RES_TAU_LO_OF["conv"] == 0.05 and RES_TAU_LO_OF["conv01"] == 0.05
        and RES_TAU_LO_OF["decay"] == 0.05 and RES_TAU_LO_OF["conv15"] == 0.15
        and ("conv01" not in KIND_DMU_FROZEN) and ("fb" in KIND_DMU_FROZEN)
        and KIND_NO["tied08"] == "(5b)" and KIND_NO["trunc08"] == "(6b)"
        and KIND_NO["trunc055"] == "(6c)" and KIND_NO["trunc075"] == "(6d)"
        and KIND_SHAPE["tied08"] == KIND_SHAPE["tied"]
        and KIND_SHAPE["trunc08"] == KIND_SHAPE["trunc"]
        and KIND_SHAPE["trunc055"] == "plain" and KIND_SHAPE["trunc075"] == "plain"
        and ("tied08" in KIND_DMU_FROZEN) and ("trunc08" in KIND_DMU_FROZEN)
        and ("trunc055" in KIND_DMU_FROZEN) and ("trunc075" in KIND_DMU_FROZEN)
        and ("tied" not in KIND_DMU_FROZEN) and ("trunc" not in KIND_DMU_FROZEN)
        and TRUNC_FRAC_OF["trunc055"] == 0.55 and TRUNC_FRAC_OF["trunc08"] == 0.65
        and TRUNC_FRAC_OF["trunc075"] == 0.75
        # 2026-09-16 に足した 4 行（lab_log 追記149）。番号・形・Δμ の下限を照合する。
        and KIND_NO["truncabs"] == "(6e)" and KIND_SHAPE["truncabs"] == "plain"
        and TRUNC_ABS_OF["truncabs"] == 0.45 and TRUNC_ABS_MAXFRAC == 0.90
        and KIND_NO["convout"] == "(7)" and KIND_SHAPE["convout"] == "convout"
        and KIND_NO["deconv2"] == "(8)" and KIND_SHAPE["deconv2"] == "deconv2"
        and KIND_NO["deriv"] == "(9)" and KIND_SHAPE["deriv"] == "plain"
        and list(KIND_KEYS[-3:]) == ["convout", "deconv2", "deriv"]
        and KIND_KEYS.index("truncabs") == KIND_KEYS.index("trunc075") + 1
        and all(k in KIND_DMU_FROZEN
                for k in ("truncabs", "convout", "deconv2", "deriv"))
        and all(np.isfinite(res[tau0]["got"][k]).all()
                for k in ("fb", "conv01", "conv15", "tied08", "trunc08",
                          "trunc055", "trunc075", "truncabs", "convout", "deriv")),
        "・".join(f"{_kind_no(k)} ρ {summ[(k, tau0)]['rho']:+.2f}"
                  for k in ("fb", "frozen", "conv", "conv01", "conv15", "tied",
                            "tied08", "trunc", "trunc08", "trunc055", "trunc075",
                            "truncabs", "convout", "deconv2", "deriv")))

    # (4c) の τ の下限が効いているか（2026-09-16 に足した。lab_log 追記146）。減らした
    # 掃引の全拍で、(4c) が選んだ τ は下限 0.15 s を下回らないはずである。あわせて (4) が
    # 自分の下限 0.05 s に届く拍があることを見る（下限の位置が結果を変えている証拠）。
    # (4) が届かない掃引では**規準を緩めず**、(4c) の側だけを検査してそのことを書く。
    tau15 = [v for rc in res.values() for v in rc["tau_fit"]["conv15"] if np.isfinite(v)]
    tau04 = [v for rc in res.values() for v in rc["tau_fit"]["conv"] if np.isfinite(v)]
    lo_tau15 = min(tau15) if tau15 else float("nan")
    lo_tau04 = min(tau04) if tau04 else float("nan")
    hit04 = [v for v in tau04 if v <= RES_TAU_LO_OF["conv"] + CHK_TOL]
    rep("(4c) の τ は下限 0.15 s を下回らない"
        + ("・(4) は自分の下限 0.05 s に届く拍がある" if hit04
           else "（この掃引では (4) が 0.05 s に届かないので (4c) の側だけを検査した）"),
        bool(tau15) and lo_tau15 >= RES_TAU_LO_OF["conv15"] - CHK_TOL,
        f"(4c) の τ の最小 {lo_tau15:.4f} s（{len(tau15)} 拍・下限 "
        f"{RES_TAU_LO_OF['conv15']:.2f} s）・(4) の τ の最小 {lo_tau04:.4f} s"
        f"（下限 {RES_TAU_LO_OF['conv']:.2f} s に届いた拍 {len(hit04)}/{len(tau04)}）")

    # (4)(4b) がこの変更の前と同じ値を返すか（新しい対応表が既存の型を動かしていない）。
    # 記録は CONV_REF（対応表を入れる前の版で同じ合成の 1 拍から測った値）。あわせて探索
    # 範囲そのものも照合する: (4) の τ の下限は 0.05 s のままで、(4c) との違いは τ の下限
    # の 1 つだけ（ほかの母数の上下限も Δμ の下限も同じ）である。
    t_ref, y_ref, _tr_ref = synth_beat(0.20, 0.45)
    ys_ref = _norm(y_ref)
    lo_cv, hi_cv, dmu_cv = _bounds(t_ref, ys_ref, "conv")
    lo_15, hi_15, dmu_15 = _bounds(t_ref, ys_ref, "conv15")
    d_cv_dt, d_cv_ri = 0.0, 0.0
    for k_ref, (dt_ref, ri_ref) in CONV_REF.items():
        r_ref = fit_kind(t_ref, y_ref, k_ref)
        d_cv_dt = max(d_cv_dt, abs(1000.0 * r_ref["dt_s"] - dt_ref))
        d_cv_ri = max(d_cv_ri, abs(r_ref["ri"] - ri_ref))
    rep("(4)(4b) はこの変更の前と同じ値を返す（探索範囲も (4c) と τ の下限だけが違う）",
        lo_cv[9] == 0.05 and _bounds(t_ref, ys_ref, "conv01")[0][9] == 0.05
        and _bounds(t_ref, ys_ref, "decay")[0][9] == 0.05 and lo_15[9] == 0.15
        and lo_cv[:9] == lo_15[:9] and hi_cv == hi_15 and dmu_cv == dmu_15
        and d_cv_dt <= CONV_REF_TOL_MS and d_cv_ri <= CONV_REF_TOL_RI,
        f"(4) の τ の下限 {lo_cv[9]:.2f} s・(4c) は {lo_15[9]:.2f} s・ほかの上下限と "
        f"Δμ の下限（{dmu_cv:.2f} s）は同じ・ΔT の差の最大 {d_cv_dt:.3e} ms"
        f"（要 {CONV_REF_TOL_MS:.0e} 以下）・RI の差の最大 {d_cv_ri:.3e}"
        f"（要 {CONV_REF_TOL_RI:.0e} 以下）")

    # ============================================================ HEAD との照合
    # **既存の当てはめを 1 ビットも動かしていないこと**の検査（2026-09-17 に自己検査へ
    # 移した。それまでは型を足すたびに手で同じことをしていた。lab_log 追記151）。
    # `git show HEAD:<この台本>` を一時の場所に出し、別名で読み込んで、同じ 3 拍 ×
    # 全 17 型の ΔT・RI・残差・診断の印・境界の内訳を突き合わせる。
    import tempfile as _tf
    import time as _tm
    t_hd = _tm.time()
    with _tf.TemporaryDirectory() as td_h:
        head_m, why_head = _head_module(Path(td_h))
        if head_m is None:
            rep("既存 17 型の当てはめは HEAD と同じ（**git が使えないので照合しない**）",
                True, why_head + "。git のある機械で走らせること")
        else:
            beats_h = [synth_beat(0.20, 0.45), synth_beat(0.10, 0.35),
                       synth_beat(0.28, 0.25, hr=90.0)]
            keys_h = ("ok", "boundary", "amp_zero", "ambiguous", "dmu_lo",
                      "tau_hi", "tau_lo")
            d_dt_h, d_ri_h, d_cs_h = 0.0, 0.0, 0.0
            n_h, n_bad_h, n_nan_h = 0, 0, 0
            for t_h, y_h, _tr_h in beats_h:
                for k_h in KIND_KEYS:
                    a_h, b_h = fit_kind(t_h, y_h, k_h), head_m.fit_kind(t_h, y_h, k_h)
                    n_h += 1
                    for q, box in (("dt_s", "dt"), ("ri", "ri"), ("cost", "cost")):
                        x_h, z_h = float(a_h[q]), float(b_h[q])
                        if np.isfinite(x_h) != np.isfinite(z_h):
                            n_nan_h += 1               # 片方だけ欠測（これも食い違い）
                            continue
                        if not np.isfinite(x_h):
                            continue
                        gap_h = abs(x_h - z_h)
                        if box == "dt":
                            d_dt_h = max(d_dt_h, gap_h)
                        elif box == "ri":
                            d_ri_h = max(d_ri_h, gap_h)
                        else:
                            d_cs_h = max(d_cs_h, gap_h)
                    if any(bool(a_h["checks"][q]) != bool(b_h["checks"][q])
                           for q in keys_h) or (list(a_h["checks"].get("pins", []))
                                                != list(b_h["checks"].get("pins", []))):
                        n_bad_h += 1
            rep("既存 17 型の当てはめが HEAD と 1 ビットも違わない"
                "（3 拍 × 17 型の ΔT・RI・残差・診断・境界の内訳）",
                d_dt_h == 0.0 and d_ri_h == 0.0 and d_cs_h == 0.0
                and n_bad_h == 0 and n_nan_h == 0 and n_h == 3 * len(KIND_KEYS),
                f"{n_h} 通りを照合・ΔT の差の最大 {d_dt_h:.3e} s・RI {d_ri_h:.3e}・"
                f"残差 {d_cs_h:.3e}・診断の食い違い {n_bad_h} 通り・"
                f"欠測の食い違い {n_nan_h} 件（{_tm.time() - t_hd:.0f} 秒）")

    # t1・t2（2026-09-17 に `fit_kind` の返り値に足した鍵）。ΔT = t2 − t1 であり、
    # 合成の拍では第1成分の真のピーク（`synth_beat` が返す `t_fwd`）に近いはずである。
    r_t1_fb, r_t1_fz = fit_kind(t, y, "fb"), fit_kind(t, y, "frozen")
    gap_t1 = abs(1000.0 * (r_t1_fb["t1_s"] - tr["t_fwd"]))
    rep("`fit_kind` が第1成分・第2成分のピーク時刻（t1・t2）を返し、ΔT = t2 − t1 になる",
        np.isfinite(r_t1_fb["t1_s"]) and np.isfinite(r_t1_fb["t2_s"])
        and abs((r_t1_fb["t2_s"] - r_t1_fb["t1_s"]) - r_t1_fb["dt_s"]) <= 1e-12
        and abs(r_t1_fz["t1_s"] - r_t1_fb["t1_s"]) <= 1e-9
        and gap_t1 <= 5.0,
        f"(0) t1 {1000 * r_t1_fb['t1_s']:.2f} ms・t2 {1000 * r_t1_fb['t2_s']:.2f} ms"
        f"（合成の第1成分の真のピーク {1000 * tr['t_fwd']:.2f} ms・差 {gap_t1:.2f} ms）・"
        f"(1) t1 {1000 * r_t1_fz['t1_s']:.2f} ms")

    # 打ち切りの割合が本当に配線されているか（2026-09-15 に足した。lab_log 追記145）。
    # 3 つの割合は同じ拍に別々の ΔT を返さなければならない。返り値が同じなら、割合が
    # `fit_kind` まで届いていない（TRUNC_FRAC_OF を引いていない）ということである。
    tri = ("trunc055", "trunc08", "trunc075")
    spread, n_tri = 0.0, 0
    for rc in res.values():
        vals = [np.asarray(rc["got"][k], float) for k in tri]
        for i in range(len(rc["truth"])):
            v = [float(x[i]) for x in vals]
            if not all(np.isfinite(x) for x in v):
                continue
            pair = min(abs(v[0] - v[1]), abs(v[1] - v[2]), abs(v[0] - v[2]))
            spread = max(spread, max(v) - min(v))
            n_tri += int(pair > 1.0)
    rep("打ち切りの割合 0.55・0.65・0.75 は同じ拍に別々の ΔT を返す（割合が配線されている）",
        n_tri >= 1,
        f"3 つが 1 ms を超えて違う拍が {n_tri} 拍・返り値の開きの最大 {spread:.1f} ms")
    # KIND_TRUNC は割合で切る型と絶対時間で切る型の両方を覆う（(6e) を足した
    # 2026-09-16 に広げた。**主の割合 0.65 は動かしていない**）。
    rep("主の割合は 0.65 のまま（(6) と (6b) が使う値。事前に決めた値を動かさない）",
        TRUNC_FRAC == 0.65 and TRUNC_FRAC_OF["trunc"] == 0.65
        and TRUNC_FRAC_OF["trunc08"] == 0.65
        and set(KIND_TRUNC) == set(TRUNC_FRAC_OF) | set(TRUNC_ABS_OF)
        and set(TRUNC_FRAC_OF) & set(TRUNC_ABS_OF) == set(),
        f"TRUNC_FRAC {TRUNC_FRAC}・"
        + "・".join(f"{_kind_no(k)} {TRUNC_FRAC_OF[k]:.2f}T" for k in TRUNC_FRAC_OF)
        + "・" + "・".join(f"{_kind_no(k)} {TRUNC_ABS_OF[k]:.2f}s（上限 "
                          f"{TRUNC_ABS_MAXFRAC:.2f}T）" for k in TRUNC_ABS_OF))

    # ============================================================ (6e)(7)(8)(9)
    # 2026-09-16 に足した 4 行の検算（lab_log 追記149。**走らせる前に設計を固定した**）。

    # (7) は τ → 0 で凍結版そのものに戻るか（入れ子。**(4) に無かった性質**）。
    # 核は単位面積で、τ → 0 では [1, 0, 0, …] になるので畳み込みは恒等写像になる。
    p_c7 = [1.0, 0.10, 0.045, 2.5, 0.45, 0.20, 0.087, 1.2, 1e-6]
    g1_c7, g2_c7 = _components(p_c7, "convout")
    base_c7 = skew_gaussian(t, *g1_c7) + skew_gaussian(t, *g2_c7)
    d_c7 = float(np.max(np.abs(_model(p_c7, t, "convout") - base_c7)))
    pk_c7 = float(np.max(base_c7))
    k_c7 = _res_kernel(t, 1e-6)
    rep("(7) は τ → 0 で凍結版に一致する（入れ子なので縮退する向きが無い）",
        d_c7 <= 1e-6 * pk_c7 and abs(float(k_c7[0]) - 1.0) < 1e-12
        and float(np.max(np.abs(k_c7[1:]))) == 0.0,
        f"τ = 1e-6 で 模型 − (g1+g2) の最大 {d_c7:.3e}"
        f"（要 ピーク {pk_c7:.3f} の 1e-06 倍 = {1e-6 * pk_c7:.3e} 以下）・"
        f"核の先頭 {float(k_c7[0]):.6f}・残りの最大 {float(np.max(np.abs(k_c7[1:]))):.1e}")

    # (8) の逆畳み込みが正しいか。既知の x を既知の τ で畳み込み、x = y + τ·y′ で戻す。
    # 端は因果的な畳み込みの立ち上がりが残るので、中央 80% で測る（規準は実装の前に
    # 決めた「ピークの 2%」）。
    tau_d8 = 0.3
    x_d8 = (skew_gaussian(t, A_FWD, TP_F - 0.02, SIG_FWD, AL_FWD)
            + skew_gaussian(t, A_REF, TP_F + 0.20 - 0.02,
                            W_REF_A + W_REF_B * 0.20, AL_REF))
    y_d8 = np.convolve(x_d8, _res_kernel(t, tau_d8))[:t.size]
    xh_d8 = y_d8 + tau_d8 * np.gradient(y_d8, t)
    i0_d8, i1_d8 = int(0.10 * t.size), int(0.90 * t.size)
    e_d8 = float(np.max(np.abs(xh_d8[i0_d8:i1_d8] - x_d8[i0_d8:i1_d8])))
    pk_d8 = float(np.max(x_d8))
    rep("(8) の逆畳み込み x = y + τ·y′ が元の波を戻す（中央 80%・ピークの 2% 以内）",
        e_d8 <= 0.02 * pk_d8,
        f"最大の差 {e_d8:.5f} = ピーク {pk_d8:.3f} の {100 * e_d8 / pk_d8:.2f}%"
        f"（要 2% 以下・τ {tau_d8:.2f} s・{i1_d8 - i0_d8} 標本）")

    # (9) が本当に微分の残差を使っているか。母数・探索範囲・起点・解の選び方は凍結版と
    # 同じなので、**残差の領域を変えていなければ (1) と 1 ビットも違わない値になる。**
    n_dv, gap_dv = 0, 0.0
    for rc in res.values():
        a_dv = np.asarray(rc["got"]["deriv"], float)
        b_dv = np.asarray(rc["got"]["frozen"], float)
        ok_dv = np.isfinite(a_dv) & np.isfinite(b_dv)
        if ok_dv.any():
            n_dv += int(np.sum(np.abs(a_dv[ok_dv] - b_dv[ok_dv]) > 1e-9))
            gap_dv = max(gap_dv, float(np.max(np.abs(a_dv[ok_dv] - b_dv[ok_dv]))))
    rep("(9) は微分の残差を使っている（(1) と同じ設定なのに別の解になる）",
        n_dv >= 1,
        f"(1) と ΔT が 1e-9 ms を超えて違う拍 {n_dv} 拍・差の最大 {gap_dv:.1f} ms")

    # (6e) が切る時刻。心拍数 70 の拍では 0.45 s、心拍数 140 の短い拍では 0.90 × 拍長。
    r_ab70 = fit_kind(t, y, "truncabs")
    t_ab, y_ab, _tr_ab = synth_beat(0.10, 0.45, hr=2.0 * HR_SYN)
    r_ab140 = fit_kind(t_ab, y_ab, "truncabs")
    T_ab = float(t_ab[-1] - t_ab[0])
    ord_tr = list(_order_cols(pd.DataFrame([{"subj_no": 1, "pin_trunc08": "-",
                                             "cut_trunc08_s": 0.5}]),
                              ("trunc08",)).columns)
    rep("(6e) は 0.45 s で切り、拍が短いときは 0.90 × 拍長で切る（切った時刻を記録する）",
        abs(r_ab70["cut_s"] - TRUNC_ABS_S) <= 1e-12
        and abs(r_ab140["cut_s"] - TRUNC_ABS_MAXFRAC * T_ab) <= 1e-12
        and r_ab140["cut_s"] < TRUNC_ABS_S
        and not np.isfinite(fit_kind(t, y, "frozen")["cut_s"])
        and ord_tr == ["subj_no", "pin_trunc08", "cut_trunc08_s"],
        f"心拍数 {HR_SYN:.0f}（拍長 {float(t[-1] - t[0]):.4f} s）で "
        f"{r_ab70['cut_s']:.4f} s・心拍数 {2 * HR_SYN:.0f}（拍長 {T_ab:.4f} s）で "
        f"{r_ab140['cut_s']:.4f} s ＝ {TRUNC_ABS_MAXFRAC:.2f} × 拍長 "
        f"{TRUNC_ABS_MAXFRAC * T_ab:.4f} s・切らない型は欠測")

    # (7) の τ が下限にあるとき、「境界」に数えず tau_lo にだけ数えるか。
    lo_c7, hi_c7, _dmu_c7 = _bounds(t, _norm(y), "convout")
    p_mid = [0.5 * (a_ + b_) for a_, b_ in zip(lo_c7, hi_c7)]
    p_mid[8] = lo_c7[8]
    pins_c7, _lh, _hh, thi_c7, tlo_c7 = _pins_of(p_mid, lo_c7, hi_c7, "convout")
    n_tlo = sum(1 for rc in res.values()
                for c in rc["checks"]["convout"] if c.get("tau_lo"))
    n_bnd_tlo = sum(1 for rc in res.values() for c in rc["checks"]["convout"]
                    if c.get("tau_lo") and c.get("boundary"))
    rep("(7) の τ の下限は「境界」に数えず、別の印 tau_lo に数える",
        tlo_c7 and (not thi_c7) and (not pins_c7)
        and lo_c7[8] == CONVOUT_TAU_LO and hi_c7[8] == CONVOUT_TAU_HI
        and "τ下限" in txt_a0,
        f"τ = 下限 {lo_c7[8]:.2f} s だけが端にある解で tau_lo {tlo_c7}・"
        f"境界の内訳 {pins_c7 or '（無し）'}・掃引で τ が下限だった拍 {n_tlo}"
        f"（うち境界の印も立った拍 {n_bnd_tlo}）")

    # --- (b) 畳み込み貯留槽の ρ が凍結版より大きい
    pairs = [(tau, summ[("frozen", float(tau))]["rho"], summ[("conv", float(tau))]["rho"])
             for tau in TAUS_FAST]
    rep("(b) 畳み込み貯留槽の ρ が凍結版より大きい（両層）",
        all(np.isfinite(a) and np.isfinite(b) and b > a for _t, a, b in pairs),
        "・".join(f"時定数 {t_:.2f}s 凍結版 {a:+.2f} → 畳み込み {b:+.2f}"
                  for t_, a, b in pairs))

    # --- 節A-2（RI）を減らした掃引で走らせる
    bufr = io.StringIO()
    with redirect_stdout(bufr):
        a2 = section_a2(RI_CONDS, RIS_FAST, seed=SEED_A)
    txt_a2 = bufr.getvalue()
    s2 = a2["summ"]
    rep("節A-2 が減らした掃引で最後まで印字される",
        "A2-1. 条件ごとの表" in txt_a2 and len(txt_a2) > 1000,
        f"{len(txt_a2)} 文字・条件 {len(RI_CONDS)} 通り × 大きさ {len(RIS_FAST)} 通り")
    rho_fz3 = s2[("frozen", "型3 相当")]["rho"]
    rho_rx3 = s2[("relax", "型3 相当")]["rho"]
    rho_fz1 = s2[("frozen", "型1 相当")]["rho"]
    rep("(a2) 型3 相当で凍結版の RI の ρ が負（符号の反転）",
        s2[("frozen", "型3 相当")]["flip"] and rho_fz3 < RHO_FLIP,
        f"ρ {rho_fz3:+.2f}（規準 {RHO_FLIP:+.2f} より小さいとき反転）")
    rho_fb3 = s2[("fb", "型3 相当")]["rho"]
    rep("(a2) (0) 凍結版本体も型3 相当で反転（複製と同じ）",
        s2[("fb", "型3 相当")]["flip"],
        f"(0) ρ {rho_fb3:+.2f}・(1) ρ {rho_fz3:+.2f}"
        f"（規準 {RHO_FLIP:+.2f} より小さいとき反転）")
    rep("(a2) 同じ条件で Δμ0.01 は正（下限を緩めると反転が消える）",
        np.isfinite(rho_rx3) and rho_rx3 > 0
        and not s2[("relax", "型3 相当")]["flip"],
        f"Δμ0.01 ρ {rho_rx3:+.2f}・凍結版 ρ {rho_fz3:+.2f}")
    rho_cv01_3 = s2[("conv01", "型3 相当")]["rho"]
    rep("(a2) (4b) 畳み込み＋Δμ0.01 は型3 相当で正",
        np.isfinite(rho_cv01_3) and rho_cv01_3 > 0
        and not s2[("conv01", "型3 相当")]["flip"],
        f"(4b) ρ {rho_cv01_3:+.2f}・(1) ρ {rho_fz3:+.2f}")
    rep("(a2) 型1 相当では凍結版も反転しない",
        np.isfinite(rho_fz1) and rho_fz1 > 0 and not s2[("frozen", "型1 相当")]["flip"],
        f"ρ {rho_fz1:+.2f}")
    rep("(a2) RI の真値は 2 通りとも順位が同じ（母数 a_ref と成分のピーク高さの比）",
        all(np.array_equal(np.argsort(np.asarray(r["truth"], float)),
                           np.argsort(np.asarray(r["ri_peak"], float)))
            for r in a2["res"].values()),
        "母数で計算した ρ と比で計算した ρ は同じ順位になる")

    # --- (f) 再実装 (1) と凍結版本体 (0) の照合（2026-09-15 に足した）。
    # 起点の作り方・解の選び方・成分のピークの求め方を凍結版と同じにしたので、(1) は
    # (0) と同じ解に行き着くはずである。節A（2 層 × 5 拍）と節A-2（2 条件 × 4 拍）の
    # 全拍で照合する。ここが落ちたら、写した複製が本体と別の当てはめになっている。
    d_dt = 0.0
    for rc in res.values():
        d_dt = max(d_dt, float(np.max(np.abs(
            np.asarray(rc["got"]["frozen"], float)
            - np.asarray(rc["got"]["fb"], float)))))
    d_ri = 0.0
    for rc in a2["res"].values():
        d_ri = max(d_ri, float(np.max(np.abs(
            np.asarray(rc["got"]["frozen"], float)
            - np.asarray(rc["got"]["fb"], float)))))
    rep("(1) は (0) と同じ値を返す（再実装の照合）",
        d_dt <= 1e-6 and d_ri <= 1e-9,
        f"ΔT の差の最大 {d_dt:.3e} ms（要 1e-06 以下）・"
        f"RI の差の最大 {d_ri:.3e}（要 1e-09 以下）")

    n_chk, n_dif = 0, 0
    for rc in list(res.values()) + list(a2["res"].values()):
        for c_fb, c_fz in zip(rc["checks"]["fb"], rc["checks"]["frozen"]):
            n_chk += 1
            if any(bool(c_fb[q]) != bool(c_fz[q])
                   for q in ("ok", "boundary", "amp_zero", "ambiguous")):
                n_dif += 1
    rep("(1) の診断は (0) の検算と一致する", n_dif == 0,
        f"{n_chk} 拍で 通過・境界・高さ・別解 の 4 つを照合し、食い違い {n_dif} 拍")

    # 境界の内訳（2026-09-15 に足した）。内訳が空でないことと「境界」の印が立つことは
    # 同値でなければならない（τ の上限は境界に数えないので、内訳にも入らない）。
    n_pin, n_bad_pin, n_any = 0, 0, 0
    for rc in list(res.values()) + list(a2["res"].values()):
        for k in KIND_KEYS:
            for c in rc["checks"][k]:
                n_pin += 1
                pins = c.get("pins", [])
                n_any += int(bool(pins))
                if bool(pins) != bool(c["boundary"]):
                    n_bad_pin += 1
    rep("境界の内訳は「境界」の印と食い違わない（空でないことと境界が立つことが同値）",
        n_bad_pin == 0 and n_any > 0,
        f"節A {len(TAUS_FAST)} 層・節A-2 {len(RI_CONDS)} 条件 × 当てはめ "
        f"{len(KIND_KEYS)} 型の {n_pin} 拍で照合し、食い違い {n_bad_pin} 拍"
        f"（内訳が空でない拍は {n_any}）")

    n_dif_pin = 0
    for rc in list(res.values()) + list(a2["res"].values()):
        for c_fb, c_fz in zip(rc["checks"]["fb"], rc["checks"]["frozen"]):
            if list(c_fb.get("pins", [])) != list(c_fz.get("pins", [])):
                n_dif_pin += 1
    rep("(1) の境界の内訳は (0) のものと同じ（母数の名前まで一致する）",
        n_dif_pin == 0,
        f"{n_chk} 拍で照合し、食い違い {n_dif_pin} 拍")

    n_bad = 0
    for rc in list(res.values()) + list(a2["res"].values()):
        for k in KIND_KEYS:
            rows = rc["checks"][k]
            n_ok = sum(1 for c in rows if c["ok"])
            if len(rows) != len(rc["truth"]) or not 0 <= n_ok <= len(rows):
                n_bad += 1
    rep("診断の表が印字され、通過数は拍数を超えない",
        n_bad == 0 and "Δμ下限" in txt_a0 and "Δμ下限" in txt_a2,
        f"節A {len(TAUS_FAST)} 層・節A-2 {len(RI_CONDS)} 条件 × 当てはめ "
        f"{len(KIND_KEYS)} 型で数を照合し、食い違い {n_bad} 件")

    # --- (c) 節B の計算部品を、下限で詰まる列を人工的に作った表で確かめる
    db = synth_b(seed=0)
    bufb = io.StringIO()
    with redirect_stdout(bufb):
        sb = section_b(db, "合成データ（自己検査）")
    txt_b = bufb.getvalue()
    rep("(c) 節B が合成の表で最後まで印字される",
        sb["state"] == 0 and "B5. 予測との照合" in txt_b,
        f"{len(db)} 行・{len(txt_b)} 文字")
    b2, bp = sb["b2"], sb["b5"]
    low3 = b2[3]["bins"][:PRED_P1_N_BINS]
    rep("(c) P1: 型3 は下から 2 区間でも凍結版 ΔT の中央値が下がらない",
        bp["P1"] and all(abs(b["med"] - FLOOR_SYN_MS) < 3.0 for b in low3),
        "・".join(f"[{b['lo']:.0f},{b['hi']:.0f}) 中央値 {b['med']:.1f} ms" for b in low3)
        + f"（仕込んだ下限 {FLOOR_SYN_MS:.0f} ms）")
    rep("(c) P2: 型3 は短い側の ρ が長い側より 0.15 以上小さい",
        bp["P2"], f"差 {_n(bp['gap3'], 3, sign=True)}")
    rep("(c) P3: 型1（下限を仕込んでいない）は差が 0.15 未満",
        bp["P3"], f"差 {_n(bp['gap1'], 3, sign=True)}")
    rep("(c) 型1 の凍結版 ΔT の最小は特徴点法に追随する（下限を仕込んでいない）",
        b2[1]["v1_min"] < FLOOR_SYN_MS - 40.0,
        f"型1 の最小 {b2[1]['v1_min']:.1f} ms・型3 の最小 {b2[3]['v1_min']:.1f} ms")
    rep("(c) 下限を仕込まない表では P1 が「いいえ」になる（検査が効いている）",
        not _p1_of(synth_b_nofloor(seed=0)),
        "型3 にも下限を仕込まない合成データで照合した")
    b4 = sb["b4"]
    r3, r1 = bp["ri3"], bp["ri1"]
    rep("(c) P4: 型3 の ρ(ri_v1, digital_ri) は中央値 0.30 未満・75 歳層 0.20 未満",
        bp["P4"],
        f"中央値 {_n(r3['med'], 3, sign=True)}・75 歳層 {_n(r3['old'], 3, sign=True)}"
        f"・年齢との順位相関 {_n(r3['trend'], 2, sign=True)}")
    rep("(c) P5: 型1 は中央値 0.60 以上で年齢層による差が 0.15 未満",
        bp["P5"],
        f"中央値 {_n(r1['med'], 3, sign=True)}・最若層 {_n(r1['young'], 3, sign=True)}"
        f"・最高齢層 {_n(r1['old'], 3, sign=True)}・差 {_n(r1['span'], 3)}")
    rep("(c) B4 の表が型ごと・年齢層ごとに並ぶ（A 段と C 段）",
        set(b4.keys()) >= {1, 3} and b4[3]["A"]["n_ages"] == len(AGES_SYN)
        and b4[1]["C"]["n_ages"] == len(AGES_SYN),
        f"型3 の層 {b4[3]['A']['n_ages']}・型1 の層 {b4[1]['A']['n_ages']}")
    rep("(c) 型3 も特徴点法に追随する表では P4 が「いいえ」になる（検査が効いている）",
        not _p4_of(synth_b_ri_flat(seed=0)),
        "型3 の傾きを型1 と同じにした合成データで照合した")

    # --- (c) B6（真値そのもののばらつき。2026-09-15 に足した）
    b6 = sb["b6"]["types"]
    w1 = b6.get(1, {}).get("iqr_med", {}).get(COL_PWV, float("nan"))
    w3 = b6.get(3, {}).get("iqr_med", {}).get(COL_PWV, float("nan"))
    rep("(c) B6 が B4 の後・B5 の前に印字され、型 × 年齢層の表が出る",
        "B6. 真値そのもののばらつき" in txt_b
        and txt_b.index("B4. 型ごとの") < txt_b.index("B6. 真値そのもののばらつき")
        < txt_b.index("B5. 予測との照合")
        and b6.get(1, {}).get("n_ages") == len(AGES_SYN)
        and b6.get(3, {}).get("n_ages") == len(AGES_SYN)
        and "範囲の制限" in txt_b and "予測は立てて" in txt_b,
        f"型1 の層 {b6.get(1, {}).get('n_ages')}・型3 の層 "
        f"{b6.get(3, {}).get('n_ages')}・型1 の最小の層 n "
        f"{b6.get(1, {}).get('min_n')}")
    rep("(c) B6 で型1 の PWV_a の四分位範囲の幅が型3 より狭く出る（仕込みどおり）",
        np.isfinite(w1) and np.isfinite(w3) and w1 < w3
        and np.isfinite(sb["b6"]["ratio"][COL_PWV])
        and sb["b6"]["ratio"][COL_PWV] < 1.0,
        f"幅の中央値 型1 {w1:.3f}・型3 {w3:.3f}・比 "
        f"{sb['b6']['ratio'][COL_PWV]:.3f}"
        f"（仕込みの標準偏差 型1 {PWV_SD_K1}・型3 {PWV_SD_K3}）")
    db_notruth = db.drop(columns=[COL_PWV, COL_PVR])
    buf6 = io.StringIO()
    with redirect_stdout(buf6):
        sb6 = section_b(db_notruth, "合成データ（真値の列を抜いた）")
    txt_b6 = buf6.getvalue()
    rep("(c) PWV_a・pvr が無い表では B6 を飛ばし、そのことを 1 行で印字して先へ進む",
        sb6["state"] == 0 and sb6["b6"] == {}
        and "B6 は計算できない" in txt_b6 and COL_PWV in txt_b6
        and "B5. 予測との照合" in txt_b6,
        f"終了の状態 {sb6['state']}・B6 の返り値 {sb6['b6']}")

    # --- (d) 列が無い CSV
    d_miss = db.drop(columns=[COL_V1])
    bufm = io.StringIO()
    with redirect_stdout(bufm):
        out_m = report("B", d_miss, "合成データ（列を抜いた）")
    txt_m = bufm.getvalue()
    rep("(d) 列が無い CSV で落ちずに「列が無い」と印字し、終了コード 2 になる",
        out_m["code"] == 2 and "列が無い" in txt_m and COL_V1 in txt_m,
        f"終了コード {out_m['code']}")

    # --- (e) 同じ乱数種なら出力が同一
    def render(seed):
        b = io.StringIO()
        with redirect_stdout(b):
            section_a(TAUS_FAST, DTS_FAST, seed=seed)
        return b.getvalue()

    t_same, t_other = render(SEED_A), render(SEED_A + 1)
    rep("(e) 同じ乱数種なら出力が同一", t_same == txt_a0, f"{len(t_same)} 文字")
    rep("(e) 乱数種を変えれば値は変わる（比較が効いている）", t_other != txt_a0)

    # --- (g) 節C を模擬 PWDB（26番の自己検証と同じもの）で通す。**ネットワークは要らない。**
    # 実 PWDB は無いので、26番の `_selftest_root` が作る模擬の配布物を使う。ここで検査するのは
    # 処理系（拍の作り方・記録・再開・表が最後まで出ること）であって、当てはめの優劣ではない。
    import tempfile
    import time as _time
    t_c = _time.time()
    with tempfile.TemporaryDirectory() as td:
        refit_p = Path(td) / "50_refit_selftest.csv"
        vars_c = ("fb", "relax")
        # 51番の記録は**わざと無い場所**を指す。この機械に実データの 51_wave_sep.csv が
        # あると、模擬の被験者番号に実データの前進波が結合されてしまい、自己検査が
        # 機械によって変わる（C7 の「51番が無いときの案内」もここで通す）。
        no_wave = Path(td) / "51_wave_sep_none.csv"
        bufm = io.StringIO()
        with redirect_stdout(bufm):        # 模擬の作成と読み込みの print は表に出さない
            m26 = _load("26_pwdb_compare.py", "m26")
            root, _kinds = m26._selftest_root(Path(td), n=48)
            hae_, _cfg_, ppg_, _x_ = M.load_pwdb(root)
        rep("(g) --limit の取り方が 26番の `_stride` と同じ",
            list(c_stride(ppg_, 24).iloc[:, 0]) == list(m26._stride(ppg_, 24).iloc[:, 0])
            and len(c_stride(ppg_, len(ppg_) + 5)) == len(ppg_),
            f"{len(ppg_)} 名から 24 名・端から端まで")

        rep("(g) --limit のときの記録は別名になる（全例の記録を上書きしない。26番と同じ規約）",
            _refit_path(None, 0).name == REFIT_NAME
            and _refit_path(None, 300).name == "50_refit_limit300.csv"
            and _refit_path(refit_p, 300) == refit_p,
            f"{_refit_path(None, 0).name} / {_refit_path(None, 300).name}")

        bufc = io.StringIO()
        with redirect_stdout(bufc):
            c1 = section_c(root, limit=24, jobs=1, variants=vars_c, refit_csv=refit_p,
                           resume=True, d26=None, b_variants=vars_c,
                           wave_csv=no_wave)
        txt_c1 = bufc.getvalue()
        need_cols = ["subj_no", "fs", "n_samp", "klass_own", "sys_own_ms", "dia_own_ms",
                     "noise_sd"]
        for k in vars_c:
            need_cols += ([f"dt_{k}_ms", f"t1_{k}_ms", f"ri_{k}", f"ok_{k}", f"cost_{k}"]
                          + [f"{tag}_{k}" for tag, _q in CHK_COLS])
        got = pd.read_csv(refit_p)
        rep("(g) 節C が記録（CSV）を書き、要る列が揃う（型 2 つぶん）",
            refit_p.exists() and all(c in got.columns for c in need_cols)
            and len(got) == 24 and got["subj_no"].is_unique,
            f"{len(got)} 名・{len(got.columns)} 列・"
            f"当てはめた {c1['info']['n_fit']} 名")

        txt_first = refit_p.read_text(encoding="utf-8")
        bufc2 = io.StringIO()
        with redirect_stdout(bufc2):
            c2 = section_c(root, limit=24, jobs=1, variants=vars_c, refit_csv=refit_p,
                           resume=True, d26=None, b_variants=vars_c,
                           wave_csv=no_wave)
        rep("(g) 再開すると 1 名も当てはめ直さず、記録も同じ内容になる",
            c2["info"]["n_fit"] == 0 and c2["info"]["n_cache"] == 24
            and refit_p.read_text(encoding="utf-8") == txt_first,
            f"当てはめ直した {c2['info']['n_fit']} 名・再利用 {c2['info']['n_cache']} 名")

        # 境界の内訳の列（2026-09-15 に足した）。これが無い記録は古いので、再開の
        # ときに当てはめ直されなければならない。列を落とした記録を作って確かめる。
        pin_cols = [f"pin_{k}" for k in vars_c]
        pd.read_csv(refit_p).drop(columns=pin_cols).to_csv(refit_p, index=False)
        bufc3 = io.StringIO()
        with redirect_stdout(bufc3):
            c3 = section_c(root, limit=24, jobs=1, variants=vars_c, refit_csv=refit_p,
                           resume=True, d26=None, b_variants=vars_c,
                           wave_csv=no_wave)
        got3 = pd.read_csv(refit_p)
        rep("(g) 記録に境界の内訳 pin_{型} の列があり、値が入っている",
            all(c in got.columns for c in pin_cols)
            and all(c in got3.columns for c in pin_cols)
            and bool(got3[pin_cols[0]].astype(str).str.strip().ne("").all()),
            f"列 {pin_cols}・(0) の値の例 "
            + "・".join(sorted(set(got3[pin_cols[0]].astype(str)))[:3]))
        rep("(g) pin_{型} が無い記録は再開のときに当てはめ直す（古い記録を使い回さない）",
            c3["info"]["n_fit"] == 24 and c3["info"]["n_cache"] == 0,
            f"当てはめ直した {c3['info']['n_fit']} 名・再利用 {c3['info']['n_cache']} 名"
            "（列を落とす前の再開は 0 名だった）")

        # 3 名だけ、記録の値が `fit_beat` ＋ `si_ri_from_fit` の直接計算と一致するか
        from src.indices import si_ri_from_fit
        hr_by_ = dict(zip(hae_["subj_no"].astype(int), hae_["HR"].astype(float)))
        d_dt, d_ri, n_ok_same, n_chk = 0.0, 0.0, 0, 0
        idx_by = dict((int(ppg_.iloc[i, 0]), i) for i in range(len(ppg_)))
        for subj in [int(v) for v in got["subj_no"].head(3)]:
            row = got[got["subj_no"] == subj]
            i = idx_by[subj]
            y_, fs_ = M.beat_of(ppg_.iloc[i].to_numpy(float), hr_by_.get(subj, np.nan))
            if y_ is None:
                continue
            fit = pda.fit_beat(np.arange(y_.size) / fs_, y_)
            ix = si_ri_from_fit(fit)
            n_chk += 1
            d_dt = max(d_dt, abs(float(row["dt_fb_ms"].iloc[0]) - 1000.0 * ix["dt_s"]))
            d_ri = max(d_ri, abs(float(row["ri_fb"].iloc[0]) - ix["ri"]))
            n_ok_same += int(int(row["ok_fb"].iloc[0]) == int(bool(fit["ok"])))
        rep("(g) 記録の dt_fb_ms・ri_fb・ok_fb が `fit_beat` ＋ `si_ri_from_fit` と一致する",
            n_chk == 3 and d_dt <= 1e-9 and d_ri <= 1e-9 and n_ok_same == 3,
            f"{n_chk} 名で照合・ΔT の差 {d_dt:.3e} ms・RI の差 {d_ri:.3e}・"
            f"採否の一致 {n_ok_same}/{n_chk}")

        kl_ = pd.to_numeric(got["klass_own"], errors="coerce").to_numpy(float)
        rep("(g) 型 klass_own は 1・3・4・5 か欠測のいずれか（26番と同じ付け方）",
            bool(np.all([(not np.isfinite(v)) or int(v) in (1, 3, 4, 5) for v in kl_])),
            f"値 {sorted(set(int(v) for v in kl_[np.isfinite(kl_)]))}")

        rep("(g) C1〜C5 の表が最後まで印字され、予測は照合できないか はい／いいえ になる",
            all(h in txt_c1 for h in ("C1. 採否と縮退", "C2. ΔT ×", "C3. RI ×",
                                      "C4. 一致", "C5. 予測との照合"))
            and "まとめ: 予測 5 条のうち" in txt_c1
            and c1["c5"]["n_eval"] == 0 and c1["c5"]["hit"] == 0,
            f"{len(txt_c1)} 文字・照合できた予測 {c1['c5']['n_eval']} 条"
            "（模擬は 1 層 4 名なのでどの層も評価できない）")
        rep("(g) 26番の列が無いので C0 と P10 は「照合できない」になる",
            c1["c0"]["state"] == "照合できない" and not c1["c5"]["P10"]["ev"]
            and "P10 検算  (0) と 26番の列: 照合できない" in txt_c1)

        # C1b（境界の内訳）が C1 の後に出て、型 × 当てはめのます目が埋まっているか。
        # 模擬の拍では境界に付く母数が無いことがあるので、「—」でも表としては正しい。
        c1b = c1["c1b"]
        rep("(g) C1b 境界の内訳が C1 の後に印字され、型 × 当てはめのます目が揃う",
            "C1b. 境界の内訳" in txt_c1
            and txt_c1.index("C1. 採否と縮退") < txt_c1.index("C1b. 境界の内訳")
            < txt_c1.index("C2. ΔT ×")
            and set(c1b.keys()) == set((kt, k) for kt, _nm in _ktypes()
                                       for k in vars_c),
            f"ます目 {len(c1b)} 個・全例の (0) は 解が出た拍 "
            f"{c1b[(None, 'fb')]['n']} ・内訳 "
            + (("・".join(f"{nm} {c}" for nm, c in c1b[(None, 'fb')]["rows"][:PIN_TOP]))
               or "どの母数も端に付かない"))

        # B 段（比べるすべての手法が採用した共通例。2026-09-16 に足した。追記149）。
        # 定義から **B 段はどの型の A 段の部分集合**であり、いちばん小さい A 段より
        # 大きくならない。C2 の表の人数（段ごとの分母）でも同じ順序が成り立つ。
        got_b = pd.read_csv(refit_p)
        bm = b_stage_mask(got_b, vars_c)
        am = dict((k, (pd.to_numeric(got_b[f"ok_{k}"], errors="coerce") == 1)
                   .to_numpy(dtype=bool)) for k in vars_c)
        sub_ok = all(bool(np.all(a_[bm])) for a_ in am.values())
        n_bad_b = 0
        for k in vars_c:
            for kt, _nm in _ktypes():
                n_a = c1["c2"][(f"dt_{k}_ms", "A", kt)]["n"]
                n_b = c1["c2"][(f"dt_{k}_ms", "B", kt)]["n"]
                n_c = c1["c2"][(f"dt_{k}_ms", "C", kt)]["n"]
                n_bad_b += int(not (n_b <= n_a <= n_c))
        rep("(g) B 段はどの型の A 段の部分集合でもあり、いちばん小さい A 段を超えない",
            sub_ok and int(bm.sum()) <= min(int(a_.sum()) for a_ in am.values())
            and n_bad_b == 0
            and "段 B = `--b-stage` の" in txt_c1
            and "すべて採用した共通例" in txt_c1
            and "B 段の人数（波形の型ごと" in txt_c1
            and "**C4 は A 段と C 段だけである**" in txt_c1,
            f"B 段 {int(bm.sum())} 名・A 段 "
            + "・".join(f"{_kind_no(k)} {int(am[k].sum())} 名" for k in vars_c)
            + f"・C2 の段の人数（B ≤ A ≤ C）の食い違い {n_bad_b} 件")
        rep("(g) 節C は B 段の人数を表を出す前に 1 回だけ数え、返り値に入れる",
            0 <= c1["n_b"] <= c1["n"] and c1["n_b"] <= int(bm.sum()),
            f"節C の返り値 {c1['n_b']} 名 / 突き合わせ {c1['n']} 名"
            f"（記録から数えた共通例 {int(bm.sum())} 名。真値の表と突き合わせる段で"
            "減ることはある）")

        # ============================================================ 2026-09-17 の追加
        # --- C6・C7・C8 が C5 の後に印字され、返り値に入る
        rep("(g) C6・C7・C8 が C5 の後に印字され、節C の返り値に入る",
            all(h in txt_c1 for h in ("C6. 採否の偏り", "C7. 第1成分のピーク時刻 t1",
                                      "C8. 振った因子ごとの主効果"))
            and txt_c1.index("C5. 予測との照合") < txt_c1.index("C6. 採否の偏り")
            < txt_c1.index("C7. 第1成分のピーク時刻 t1")
            < txt_c1.index("C8. 振った因子ごとの主効果")
            and all(q in c1 for q in ("c6", "c7", "c8"))
            and "**この表は C 段だけである。**" in txt_c1
            and "**C7 は A 段と C 段だけである**" in txt_c1
            and "**C8 は A 段と C 段だけである**" in txt_c1,
            f"ます目 C6 {len(c1['c6'])} 個・C7 {len(c1['c7'])} 個・C8 {len(c1['c8'])} 個")

        # --- C6（W4 採否の偏り）。通過率は ok_{型} の平均そのもの、三分位は年齢層ごと
        got_c6 = pd.read_csv(refit_p)
        ok_fb6 = pd.to_numeric(got_c6["ok_fb"], errors="coerce").to_numpy(float)
        ter6 = _tertile_in_age(
            pd.DataFrame({"age": [25] * 9 + [35] * 9,
                          COL_PWV: list(range(9)) + list(range(9))}), COL_PWV)
        rep("(g) C6 は C 段の通過率（ok_{型} の平均）を出し、三分位は年齢層ごとに切る",
            abs(c1["c6"][(None, "ok_fb")]["ok"] - float(np.nanmean(ok_fb6))) <= 1e-12
            and c1["c6"][(None, "ok_fb")]["n"] == int(np.isfinite(ok_fb6).sum())
            and list(ter6) == [0, 0, 0, 1, 1, 1, 2, 2, 2] * 2
            and len(c1["c6"][(None, "ok_fb")]["tertile"]) == len(C6_TERT),
            f"通過率 {c1['c6'][(None, 'ok_fb')]['ok']:.3f}"
            f"（記録から {float(np.nanmean(ok_fb6)):.3f}）・"
            f"三分位の通過率 "
            + "・".join(f"{q} {_n(v)}" for q, v in
                        zip(C6_TERT, c1["c6"][(None, "ok_fb")]["tertile"])))

        # --- C7（W5 第1成分の位置）。仕込んだ差がそのまま中央値に出るか
        n_c7 = 24
        d_c7t = pd.DataFrame({
            "subj_no": np.arange(1, n_c7 + 1), "age": 25.0, KLASS_COL: 1.0,
            "sys_own_ms": 100.0 + np.arange(n_c7, dtype=float),
            "t1_fb_ms": 107.0 + np.arange(n_c7, dtype=float),      # 収縮期 +7 ms
            COL_PF: 120.0 + np.arange(n_c7, dtype=float),          # 前進波 −13 ms
            "ok_fb": 1, COL_PWV: 6.0 + 0.1 * np.arange(n_c7, dtype=float)})
        d_c7t[STAGE_B_COL] = False
        with redirect_stdout(io.StringIO()):
            c7t = print_c7(d_c7t, ("fb",))
        rec_c7 = c7t[(1, "fb", "C")]
        rep("(g) C7 の t1 と差が仕込んだ値と一致する（t1 − 収縮期 +7 ms・t1 − 前進波 −13 ms）",
            rec_c7["n"] == n_c7
            and abs(rec_c7["t1"] - float(np.median(d_c7t["t1_fb_ms"]))) <= 1e-12
            and abs(rec_c7["d_sys"] - 7.0) <= 1e-12
            and abs(rec_c7["d_pf"] + 13.0) <= 1e-12
            and abs(rec_c7["rho_pf"] - 1.0) <= 1e-9,
            f"n {rec_c7['n']}・t1 の中央値 {rec_c7['t1']:.1f} ms・"
            f"t1 − 収縮期 {rec_c7['d_sys']:+.1f} ms・t1 − 前進波 {rec_c7['d_pf']:+.1f} ms・"
            f"ρ(t1, 前進波) {rec_c7['rho_pf']:+.3f}")
        rep("(g) 51番の記録が無いと C7 の前進波の 2 列は「—」になり、走らせ方を案内する",
            c1["wave_sep"] == "" and "51番の記録" in txt_c1
            and "51_pwdb_wave_separation.py" in txt_c1
            and all(not np.isfinite(c1["c7"][(None, k, "C")]["d_pf"]) for k in vars_c),
            f"51番の記録 {c1['wave_sep'] or '（無し）'}")

        # --- C8（W1b 因子ごとの主効果）。20番の `_factor_effects` と同じ値になるか
        n_c8 = 6 * 30
        rng_c8 = np.random.default_rng(7)
        lv_c8 = rng_c8.integers(-1, 2, size=(n_c8, len(M.FACTORS)))
        d_c8t = pd.DataFrame({"subj_no": np.arange(1, n_c8 + 1),
                              "age": np.repeat(list(AGES_SYN), n_c8 // 6).astype(float),
                              KLASS_COL: 1.0, "ok_fb": 1})
        for j, f_ in enumerate(M.FACTORS):
            d_c8t[f"var_{f_}"] = lv_c8[:, j].astype(float)
        d_c8t["dt_fb_ms"] = (200.0 - 20.0 * lv_c8[:, M.FACTORS.index("pwv")]
                             + rng_c8.normal(0.0, 2.0, n_c8))
        d_c8t["ri_fb"] = (0.40 + 0.05 * lv_c8[:, M.FACTORS.index("mbp")]
                          + rng_c8.normal(0.0, 0.01, n_c8))
        d_c8t[STAGE_B_COL] = False
        with redirect_stdout(io.StringIO()):
            c8t = print_c8(d_c8t, ("fb",))
        e_ref, r_ref = M._factor_effects(d_c8t, "dt_fb_ms")
        e_got = c8t[(None, "dt_fb_ms", "C")]["eff"]
        r_got = c8t[(None, "dt_fb_ms", "C")]["rho"]
        i_pwv = M.FACTORS.index("pwv")
        rep("(g) C8 は 20番の `_factor_effects` と同じ値を返す（計算し直していない）",
            np.array_equal(np.asarray(e_got), np.asarray(e_ref), equal_nan=True)
            and np.array_equal(np.asarray(r_got), np.asarray(r_ref), equal_nan=True)
            and float(e_got[i_pwv]) < -10.0 and float(r_got[i_pwv]) < -0.5,
            "仕込んだ 脈波伝播速度 −1/+1 で ΔT が ±20 ms 動く合成の表で、"
            f"主効果 {float(e_got[i_pwv]):+.1f}%・ρ {float(r_got[i_pwv]):+.2f}")
        with redirect_stdout(io.StringIO()) as buf_c8n:
            c8n = print_c8(d_c8t.drop(columns=[f"var_{f_}" for f_ in M.FACTORS]),
                           ("fb",))
        rep("(g) var_{因子} が無い表では C8 を飛ばし、案内を印字して落ちない",
            c8n == {} and "C8 は計算できない" in buf_c8n.getvalue()
            and "var_pwv" in buf_c8n.getvalue(),
            "変動表の列を抜いた表で照合した")

        # --- B 段を候補で絞る（--b-stage。2026-09-17）
        d_bs = pd.DataFrame({"ok_fb": [1, 1, 0, 1], "ok_trunc08": [1, 0, 1, 1],
                             "ok_deriv": [1, 1, 1, 0], "ok_relax": [0, 0, 0, 0]})
        m_bs = b_stage_mask(d_bs, B_STAGE_DEFAULT)
        rep("(g) B 段は `--b-stage` の型すべての A 段の部分集合で、既定は fb,trunc08,deriv",
            B_STAGE_DEFAULT == ("fb", "trunc08", "deriv")
            and list(m_bs) == [True, False, False, False]
            and all(bool(np.all((d_bs[f"ok_{k}"] == 1).to_numpy()[m_bs]))
                    for k in B_STAGE_DEFAULT),
            f"B 段 {int(m_bs.sum())}/4 名・A 段 "
            + "・".join(f"{_kind_no(k)} {int((d_bs[f'ok_{k}'] == 1).sum())} 名"
                        for k in B_STAGE_DEFAULT))
        rep("(g) `--b-stage` に無い型が不採用でも B 段には入りうる（B 段は挙げた型だけで決まる）",
            bool(m_bs[0]) and int(d_bs["ok_relax"].iloc[0]) == 0,
            "(2) Δμ0.01 は 4 名とも不採用だが、1 人目は B 段に入る")
        rep("(g) `--b-stage` の型が `--variants` に無い・列が無いときは B 段を全部偽にする",
            b_stage_missing(d_bs, ("fb", "trunc08"), B_STAGE_DEFAULT) == ["deriv"]
            and b_stage_missing(d_bs, KIND_KEYS, ("convout",)) == ["convout"]
            and b_stage_missing(d_bs, KIND_KEYS, B_STAGE_DEFAULT) == []
            and not b_stage_mask(d_bs, ("convout",)).any(),
            "型が足りないときは黙って C 段にせず、★ を印字して全部偽にする")

        # --- 記録の保ち（--variants を絞っても、指定しなかった型の列が消えない）
        import shutil as _sh
        p_keep = Path(td) / "keep.csv"
        _sh.copy2(refit_p, p_keep)
        # (0) の t1 の列だけを落として「古い記録」を作る。読み書きで最後の桁が動かない
        # よう、記録と同じ `float_precision="round_trip"` で読む（`_cached_rows` と同じ）。
        pd.read_csv(p_keep, float_precision="round_trip").drop(
            columns=["t1_fb_ms"]).to_csv(p_keep, index=False)
        base_keep = pd.read_csv(p_keep)        # 当て直す前の記録（これと突き合わせる）
        with redirect_stdout(io.StringIO()):
            _kk, _pp, info_k = build_refit(root, limit=6, jobs=1, variants=("fb",),
                                           refit_csv=p_keep, resume=True)
        got_k = pd.read_csv(p_keep).set_index("subj_no")
        base_i = base_keep.set_index("subj_no")
        keep_cols = [c for c in base_keep.columns if "relax" in c]
        # 記録の被験者は減らない（`--limit` で選ばれなかった行も残る）。**その実行で
        # 新しく当てた被験者が増える**ことはあるので、元からある被験者だけを突き合わせる
        # （増えた行の (2) の列は欠測になり、列の型が int から float に変わる。だから
        # 文字ではなく数として比べる。`pin_` だけは文字の列なので文字で比べる）。
        common = [s_ for s_ in base_i.index if s_ in got_k.index]
        bad_keep = [c for c in keep_cols if not c.startswith("pin_")
                    and not np.array_equal(
                        pd.to_numeric(got_k.loc[common, c], errors="coerce").to_numpy(float),
                        pd.to_numeric(base_i.loc[common, c], errors="coerce").to_numpy(float),
                        equal_nan=True)]
        bad_keep += [c for c in keep_cols if c.startswith("pin_")
                     and got_k.loc[common, c].astype(str).tolist()
                     != base_i.loc[common, c].astype(str).tolist()]
        same_keep = not bad_keep
        rep("(g) 2 型で書いた記録に 1 型だけ指定して当て直しても、もう 1 型の列は失われない",
            info_k["n_fit"] == 6 and len(common) == len(base_i)
            and all(c in got_k.columns for c in keep_cols) and same_keep
            and int(np.isfinite(pd.to_numeric(got_k["t1_fb_ms"],
                                              errors="coerce")).sum()) >= 6,
            f"当て直した {info_k['n_fit']} 名・記録に残った元の被験者 {len(common)}/"
            f"{len(base_i)} 名・保たれた (2) の列 {len(keep_cols)} 個"
            + (f"（食い違い {bad_keep}）" if bad_keep else "") + "・"
            f"t1_fb_ms が入った {int(np.isfinite(pd.to_numeric(got_k['t1_fb_ms'], errors='coerce')).sum())} 名")

        # --- W6 の雑音（--noise）
        hr_n = dict(zip(hae_["subj_no"].astype(int), hae_["HR"].astype(float)))
        fin_n = [int(v) for v, ok_ in zip(
            got["subj_no"],
            np.isfinite(pd.to_numeric(got["dt_fb_ms"], errors="coerce"))) if ok_]
        sub_n = fin_n[0]
        row_n = ppg_.iloc[idx_by[sub_n]].to_numpy(float)
        r_n0 = refit_subject((sub_n, row_n, hr_n.get(sub_n, np.nan), ("fb",), 0.0))
        y_n, fs_n = M.beat_of(row_n, hr_n.get(sub_n, np.nan))
        r_direct = fit_kind(np.arange(y_n.size) / fs_n, y_n, "fb")
        rep("(g) --noise 0 は雑音なしと 1 ビットも違わない（拍に何も足さない）",
            abs(r_n0["dt_fb_ms"] - 1000.0 * r_direct["dt_s"]) == 0.0
            and abs(r_n0["ri_fb"] - r_direct["ri"]) == 0.0
            and abs(r_n0["t1_fb_ms"] - 1000.0 * r_direct["t1_s"]) == 0.0
            and float(r_n0["noise_sd"]) == 0.0,
            f"ΔT の差 {abs(r_n0['dt_fb_ms'] - 1000.0 * r_direct['dt_s']):.3e} ms・"
            f"RI の差 {abs(r_n0['ri_fb'] - r_direct['ri']):.3e}")
        sd_n = 0.01
        r_n1 = refit_subject((sub_n, row_n, hr_n.get(sub_n, np.nan), ("fb",), sd_n))
        rng_n = np.random.default_rng(SEED_NOISE + sub_n)
        y_noisy = y_n + (sd_n * float(np.ptp(y_n))) * rng_n.standard_normal(y_n.size)
        rep("(g) --noise 0.01 で拍は変わるが、波形の型・収縮期ピークは変わらない",
            float(np.max(np.abs(y_noisy - y_n))) > 0.0
            and "klass_own" in r_n0 and "sys_own_ms" in r_n0
            and r_n1.get("klass_own") == r_n0.get("klass_own")
            and r_n1.get("sys_own_ms") == r_n0.get("sys_own_ms")
            and r_n1.get("dia_own_ms") == r_n0.get("dia_own_ms")
            and float(r_n1["noise_sd"]) == sd_n,
            f"拍の差の最大 {float(np.max(np.abs(y_noisy - y_n))):.5f}"
            f"（峰から谷まで {float(np.ptp(y_n)):.3f}）・型 {r_n1.get('klass_own')}・"
            f"収縮期 {_n(float(r_n1.get('sys_own_ms', float('nan'))), 1)} ms・"
            f"ΔT は {r_n0['dt_fb_ms']:.1f} → {r_n1['dt_fb_ms']:.1f} ms")
        rep("(g) --noise の記録は別のファイルになる（雑音なしの記録を上書きしない）",
            _refit_path(None, 0, 0.0).name == REFIT_NAME
            and _refit_path(None, 0, 0.01).name == "50_refit_noise0.01.csv"
            and _refit_path(None, 24, 0.01).name == "50_refit_noise0.01_limit24.csv"
            and _refit_path(None, 24, 0.0).name == "50_refit_limit24.csv",
            f"{_refit_path(None, 0, 0.01).name} / "
            f"{_refit_path(None, 24, 0.01).name}")
        err_n = ""
        try:
            with redirect_stdout(io.StringIO()):
                build_refit(root, limit=6, jobs=1, variants=("fb",),
                            refit_csv=p_keep, resume=True, noise_sd=0.02)
        except ValueError as e:
            err_n = str(e)
        rep("(g) 記録の noise_sd と --noise が違えば止める（雑音の違う行を混ぜない）",
            "noise_sd" in err_n and "0.02" in err_n,
            (err_n[:70] + "…") if err_n else "止まらなかった")

        # --- --no-resume は上書きの前に退避する
        p_bak = Path(td) / "bak.csv"
        _sh.copy2(refit_p, p_bak)
        n_before = len(pd.read_csv(p_bak))
        with redirect_stdout(io.StringIO()) as buf_bk:
            build_refit(root, limit=6, jobs=1, variants=("fb",), refit_csv=p_bak,
                        resume=False)
        baks = sorted(Path(td).glob("bak.csv.bak-*"))
        rep("(g) --no-resume は既存の記録を退避してから上書きする（15 時間の記録を消さない）",
            len(baks) == 1 and len(pd.read_csv(baks[0])) == n_before
            and len(pd.read_csv(p_bak)) == 6
            and "既存の記録を退避した" in buf_bk.getvalue(),
            f"退避 {baks[0].name if baks else '（無し）'}（{n_before} 名）→ "
            f"書き直した記録 {len(pd.read_csv(p_bak))} 名")

    # --- (g) --pwdb が無いまま節C を頼まれたら、落ちずに終了コード 2
    bufp = io.StringIO()
    with redirect_stdout(bufp):
        out_p = report("C", None, "")
    txt_p = bufp.getvalue()
    rep("(g) --pwdb が無いまま節C を頼まれたら案内を出して終了コード 2 になる",
        out_p["code"] == 2 and "節C は PWDB の配布物が要る" in txt_p,
        f"終了コード {out_p['code']}")
    print(f"    節C の自己検査に {_time.time() - t_c:.0f} 秒")

    # --- 既定の CSV があれば節B を走らせる（動くことの確認だけ）
    print("\n  --- 既定の CSV で節B を走らせる（動くことの確認だけ）---")
    if DEFAULT_CSV.exists():
        d_real = pd.read_csv(DEFAULT_CSV)
        bufr = io.StringIO()
        with redirect_stdout(bufr):
            out_r = report("B", d_real, str(DEFAULT_CSV))
        txt_r = bufr.getvalue()
        rep("既定の CSV で節B が例外なく最後まで印字される",
            out_r["code"] == 0 and "B5. 予測との照合" in txt_r,
            f"{len(d_real)} 行・終了コード {out_r['code']}・{len(txt_r)} 文字")
        if len(d_real) < 100:
            rows = out_r["B"]["b3"].get((3, "A"), {}).get("all", {})
            rep("抜粋では 8 名以上の年齢層が無く、ρ が計算できないことが表に出る",
                rows.get("n_ages", 0) == 0,
                f"評価できた層 {rows.get('n_ages', 0)}")
            print(f"  ★ この機械の {DEFAULT_CSV.name} は {len(d_real)} 行の抜粋である。")
            print("  ★ **ここから出る数値は読んではいけない。**確認的解析の機械の"
                  " 4,374 行で走らせること。")
    else:
        rep("既定の CSV が無い機械でも自己検査は通る", True, f"{DEFAULT_CSV} が無い")

    print("\n" + ("自己検証: 通過" if n_fail == 0 else f"自己検証: 失敗 {n_fail} 件"))
    return 0 if n_fail == 0 else 1


def synth_b_nofloor(seed: int = 0) -> pd.DataFrame:
    """(c) の対照。型3 にも下限を仕込まない（P1 が「いいえ」になるはず）。"""
    d = synth_b(seed=seed)
    rng = np.random.default_rng(seed + 1)
    d[COL_V1] = _colv(d, COL_LM) + rng.normal(0.0, JIT_SYN_MS, len(d))
    return d


def _p1_of(d: pd.DataFrame) -> bool:
    """P1 だけを静かに計算する（自己検査の対照用）。"""
    b = floor_bins(stage_a(subset(d, 3)))
    low = b["bins"][:PRED_P1_N_BINS]
    return bool(low) and len(low) == PRED_P1_N_BINS and all(
        np.isfinite(x["med"]) and x["med"] >= PRED_P1_FLOOR_MS for x in low)


def synth_b_ri_flat(seed: int = 0) -> pd.DataFrame:
    """(c) の対照。型3 の RI も型1 と同じ傾きにする（P4 が「いいえ」になるはず）。"""
    d = synth_b(seed=seed)
    rng = np.random.default_rng(seed + 2)
    d[COL_RI_V1] = (0.30 + RI_SLOPE_FLAT * (_colv(d, COL_RI_LM) - 0.45)
                    + rng.normal(0.0, RI_JIT_SYN, len(d)))
    return d


def _p4_of(d: pd.DataFrame) -> bool:
    """P4 だけを静かに計算する（自己検査の対照用）。"""
    s = strat(rho_rows(stage_a(subset(d, 3)), xcol=COL_RI_V1, ycol=COL_RI_LM))
    rows = [(a, r) for a, r, _n in s["rows"] if np.isfinite(r)]
    if not rows:
        return False
    old = [r for a, r in rows if abs(a - AGE_OLD) < 1e-9]
    old_v = old[0] if old else sorted(rows)[-1][1]
    return bool(np.isfinite(s["med"]) and s["med"] < PRED_P4_MED
                and old_v < PRED_P4_OLD)


# ---------------------------------------------------------------- 入口
def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--csv", type=str, default=None,
                    help="26番の出力（既定 data/pwdb/pwdb_compare.csv があれば使う）")
    ap.add_argument("--section", type=str, default="AB",
                    choices=("A", "B", "C", "AB", "AC", "BC", "ABC"),
                    help="走らせる節（既定 AB。CSV が無ければ A だけ。C は --pwdb が要る）")
    ap.add_argument("--fast", action="store_true",
                    help="節A・節A-2 の掃引を減らす（自己検査と同じ。本番の表ではない）")
    ap.add_argument("--seed", type=int, default=SEED_A,
                    help="節A・節A-2 の雑音の乱数種")
    ap.add_argument("--pwdb", type=str, default=None,
                    help="PWDB の配布物を置いたフォルダ（節C に要る）")
    ap.add_argument("--limit", type=int, default=0,
                    help="節C で全体から等間隔に N 名だけ当てはめる（先頭 N 名ではない。0=全員）")
    ap.add_argument("--jobs", type=int, default=1, help="節C の並列数（26番と同じ）")
    ap.add_argument("--variants", type=str, default=",".join(VARIANTS_DEFAULT),
                    help="節C で当てる型（KINDS の鍵をコンマで並べる。既定 "
                         + ",".join(VARIANTS_DEFAULT) + "）")
    ap.add_argument("--b-stage", type=str, default=",".join(B_STAGE_DEFAULT),
                    help="節C の B 段でそろえる型（KINDS の鍵をコンマで並べる。既定 "
                         + ",".join(B_STAGE_DEFAULT)
                         + "）。B 段 = ここに挙げた型がすべて採用した共通例")
    ap.add_argument("--noise", type=float, default=0.0,
                    help="節C で拍に白色ガウス雑音を足す（峰から谷までの振幅に対する"
                         "標準偏差。既定 0.0 = 足さない）。記録は 50_refit_noiseSD.csv")
    ap.add_argument("--refit-csv", type=str, default=None,
                    help="節C の記録の場所（既定 data/pwdb/50_refit.csv。--limit なら"
                         " 50_refit_limitN.csv、--noise なら 50_refit_noiseSD.csv）")
    ap.add_argument("--no-resume", action="store_true",
                    help="節C で記録を使わずに全員当てはめ直す（既定は再開する。"
                         "上書きの前に 50_refit.csv.bak-日時 へ退避する）")
    ap.add_argument("--selftest", action="store_true",
                    help="合成だけで計算の筋道を検算する（CSV もネットワークも要らない）")
    args = ap.parse_args()

    if args.selftest:
        sys.exit(selftest())
    if args.jobs < 1:
        ap.error("--jobs は 1 以上")
    if args.limit < 0:
        ap.error("--limit は 0 以上（0 = 全員）")
    if args.noise < 0:
        ap.error("--noise は 0 以上（0 = 雑音を足さない）")
    variants = tuple(v.strip() for v in args.variants.split(",") if v.strip())
    bad = [v for v in variants if v not in KIND_KEYS]
    if bad:
        ap.error(f"--variants に知らない型がある: {bad}（使えるのは {list(KIND_KEYS)}）")
    b_variants = tuple(v.strip() for v in args.b_stage.split(",") if v.strip())
    bad_b = [v for v in b_variants if v not in KIND_KEYS]
    if bad_b:
        ap.error(f"--b-stage に知らない型がある: {bad_b}（使えるのは {list(KIND_KEYS)}）")
    if not b_variants:
        ap.error("--b-stage には 1 つ以上の型が要る（B 段はそろえる相手を決める指定である）")

    want_b = "B" in args.section
    want_c = "C" in args.section
    if want_c and not args.pwdb:
        print_no_pwdb()
        sys.exit(2)

    d, src = None, ""
    if want_b or want_c:
        p = Path(args.csv) if args.csv else DEFAULT_CSV
        if not p.exists() and not p.is_absolute():
            p = ROOT / str(args.csv)
        if p.exists():
            d, src = pd.read_csv(p), str(p)
        elif args.csv:
            if want_b:
                print(f"\n{args.csv} が無い。26番（26_pwdb_compare.py）の出力が要る。")
                print("確認的解析を回した機械には data/pwdb/pwdb_compare.csv がある"
                      "（4,374 行）。")
                sys.exit(2)
            print(f"\n{args.csv} が無い。節C の C0 の照合と参考行は飛ばす。")
        elif want_b and want_c:
            print(f"\n{DEFAULT_CSV} が無いので節B は走らせない"
                  "（節B は --csv で 26番の出力を渡す）。")
            args.section = args.section.replace("B", "")
        elif want_b:
            print(f"\n{DEFAULT_CSV} が無いので節A だけを走らせる"
                  "（節B は --csv で 26番の出力を渡す）。")
            args.section = args.section.replace("B", "") or "A"

    taus = TAUS_FAST if args.fast else TAUS_FULL
    dts = DTS_FAST if args.fast else DTS_FULL
    ris = RIS_FAST if args.fast else RIS_FULL
    if args.fast:
        print("\n  ★ --fast: 節A・節A-2 の掃引を減らしている。**本番の表ではない。**")
    out = report(args.section, d, src, taus=taus, dts=dts, ris=ris, seed=args.seed,
                 pwdb=args.pwdb, limit=args.limit, jobs=args.jobs, variants=variants,
                 refit_csv=args.refit_csv, resume=not args.no_resume,
                 b_variants=b_variants, noise_sd=args.noise)
    sys.exit(out["code"])


if __name__ == "__main__":
    main()
